// Improved Express.js application with comprehensive error handling and security
// Security best practices implementation

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const morgan = require('morgan');
const winston = require('winston');

// Initialize Express app
const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// 1. Set security HTTP headers using helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'"],
      fontSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      scriptSrc: ["'self'"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  },
  frameguard: { action: 'deny' }, // Prevent clickjacking
  noSniff: true, // Prevent MIME type sniffing
  xssFilter: true // Enable XSS filter
}));

// 2. Configure CORS
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000', 'http://localhost:3001'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
}));

// 3. Rate limiting - prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiting to all requests
app.use(limiter);

// 4. Request logging
app.use(morgan('combined', {
  skip: (req, res) => process.env.NODE_ENV === 'test'
}));

// 5. Body parsing with size limits
app.use(express.json({
  limit: '1mb', // Prevent large payload attacks
  verify: (req, res, buf) => {
    try {
      JSON.parse(buf);
    } catch (e) {
      throw new Error('Invalid JSON payload');
    }
  }
}));

app.use(express.urlencoded({
  extended: true,
  limit: '1mb',
  parameterLimit: 50 // Limit number of parameters
}));

// ==================== LOGGING SETUP ====================

// Configure Winston logger
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console({
      format: winston.format.combine(
        winston.format.colorize(),
        winston.format.simple()
      )
    }),
    new winston.transports.File({ 
      filename: 'error.log', 
      level: 'error' 
    }),
    new winston.transports.File({ 
      filename: 'combined.log' 
    }),
  ],
});

// ==================== VALIDATION HELPER FUNCTIONS ====================

/**
 * Sanitize and validate input
 */
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;

  // Basic XSS prevention
  return input
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;');
};

/**
 * Validate email format
 */
const isValidEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

/**
 * Validate user ID
 */
const isValidUserId = (id) => {
  return Number.isInteger(id) && id > 0;
};

// ==================== ROUTES WITH VALIDATION ====================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memoryUsage: process.memoryUsage()
    });
  } catch (error) {
    logger.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error during health check' 
    });
  }
});

// Users endpoint with input validation
app.get('/users', 
  // Input validation middleware
  [
    body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
    body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    body('search').optional().isString().trim().escape()
  ],
  async (req, res) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          errors: errors.array(),
          message: 'Validation failed' 
        });
      }

      // Get and sanitize query parameters
      const { page = 1, limit = 10, search = '' } = req.query;
      const sanitizedSearch = sanitizeInput(search.toString());

      // Validate pagination parameters
      const pageNum = parseInt(page);
      const limitNum = parseInt(limit);

      if (isNaN(pageNum) || pageNum < 1) {
        return res.status(400).json({ 
          message: 'Invalid page number' 
        });
      }

      if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
        return res.status(400).json({ 
          message: 'Limit must be between 1 and 100' 
        });
      }

      // Simulate database query with validation
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ].filter(user => 
        sanitizedSearch === '' || 
        user.name.toLowerCase().includes(sanitizedSearch.toLowerCase()) ||
        user.email.toLowerCase().includes(sanitizedSearch.toLowerCase())
      );

      // Paginate results
      const startIndex = (pageNum - 1) * limitNum;
      const endIndex = pageNum * limitNum;
      const paginatedUsers = users.slice(startIndex, endIndex);

      res.json({
        data: paginatedUsers,
        pagination: {
          currentPage: pageNum,
          totalPages: Math.ceil(users.length / limitNum),
          totalItems: users.length,
          itemsPerPage: limitNum
        }
      });

    } catch (error) {
      logger.error('Error fetching users:', error);
      res.status(500).json({ 
        message: 'Internal server error',
        error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }
);

// User creation endpoint with comprehensive validation
app.post('/users',
  [
    body('name')
      .trim()
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters')
      .matches(/^[a-zA-Z\s]*$/).withMessage('Name can only contain letters and spaces'),

    body('email')
      .trim()
      .notEmpty().withMessage('Email is required')
      .isEmail().withMessage('Invalid email format')
      .customSanitizer(value => value.toLowerCase()),

    body('password')
      .notEmpty().withMessage('Password is required')
      .isLength({ min: 8 }).withMessage('Password must be at least 8 characters')
      .matches(/\d/).withMessage('Password must contain at least one number')
      .matches(/[a-zA-Z]/).withMessage('Password must contain at least one letter'),

    body('role')
      .optional()
      .isIn(['user', 'admin']).withMessage('Role must be either "user" or "admin"')
  ],
  async (req, res) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          errors: errors.array(),
          message: 'Validation failed'
        });
      }

      const { name, email, password, role = 'user' } = req.body;

      // Additional business logic validation
      if (!isValidEmail(email)) {
        return res.status(400).json({
          message: 'Invalid email format'
        });
      }

      // In a real application, you would:
      // 1. Hash the password
      // 2. Check if email already exists
      // 3. Create user in database

      logger.info(`New user created: ${email}`);

      res.status(201).json({
        message: 'User created successfully',
        userId: 3, // In real app, return the actual ID
        email: email
      });

    } catch (error) {
      logger.error('Error creating user:', error);
      if (error.code === '23505') { // PostgreSQL unique violation
        return res.status(409).json({
          message: 'User with this email already exists'
        });
      }
      res.status(500).json({
        message: 'Internal server error'
      });
    }
  }
);

// ==================== ERROR HANDLING MIDDLEWARE ====================

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    message: 'Route not found',
    path: req.path,
    method: req.method
  });
});

// Global error handler
app.use((error, req, res, next) => {
  logger.error('Unhandled error:', {
    error: error.message,
    stack: error.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    userAgent: req.get('user-agent')
  });

  const statusCode = error.statusCode || 500;
  const response = {
    message: 'An unexpected error occurred',
    requestId: req.id || Date.now().toString(36)
  };

  // Only show error details in development
  if (process.env.NODE_ENV === 'development') {
    response.error = error.message;
    response.stack = error.stack;
  }

  res.status(statusCode).json(response);
});

// ==================== SERVER SETUP ====================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Graceful shutdown handling
const shutdown = (signal) => {
  logger.info(`${signal} received. Starting graceful shutdown...`);

  setTimeout(() => {
    logger.info('Forcefully shutting down');
    process.exit(1);
  }, 10000).unref();

  // Close server
  server.close(() => {
    logger.info('HTTP server closed');
    // Close database connections, Redis connections, etc. here
    process.exit(0);
  });
};

// Start server
const server = app.listen(PORT, () => {
  logger.info(`Server running in ${NODE_ENV} mode on port ${PORT}`);
});

// Handle graceful shutdown
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Handle unhandled rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception:', error);
  process.exit(1);
});

module.exports = app;

