// Test DNS resolution
async function testDNS(hostname) {
  return new Promise((resolve) => {
    dns.resolve4(hostname, (err, addresses) => {
      if (err) {
        resolve({ resolved: false, error: err.message });
      } else {
        resolve({ resolved: true, addresses });
      }
    });
  });
}

// Test TCP connectivity
async function testTCP(host, port, timeout = 5000) {
  return new Promise((resolve) => {
    const socket = new net.Socket();
    let timedOut = false;

    const timer = setTimeout(() => {
      timedOut = true;
      socket.destroy();
      resolve({ connected: false, error: 'Timeout after ' + timeout + 'ms' });
    }, timeout);

    socket.connect(port, host, () => {
      clearTimeout(timer);
      socket.end();
      resolve({ connected: true });
    });

    socket.on('error', (err) => {
      clearTimeout(timer);
      if (!timedOut) {
        resolve({ connected: false, error: err.message });
      }
    });
  });
}

// Test HTTPS connectivity
async function testHTTPS(host, timeout = 5000) {
  return new Promise((resolve) => {
    const options = {
      hostname: host,
      port: 443,
      path: '/',
      method: 'HEAD',
      timeout: timeout,
      rejectUnauthorized: false // For testing purposes only
    };

    const req = https.request(options, (res) => {
      resolve({ 
        connected: true, 
        statusCode: res.statusCode,
        headers: res.headers 
      });
    });

    req.on('timeout', () => {
      req.destroy();
      resolve({ connected: false, error: 'Timeout after ' + timeout + 'ms' });
    });

    req.on('error', (err) => {
      resolve({ connected: false, error: err.message });
    });

    req.end();
  });
}

