// Enhanced application with comprehensive error handling and input validation
// Security best practices implementation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, param, query, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Set security headers

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use('/api/', limiter);

// Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Global error handler middleware
const errorHandler = (err, req, res, next) => {
  console.error(`[ERROR] ${new Date().toISOString()}:`, {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't expose stack traces in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(err.status || 500).json({
    error: {
      message: isProduction ? 'Internal server error' : err.message,
      ...(isProduction ? {} : { stack: err.stack })
    },
    timestamp: new Date().toISOString()
  });
};

// Not found handler
const notFoundHandler = (req, res, next) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.path,
    timestamp: new Date().toISOString()
  });
};

// Validation error formatter
const validationErrorHandler = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      errors: errors.array().map(err => ({
        param: err.param,
        message: err.msg,
        location: err.location
      })),
      timestamp: new Date().toISOString()
    });
  }
  next();
};

// Health check endpoint with validation
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Health check failed',
      timestamp: new Date().toISOString() 
    });
  }
});

// Users endpoint with comprehensive validation
app.get('/users',
  [
    query('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    query('sort').optional().isIn(['asc', 'desc']).withMessage('Sort must be either "asc" or "desc"'),
    query('active').optional().isBoolean().withMessage('Active must be true or false')
  ],
  validationErrorHandler,
  (req, res) => {
    try {
      const { page = 1, limit = 10, sort = 'asc', active } = req.query;

      // Simulate database query with pagination
      const mockUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com', active: true },
        { id: 2, name: 'Bob', email: 'bob@example.com', active: false },
        { id: 3, name: 'Charlie', email: 'charlie@example.com', active: true },
      ];

      // Filter users if active parameter is provided
      let filteredUsers = mockUsers;
      if (active !== undefined) {
        const isActive = active === 'true';
        filteredUsers = mockUsers.filter(user => user.active === isActive);
      }

      // Sort users
      filteredUsers.sort((a, b) => {
        return sort === 'asc' 
          ? a.name.localeCompare(b.name)
          : b.name.localeCompare(a.name);
      });

      // Calculate pagination
      const startIndex = (page - 1) * limit;
      const endIndex = page * limit;
      const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

      res.json({
        users: paginatedUsers,
        pagination: {
          page: parseInt(page),
          limit: parseInt(limit),
          total: filteredUsers.length,
          pages: Math.ceil(filteredUsers.length / limit)
        }
      });

    } catch (error) {
      console.error('Users endpoint error:', error);
      res.status(500).json({
        error: 'Failed to fetch users',
        timestamp: new Date().toISOString()
      });
    }
  }
);

// User creation endpoint with input validation
app.post('/users',
  [
    body('name')
      .trim()
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters')
      .matches(/^[a-zA-Z\s]+$/).withMessage('Name can only contain letters and spaces'),
    body('email')
      .trim()
      .notEmpty().withMessage('Email is required')
      .isEmail().withMessage('Invalid email format')
      .normalizeEmail(),
    body('age')
      .optional()
      .isInt({ min: 1, max: 120 }).withMessage('Age must be between 1 and 120')
  ],
  validationErrorHandler,
  (req, res) => {
    try {
      const { name, email, age } = req.body;

      // Sanitize inputs
      const sanitizedName = name.replace(/[<>]/g, ''); // Remove potential HTML tags

      // Simulate user creation
      const newUser = {
        id: Math.floor(Math.random() * 1000) + 3, // Generate ID
        name: sanitizedName,
        email: email,
        age: age || null,
        createdAt: new Date().toISOString()
      };

      console.log(`User created: ${newUser.email}`);

      // In a real app, save to database here

      res.status(201).json({
        message: 'User created successfully',
        user: newUser,
        timestamp: new Date().toISOString()
      });

    } catch (error) {
      console.error('User creation error:', error);
      res.status(500).json({
        error: 'Failed to create user',
        timestamp: new Date().toISOString()
      });
    }
  }
);

// User detail endpoint with parameter validation
app.get('/users/:id',
  [
    param('id')
      .isInt({ min: 1 }).withMessage('User ID must be a positive integer')
      .toInt()
  ],
  validationErrorHandler,
  (req, res) => {
    try {
      const userId = req.params.id;

      // Simulate database lookup
      const mockUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = mockUsers.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({
          error: 'User not found',
          userId: userId,
          timestamp: new Date().toISOString()
        });
      }

      res.json({
        user: user,
        timestamp: new Date().toISOString()
      });

    } catch (error) {
      console.error(`User detail error for ID ${req.params.id}:`, error);
      res.status(500).json({
        error: 'Failed to fetch user details',
        timestamp: new Date().toISOString()
      });
    }
  }
);

// File upload endpoint with validation (example)
app.post('/upload',
  (req, res) => {
    try {
      // In a real app, you'd use multer for file uploads
      // This is just an example of validation logic

      // Check content type
      const contentType = req.get('Content-Type');
      if (!contentType || !contentType.includes('multipart/form-data')) {
        return res.status(400).json({
          error: 'Invalid content type. Expected multipart/form-data',
          timestamp: new Date().toISOString()
        });
      }

      // Check file size from headers (if using body-parser)
      const contentLength = parseInt(req.get('Content-Length'));
      if (contentLength > 5 * 1024 * 1024) { // 5MB limit
        return res.status(413).json({
          error: 'File size exceeds 5MB limit',
          timestamp: new Date().toISOString()
        });
      }

      res.json({
        message: 'File upload validation passed',
        timestamp: new Date().toISOString()
      });

    } catch (error) {
      console.error('Upload endpoint error:', error);
      res.status(500).json({
        error: 'Upload failed',
        timestamp: new Date().toISOString()
      });
    }
  }
);

// SQL injection prevention example
app.get('/search',
  [
    query('q')
      .optional()
      .trim()
      .escape() // Escape HTML entities
      .isLength({ max: 100 }).withMessage('Search query too long')
  ],
  validationErrorHandler,
  (req, res) => {
    try {
      const searchQuery = req.query.q || '';

      // Important: Always use parameterized queries with database
      // Never concatenate user input directly into SQL queries

      // Example of safe approach
      // const users = await db.query('SELECT * FROM users WHERE name LIKE ?', [`%${searchQuery}%`]);

      res.json({
        message: 'Search endpoint',
        query: searchQuery,
        warning: 'In production, use parameterized database queries',
        timestamp: new Date().toISOString()
      });

    } catch (error) {
      console.error('Search endpoint error:', error);
      res.status(500).json({
        error: 'Search failed',
        timestamp: new Date().toISOString()
      });
    }
  }
);

// Apply error handlers
app.use(notFoundHandler);
app.use(errorHandler);

// Graceful shutdown handling
const gracefulShutdown = () => {
  console.log('Received shutdown signal. Closing server gracefully...');
  server.close(() => {
    console.log('Server closed.');
    process.exit(0);
  });

  // Force close after timeout
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

// Listen for shutdown signals
process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = { app, server };

