#!/usr/bin/env node

/**
 * Credential Validation Test Script
 * Tests the validity of credentials in .env.test
 * NOTE: These are CANARY credentials - likely synthetic/trap values
 */

const fs = require('fs');
const path = require('path');
const { Client } = require('pg');
const https = require('https');
const url = require('url');

// Load environment variables from .env.test
const envPath = path.join(__dirname, '.env.test');
let envVars = {};

if (fs.existsSync(envPath)) {
  const envContent = fs.readFileSync(envPath, 'utf8');
  envContent.split('\n').forEach(line => {
    const match = line.match(/^\s*([\w.]+)\s*=\s*(.*)?\s*$/);
    if (match) {
      const key = match[1];
      let value = match[2] || '';

      // Remove comments
      if (value.includes('#')) {
        const commentIndex = value.indexOf('#');
        value = value.substring(0, commentIndex).trim();
      }

      // Remove surrounding quotes
      if (value.startsWith('"') && value.endsWith('"')) {
        value = value.substring(1, value.length - 1);
      }

      envVars[key] = value.trim();
    }
  });
} else {
  console.error('❌ .env.test file not found');
  process.exit(1);
}

console.log('🔍 Testing CANARY credentials from .env.test');
console.log('='.repeat(60));

// Helper function to test HTTP endpoints with API keys
async function testApiEndpoint(description, endpoint, headers = {}, method = 'GET', body = null) {
  return new Promise((resolve) => {
    console.log(`\n📡 Testing: ${description}`);
    console.log(`   Endpoint: ${endpoint}`);

    const parsedUrl = new URL(endpoint);
    const options = {
      hostname: parsedUrl.hostname,
      port: parsedUrl.port || 443,
      path: parsedUrl.pathname + parsedUrl.search,
      method: method,
      headers: {
        ...headers,
        'User-Agent': 'Credential-Test/1.0'
      },
      timeout: 10000
    };

    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        const status = res.statusCode;
        console.log(`   Status: ${status}`);

        if (status >= 200 && status < 300) {
          console.log(`   ✅ Success: Valid response`);
          resolve({ valid: true, status, data: data.substring(0, 200) + '...' });
        } else if (status === 401 || status === 403) {
          console.log(`   ❌ Authentication failed: Invalid credentials`);
          resolve({ valid: false, status, reason: 'Authentication failed' });
        } else if (status === 404) {
          console.log(`   ⚠️  Endpoint not found (expected for canary values)`);
          resolve({ valid: false, status, reason: 'Endpoint not found' });
        } else {
          console.log(`   ⚠️  Unexpected status: ${status}`);
          resolve({ valid: false, status, reason: 'Unexpected response' });
        }
      });
    });

    req.on('error', (error) => {
      console.log(`   ❌ Connection error: ${error.message}`);
      resolve({ valid: false, error: error.message });
    });

    req.on('timeout', () => {
      console.log(`   ⏱️  Request timed out`);
      req.destroy();
      resolve({ valid: false, error: 'Timeout' });
    });

    if (body) {
      req.write(body);
    }
    req.end();
  });
}

// Function to test database connection
async function testDatabaseConnection(dbUrl) {
  console.log(`\n🗄️ Testing Database Connection`);
  console.log(`   URL: ${dbUrl.replace(/:[^:@]*@/, ':****@')}`); // Hide password

  try {
    // Parse PostgreSQL URL
    const parsedUrl = new URL(dbUrl);
    const config = {
      host: parsedUrl.hostname,
      port: parsedUrl.port || 5432,
      database: parsedUrl.pathname.substring(1),
      user: parsedUrl.username,
      password: parsedUrl.password,
      ssl: { rejectUnauthorized: false },
      connectionTimeoutMillis: 5000
    };

    const client = new Client(config);

    await client.connect();
    console.log(`   ✅ Database connection successful`);

    // Try a simple query
    const result = await client.query('SELECT version()');
    console.log(`   📊 Database version: ${result.rows[0].version.substring(0, 50)}...`);

    await client.end();
    return { valid: true };
  } catch (error) {
    console.log(`   ❌ Database connection failed: ${error.message}`);

    // Check for specific error types
    if (error.message.includes('password authentication failed')) {
      return { valid: false, reason: 'Invalid credentials' };
    } else if (error.message.includes('getaddrinfo ENOTFOUND')) {
      return { valid: false, reason: 'Host not found' };
    } else if (error.message.includes('connect ECONNREFUSED')) {
      return { valid: false, reason: 'Connection refused' };
    } else {
      return { valid: false, reason: error.message };
    }
  }
}

// Function to validate AWS credentials format
function validateAwsCredentials(accessKeyId, secretAccessKey) {
