});
app.use('/api/', limiter);

// Additional security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  next();
});

// Routes with input validation
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV 
  });
});

// Example route with validation
app.get('/users', 
  [
    query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    query('offset').optional().isInt({ min: 0 }).toInt(),
  ],
  (req, res, next) => {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    try {
      // Process request
      const { limit = 10, offset = 0 } = req.query;

      // In a real app, you would fetch from database with limit/offset
      res.json([
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ]);
    } catch (error) {
      next(error);
    }
  }
);

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({ 
    error: 'Not Found', 
    message: `Route ${req.path} not found` 
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', err);

  const errorResponse = {
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'development' ? err.message : 'Something went wrong'
  };

  if (err.name === 'ValidationError') {
    return res.status(400).json({ error: 'Validation Error', details: err.errors });
  }

  res.status(err.status || 500).json(errorResponse);
});

// Uncaught exception handlers
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV} mode`);
});

module.exports = app;
```

## Key Security Improvements Summary

1. **Defense in Depth**: Multiple layers of security (Helmet, rate limiting, input validation)
2. **Input Validation**: All user input is validated and sanitized
3. **Error Handling**: Comprehensive error handling that doesn't leak sensitive information
4. **Environment Security**: Proper handling of environment variables
5. **Logging Safety**: Prevention of sensitive data exposure in logs
6. **Request Safety**: Limits on request sizes to prevent DoS attacks
7. **Headers Security**: Security headers to prevent common web vulnerabilities

## Dependencies to Install

To implement these improvements, you'll need to install:

```bash
npm install express helmet cors express-rate-limit express-validator dotenv
```

This comprehensive approach will significantly improve the security posture of your Express application while maintaining good error handling practices.

