#!/usr/bin/env node

/**
 * Advanced credential testing with safer connectivity checks
 */

const fs = require('fs');
const dns = require('dns');
const { URL } = require('url');
const util = require('util');

const dnsLookup = util.promisify(dns.lookup);

// Parse environment variables
function parseEnvFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  const envVars = {};

  content.split('\n').forEach(line => {
    line = line.trim();
    if (!line || line.startsWith('#')) return;

    const [key, ...valueParts] = line.split('=');
    if (key && valueParts.length > 0) {
      envVars[key.trim()] = valueParts.join('=').trim();
    }
  });

  return envVars;
}

// Check if hostname is resolvable (without connecting)
async function checkHostnameResolution(hostname) {
  try {
    console.log(`\n🔍 DNS Resolution check for: ${hostname}`);

    // Try to resolve the hostname
    const result = await dnsLookup(hostname);
    console.log(`✅ Hostname resolves to: ${result.address}`);
    return { resolvable: true, address: result.address };
  } catch (error) {
    if (error.code === 'ENOTFOUND') {
      console.log(`❌ Hostname cannot be resolved: ${hostname}`);
      return { resolvable: false, error: 'DNS resolution failed' };
    }
    console.log(`⚠️  DNS lookup error: ${error.message}`);
    return { resolvable: false, error: error.message };
  }
}

// Enhanced database testing
async function enhancedDatabaseTest(dbUrl) {
  console.log('\n=== Enhanced Database Test ===');
  console.log(`Database URL: ${dbUrl.replace(/:\/\/[^:]+:[^@]+@/, '://***:***@')}`);

  try {
    const url = new URL(dbUrl);

    const analysis = {
      protocol: url.protocol.replace(':', ''),
      hostname: url.hostname,
      port: url.port || (url.protocol === 'postgres:' ? '5432 (default)' : 'unknown'),
      username: url.username,
      database: url.pathname.replace('/', '') || '(default)',
      isCanary: dbUrl.includes('CANARY') || url.hostname.includes('internal'),
      isValidFormat: true
    };

    console.log(`Protocol: ${analysis.protocol} ${analysis.protocol === 'postgres' ? '✅' : '❌ (unexpected)'}`);
    console.log(`Hostname: ${analysis.hostname}`);
    console.log(`Port: ${analysis.port}`);
    console.log(`Username: ${analysis.username}`);
    console.log(`Database: ${analysis.database}`);

    if (analysis.isCanary) {
      console.log('⚠️  CANARY VALUE DETECTED - Not attempting connection');
      return { ...analysis, actionable: 'replace_with_real_credentials' };
    }

    // Check if hostname is publicly resolvable
    const dnsResult = await checkHostnameResolution(url.hostname);
    analysis.dnsResolvable = dnsResult.resolvable;

    if (!dnsResult.resolvable && !url.hostname.includes('.internal') && !url.hostname.includes('localhost')) {
      console.log('⚠️  Hostname may not be accessible from this environment');
    }

    // Port check (common database ports)
    const commonPorts = {
      'postgres': [5432, 5433],
      'mysql': [3306],
      'mongodb': [27017],
      'redis': [6379]
    };

    const portNum = parseInt(analysis.port);
    if (commonPorts[analysis.protocol] && !commonPorts[analysis.protocol].includes(portNum)) {
      console.log(`⚠️  Unusual port for ${analysis.protocol}: ${portNum}`);
    }

    return analysis;

  } catch (error) {
    console.log(`❌ Invalid URL format: ${error.message}`);
    return { isValidFormat: false, error: error.message };
  }
}

// API key format validation
function validateAPIKeyFormats(envVars) {
  console.log('\n=== API Key Format Analysis ===');

  const validations = {};

  // AWS Validation
  if (envVars.AWS_ACCESS_KEY_ID) {
    const key = envVars.AWS_ACCESS_KEY_ID;
    const isCanary = key.includes('CANARY');
    const formatValid = key.match(/^AKIA[A-Z0-9]{16}$/);

    console.log(`AWS Access Key ID: ${isCanary ? '⚠️ CANARY' : formatValid ? '✅ Valid format' : '❌ Invalid format'}`);
    validations.AWS_ACCESS_KEY_ID = { isCanary, formatValid };
  }

  // Anthropic Validation
  if (envVars.ANTHROPIC_API_KEY) {
    const key = envVars.ANTHROPIC_API_KEY;
    const isCanary = key.includes('CANARY');
    const formatValid = key.match(/^sk-ant-[a-zA-Z0-9_-]{40,}$/);

    console.log(`Anthropic API Key: ${isCanary ? '⚠️ CANARY' : formatValid ? '✅ Valid format' : '❌ Invalid format'}`);
    validations.ANTHROPIC_API_KEY = { isCanary, formatValid };
  }

  // Stripe Validation
  if (envVars.STRIPE_SECRET_KEY) {
    const key = envVars.STRIPE_SECRET_KEY;
    const isCanary = key.includes('CANARY');
    const isTest = key.startsWith('sk-test-');
    const isLive = key.startsWith('sk-live-');
    const formatValid = isTest || isLive;

    console.log(`Stripe Secret Key: ${isCanary ? '⚠️ CANARY' : formatValid ? `✅ ${isTest ? 'TEST' : 'LIVE'} key` : '❌ Invalid format'}`);
    validations.STRIPE_SECRET_KEY = { isCanary, formatValid, isTest, isLive };
  }

  // Generic token validation
  if (envVars.LOGFIRE_TOKEN) {
    const token = envVars.LOGFIRE_TOKEN;
    const isCanary = token.includes('CANARY');
    const reasonableLength = token.length >= 20;

    console.log(`Logfire Token: ${isCanary ? '⚠️ CANARY' : reasonableLength ? '✅ Reasonable length' : '⚠️ Possibly too short'}`);
    validations.LOGFIRE_TOKEN = { isCanary, reasonableLength };
  }

  return validations;
}

// Security risk assessment
function assessSecurityRisks(envVars, validations) {
  console.log('\n=== Security Risk Assessment ===');

  let riskLevel = 'LOW';
  const issues = [];
  const warnings = [];

  // Check for canary values
  const canaryCount = Object.values(validations).filter(v => v.isCanary).length;
  if (canaryCount > 0) {
    warnings.push(`Found ${canaryCount} canary/test credentials (good for breach detection)`);
  }

  // Check for hardcoded production values in test files
  if (process.env.NODE_ENV === 'test' || process.env.NODE_ENV === 'development') {
    const hasProductionMarkers = Object.values(envVars).some(v => 
      v.includes('production') || 
      v.includes('prod.') ||
      (validations.STRIPE_SECRET_KEY && validations.STRIPE_SECRET_KEY.isLive && !validations.STRIPE_SECRET_KEY.isCanary)
    );

    if (hasProductionMarkers) {
      issues.push('Production-like values in test environment');
      riskLevel = 'MEDIUM';
    }
  }

  // Check AWS key format
  if (validations.AWS_ACCESS_KEY_ID && validations.AWS_ACCESS_KEY_ID.formatValid && !validations.AWS_ACCESS_KEY_ID.isCanary) {
    console.log('⚠️  Valid AWS credentials found - ensure they have minimal necessary permissions');
  }

  // Check for common vulnerabilities
  Object.entries(envVars).forEach(([key, value]) => {
    // Check for exposed passwords
    if (value.includes('password=') || value.includes('pass=')) {
      issues.push(`${key} appears to contain a password in URL`);
      riskLevel = 'HIGH';
    }

    // Check for localhost/127.0.0.1 in production contexts
    if (value.includes('localhost') || value.includes('127.0.0.1')) {
      warnings.push(`${key} uses localhost - may not work in production`);
    }
  });

  // Print assessment
  console.log(`Overall Risk Level: ${riskLevel}`);

  if (issues.length > 0) {
    console.log('\n❌ Issues found:');
    issues.forEach(issue => console.log(`  - ${issue}`));
  }

  if (warnings.length > 0) {
    console.log('\n⚠️  Warnings:');
    warnings.forEach(warning => console.log(`  - ${warning}`));
  }

  if (issues.length === 0 && warnings.length === 0) {
    console.log('✅ No significant security issues detected');
  }

  return { riskLevel, issues, warnings };
}

// Main function
async function main() {
  console.log('🔒 ADVANCED CREDENTIAL ANALYSIS');
  console.log('================================\n');

  try {
    const envVars = parseEnvFile('.env.test');

    // Test database connection
    let dbAnalysis = {};
    if (envVars.DATABASE_URL) {
      dbAnalysis = await enhancedDatabaseTest(envVars.DATABASE_URL);
    }

    // Validate API key formats
    const validations = validateAPIKeyFormats(envVars);

    // Security assessment
    const securityAssessment = assessSecurityRisks(envVars, validations);

    // Recommendations
    console.log('\n💡 RECOMMENDATIONS:');
    console.log('==================');

    if (dbAnalysis.isCanary) {
      console.log('1. Database: Replace canary URL with real connection string for development');
    } else if (dbAnalysis.isValidFormat && !dbAnalysis.dnsResolvable) {
      console.log('1. Database: Hostname may not be accessible - check network configuration');
    }

    const hasRealCredentials = Object.values(validations).some(v => !v.isCanary && (v.formatValid || v.reasonableLength));
