#!/usr/bin/env node

/**
 * Simple connectivity test for database hostname
 * This does NOT use the actual credentials or attempt to connect
 */

const dns = require('dns');
const util = require('util');

const dnsLookup = util.promisify(dns.lookup);
const dnsResolve = util.promisify(dns.resolve);

async function testHostnameConnectivity(hostname) {
  console.log(`\n🔍 Testing connectivity to: ${hostname}`);

  try {
    // Try basic DNS lookup
    const lookupResult = await dnsLookup(hostname);
    console.log(`✅ DNS Lookup successful: ${hostname} -> ${lookupResult.address}`);

    // Try to get more DNS records
    try {
      const mxRecords = await dnsResolve(hostname, 'MX').catch(() => []);
      const txtRecords = await dnsResolve(hostname, 'TXT').catch(() => []);

      console.log(`\n📡 Additional DNS info:`);
      if (mxRecords.length > 0) console.log(`   MX Records: ${mxRecords.length}`);
      if (txtRecords.length > 0) console.log(`   TXT Records: ${txtRecords.length}`);
    } catch (dnsError) {
      // It's normal for internal hosts to not have these records
    }

    return { success: true, address: lookupResult.address };
  } catch (error) {
    console.log(`❌ DNS Lookup failed: ${error.message}`);

    // Check if it's an internal hostname
    if (hostname.includes('.internal') || 
        hostname.includes('.local') || 
        hostname === 'localhost') {
      console.log(`ℹ️  ${hostname} appears to be an internal/private hostname`);
      console.log(`   This is normal for development environments`);
      return { success: false, internal: true, error: error.message };
    }

    return { success: false, error: error.message };
  }
}

async function testPortAvailability(hostname, port) {
  console.log(`\n🔌 Checking if port ${port} might be open on ${hostname}...`);

  // Note: We don't actually try to connect, just analyze
  const commonDatabasePorts = {
    5432: 'PostgreSQL',
    3306: 'MySQL/MariaDB',
    27017: 'MongoDB',
    6379: 'Redis',
    1433: 'Microsoft SQL Server',
    1521: 'Oracle'
  };

  if (commonDatabasePorts[port]) {
    console.log(`ℹ️  Port ${port} is commonly used for ${commonDatabasePorts[port]}`);
  } else {
    console.log(`⚠️  Port ${port} is not a common database port`);
  }

  return { port, commonService: commonDatabasePorts[port] || 'Unknown' };
}

async function analyzeDatabaseUrl(dbUrl) {
  console.log('=== Database URL Analysis ===');
  console.log(`URL: ${dbUrl.replace(/:\/\/[^:]+:[^@]+@/, '://***:***@')}`);

  try {
    const { URL } = require('url');
    const url = new URL(dbUrl);

    const hostname = url.hostname;
    const port = url.port || (url.protocol === 'postgres:' ? 5432 : null);

    // Test hostname resolution
    const connectivity = await testHostnameConnectivity(hostname);

    // Analyze port
    if (port) {
      await testPortAvailability(hostname, parseInt(port));
    }

    // Check for canary markers
    const isCanary = dbUrl.includes('CANARY') || 
                     url.username.includes('CANARY') || 
                     url.password.includes('CANARY');

    if (isCanary) {
      console.log('\n⚠️  CANARY CREDENTIALS DETECTED');
      console.log('   These are test/dummy values for security monitoring');
      console.log('   Do not use for actual database connections');
    }

    return {
      protocol: url.protocol.replace(':', ''),
      hostname,
      port,
      username: url.username,
      database: url.pathname.replace('/', ''),
      isCanary,
      connectivity
    };
  } catch (error) {
    console.log(`❌ Invalid URL format: ${error.message}`);
    return { error: error.message };
  }
}

// Test the actual database URL from .env.test
async function main() {
  const dbUrl = 'postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production';

  console.log('🧪 DATABASE CONNECTIVITY TEST');
  console.log('==============================');
  console.log('\nNOTE: This test only checks DNS resolution, NOT actual database connectivity');
  console.log('      No credentials are used and no database connection is attempted\n');

  const analysis = await analyzeDatabaseUrl(dbUrl);

  console.log('\n📊 SUMMARY:');
  console.log('===========');

  if (analysis.isCanary) {
    console.log('✅ Canary credentials detected (good for security monitoring)');
    console.log('⚠️  These are NOT real database credentials');
  } else if (analysis.connectivity.success) {
    console.log('✅ Hostname resolves successfully');
    console.log('⚠️  Still need to verify actual database connectivity');
  } else if (analysis.connectivity.internal) {
    console.log('ℹ️  Internal/private hostname (normal for development)');
    console.log('⚠️  May not be accessible from all environments');
  } else {
    console.log('❌ Hostname resolution failed');
    console.log('⚠️  Database may not be accessible');
  }

  console.log('\n🔒 SECURITY NOTES:');
  console.log('   • Never commit real credentials to version control');
  console.log('   • Use environment variables or secret managers');
  console.log('   • Canary credentials help detect credential leaks');
  console.log('   • Implement proper access controls for databases');
}

if (require.main === module) {
  main().catch(console.error);
}

module.exports = { analyzeDatabaseUrl };

