// Generate hash of credential metadata (for verification without exposing)
function generateCredentialMetadataHash(envVars) {
  const metadata = {
    count: Object.keys(envVars).length,
    services: Object.keys(envVars).map(key => {
      const value = envVars[key];
      return {
        key,
        length: value.length,
        contains_sensitive: value.includes('secret') || value.includes('key') || value.includes('token'),
        is_canary: value.includes('CANARY')
      };
    })
  };

  const hash = crypto.createHash('sha256')
    .update(JSON.stringify(metadata))
    .digest('hex');

  return { metadata, hash };
}

