    let encrypted = cipher.update(value, 'utf8', 'hex');
    encrypted += cipher.final('hex');
    const authTag = cipher.getAuthTag().toString('hex');
    return { encrypted, iv: this.iv.toString('hex'), authTag };
  }

  // This simulates what a proper secret manager would do
  static generateSecureBackupReference(envVars) {
