#!/usr/bin/env node

/**
 * Credential Verification Script
 * 
 * WARNING: Testing actual connectivity with potentially valid credentials
 * can trigger security alerts and should only be done in a controlled
 * environment with proper authorization.
 */

const fs = require('fs');
const https = require('https');
const { spawn } = require('child_process');

class CredentialVerifier {
  constructor() {
    this.results = {
      verified: [],
      failed: [],
      warnings: [],
      skipped: []
    };
  }

  async verifyAll() {
    console.log('🔍 Starting credential verification...\n');

    // Read credentials from .env.test
    const credentials = this.readCredentials();
    console.log(`📄 Found ${Object.keys(credentials).length} credentials to verify\n`);

    // 1. Check Database URL
    await this.verifyDatabase(credentials.DATABASE_URL);

    // 2. Check AWS Credentials (format only, no API calls)
    this.verifyAWSCredentials(credentials);

    // 3. Check Anthropic API Key (format only)
    this.verifyAPIKeyFormat('ANTHROPIC_API_KEY', credentials.ANTHROPIC_API_KEY);

    // 4. Check Stripe Secret Key (format only)
    this.verifyStripeKey(credentials.STRIPE_SECRET_KEY);

    // 5. Check Logfire Token
    this.verifyTokenFormat('LOGFIRE_TOKEN', credentials.LOGFIRE_TOKEN);

    // Print summary
    this.printSummary();
  }

  readCredentials() {
    try {
      const envContent = fs.readFileSync('.env.test', 'utf8');
      const credentials = {};

      envContent.split('\n').forEach(line => {
        // Skip comments and empty lines
        if (line.trim() && !line.trim().startsWith('#')) {
          const [key, ...valueParts] = line.split('=');
          if (key && valueParts.length > 0) {
            credentials[key.trim()] = valueParts.join('=').trim();
          }
        }
      });

      return credentials;
    } catch (error) {
      console.error('❌ Error reading .env.test:', error.message);
      process.exit(1);
    }
  }

  async verifyDatabase(databaseUrl) {
    console.log('1. 📊 Testing Database URL...');

    if (!databaseUrl) {
      this.results.skipped.push('DATABASE_URL: No URL provided');
      console.log('   ⚠️  No DATABASE_URL found\n');
      return;
    }

    console.log(`   URL: ${this.maskSensitiveParts(databaseUrl)}`);

    // Parse the URL
    try {
      const url = new URL(databaseUrl);
      const protocol = url.protocol.replace(':', '');
      const hostname = url.hostname;
      const port = url.port;

      console.log(`   Protocol: ${protocol}`);
      console.log(`   Hostname: ${hostname}`);
      console.log(`   Port: ${port || 'default'}`);

      // Check for canary values
      if (databaseUrl.includes('CANARY')) {
        this.results.warnings.push('DATABASE_URL: Contains "CANARY" - likely a detection/trap value');
        console.log('   ⚠️  WARNING: Contains "CANARY" - may be a trap value');
      }

      // Test connectivity (with timeout and safe handling)
      console.log('   Testing connectivity...');

      return new Promise((resolve) => {
        // For PostgreSQL, we would typically use a client like pg
        // Since we don't want to install dependencies, we'll do a basic TCP check

