        socket.on('connect', () => {
          console.log(`   ✅ Successfully connected to ${hostname}:${connectPort}`);
          socket.destroy();
          this.results.verified.push(`DATABASE_URL: TCP connectivity to ${hostname}:${connectPort}`);
          resolve();
        });

        socket.on('timeout', () => {
          console.log(`   ⏱️  Connection timeout to ${hostname}:${connectPort}`);
          socket.destroy();
          this.results.failed.push(`DATABASE_URL: Connection timeout to ${hostname}:${connectPort}`);
          resolve();
        });

        socket.on('error', (err) => {
          console.log(`   ❌ Connection error to ${hostname}:${connectPort}: ${err.message}`);
          this.results.failed.push(`DATABASE_URL: Connection error - ${err.message}`);
          resolve();
        });

