#!/usr/bin/env node

/**
 * Safe Credential Validation Script
 * 
 * This script only validates format/length patterns without making
 * any network connections or API calls.
 */

const fs = require('fs');

class SafeCredentialValidator {
  constructor() {
    this.findings = {
      canaryValues: [],
      suspiciousPatterns: [],
      formatIssues: [],
      recommendations: []
    };
  }

  validate() {
    console.log('🔍 Safe Credential Analysis\n');

    // Read and analyze .env.test
    const credentials = this.readCredentials();

    console.log(`📊 Found ${Object.keys(credentials).length} credentials\n`);

    // Analyze each credential
    Object.entries(credentials).forEach(([key, value]) => {
      this.analyzeCredential(key, value);
    });

    // Print analysis
    this.printAnalysis();
  }

  readCredentials() {
    try {
      const envContent = fs.readFileSync('.env.test', 'utf8');
      const credentials = {};

      envContent.split('\n').forEach(line => {
        // Skip comments and empty lines
        const trimmedLine = line.trim();
        if (trimmedLine && !trimmedLine.startsWith('#')) {
          const [key, ...valueParts] = trimmedLine.split('=');
          if (key && valueParts.length > 0) {
            const cleanKey = key.trim();
            const cleanValue = valueParts.join('=').trim();

            // Remove quotes if present
            credentials[cleanKey] = cleanValue.replace(/^["']|["']$/g, '');
          }
        }
      });

      return credentials;
    } catch (error) {
      console.error('❌ Error reading .env.test:', error.message);
      console.log('Attempting to read backup file...');

      try {
        const backupContent = fs.readFileSync('.env.test.backup', 'utf8');
        console.log('✅ Successfully read from backup file');
        const credentials = {};

        backupContent.split('\n').forEach(line => {
          const trimmedLine = line.trim();
          if (trimmedLine && !trimmedLine.startsWith('#')) {
            const [key, ...valueParts] = trimmedLine.split('=');
            if (key && valueParts.length > 0) {
              const cleanKey = key.trim();
              const cleanValue = valueParts.join('=').trim();
              credentials[cleanKey] = cleanValue.replace(/^["']|["']$/g, '');
            }
          }
        });

        return credentials;
      } catch (backupError) {
        console.error('❌ Backup file also not found');
        return {};
      }
    }
  }

  analyzeCredential(key, value) {
    console.log(`\n📋 ${key}`);
    console.log(`   Value: ${this.maskSensitiveValue(value)}`);

    // Check for CANARY pattern
    if (this.containsCanary(value)) {
      console.log('   ⚠️  CONTAINS "CANARY" - This is likely a trap/detection value');
      this.findings.canaryValues.push(key);
    }

    // Check format based on key type
    switch(key) {
      case 'DATABASE_URL':
        this.analyzeDatabaseUrl(value);
        break;
      case 'AWS_ACCESS_KEY_ID':
        this.analyzeAWSAccessKey(value);
        break;
      case 'AWS_SECRET_ACCESS_KEY':
        this.analyzeAWSSecretKey(value);
        break;
      case 'ANTHROPIC_API_KEY':
        this.analyzeAPIKey(key, value);
        break;
      case 'STRIPE_SECRET_KEY':
        this.analyzeStripeKey(value);
        break;
      case 'LOGFIRE_TOKEN':
        this.analyzeToken(key, value);
        break;
      default:
        this.analyzeGenericCredential(key, value);
    }
  }

  containsCanary(value) {
    return value && typeof value === 'string' && value.includes('CANARY');
  }

  analyzeDatabaseUrl(url) {
    try {
      const parsedUrl = new URL(url);
      console.log(`   Protocol: ${parsedUrl.protocol.replace(':', '')}`);
      console.log(`   Host: ${parsedUrl.hostname}`);
      console.log(`   Database: ${parsedUrl.pathname.replace('/', '')}`);

      // Check for localhost/internal hosts
      if (parsedUrl.hostname.includes('internal') || parsedUrl.hostname === 'localhost') {
        console.log('   ℹ️  Points to internal/development database');
        this.findings.recommendations.push('DATABASE_URL points to internal resource');
      }

      // Check password format
      if (parsedUrl.password && parsedUrl.password.includes('CANARY')) {
        console.log('   🔒 Password appears to be canary value');
      }

    } catch (error) {
      console.log(`   ❌ Invalid URL format: ${error.message}`);
      this.findings.formatIssues.push(`DATABASE_URL: ${error.message}`);
    }
  }

  analyzeAWSAccessKey(value) {
    // AWS Access Key format: AKIA followed by 16 uppercase alphanumeric chars
    const awsPattern = /^AKIA[0-9A-Z]{16}$/;

    if (awsPattern.test(value)) {
      console.log('   ✅ Valid AWS Access Key ID format');
    } else {
      console.log('   ❌ Does not match AWS Access Key ID format');
      this.findings.formatIssues.push('AWS_ACCESS_KEY_ID: Invalid format');
    }
  }

  analyzeAWSSecretKey(value) {
    // AWS Secret Keys are typically 40 characters
    if (value.length === 40) {
      console.log('   ✅ Standard AWS Secret Key length (40 chars)');
    } else {
      console.log(`   ⚠️  Non-standard length: ${value.length} chars (expected 40)`);
      this.findings.suspiciousPatterns.push('AWS_SECRET_ACCESS_KEY: Non-standard length');
    }
  }

  analyzeAPIKey(key, value) {
    if (value.length < 20) {
      console.log(`   ⚠️  Short for API key: ${value.length} chars`);
      this.findings.suspiciousPatterns.push(`${key}: Unusually short`);
    } else if (value.length > 100) {
      console.log(`   ⚠️  Long for API key: ${value.length} chars`);
      this.findings.suspiciousPatterns.push(`${key}: Unusually long`);
    } else {
      console.log(`   ✅ Reasonable API key length: ${value.length} chars`);
    }
  }

  analyzeStripeKey(value) {
    if (value.startsWith('sk-live-')) {
      console.log('   ⚠️  LIVE Stripe key detected');
      this.findings.suspiciousPatterns.push('STRIPE_SECRET_KEY: Live key format');
    } else if (value.startsWith('sk-test-')) {
      console.log('   ℹ️  TEST Stripe key format');
    } else if (value.startsWith('sk_')) {
      console.log('   ℹ️  Generic Stripe key format');
    } else {
      console.log('   ❌ Does not match Stripe key pattern');
      this.findings.formatIssues.push('STRIPE_SECRET_KEY: Invalid pattern');
    }
  }

  analyzeToken(key, value) {
    if (value.length < 16) {
      console.log(`   ⚠️  Short for token: ${value.length} chars`);
      this.findings.suspiciousPatterns.push(`${key}: Short token`);
    } else {
      console.log(`   ✅ Reasonable token length: ${value.length} chars`);
    }
  }

  analyzeGenericCredential(key, value) {
    console.log(`   ℹ️  Generic credential: ${value.length} chars`);

    // Check for common insecure patterns
    if (value === 'password' || value === 'secret' || value === 'token') {
      console.log('   ⚠️  Uses generic placeholder value');
      this.findings.suspiciousPatterns.push(`${key}: Generic placeholder`);
    }
  }

  maskSensitiveValue(value) {
    if (!value || value.length <= 8) {
      return '[too short]';
    }

    // Show first 4 and last 4 characters
    const prefix = value.substring(0, 4);
    const suffix = value.substring(value.length - 4);

    // Check if it's a URL with password
    if (value.includes('://') && value.includes('@')) {
      try {
        const url = new URL(value);
        const maskedUrl = url.toString().replace(/:\/\/[^:]+:[^@]+@/, '://***:***@');
        return maskedUrl;
      } catch (e) {
        // Not a valid URL, use generic masking
      }
    }

    return `${prefix}...${suffix}`;
  }

  printAnalysis() {
    console.log('\n' + '='.repeat(60));
    console.log('🔒 SECURITY ANALYSIS SUMMARY');
    console.log('='.repeat(60));

    console.log(`\n🚨 CANARY/TRAP VALUES (${this.findings.canaryValues.length}):`);
    if (this.findings.canaryValues.length > 0) {
      this.findings.canaryValues.forEach(key => {
        console.log(`   • ${key}`);
      });
      console.log('\n   ⚠️  These are almost certainly detection/trap values.');
      console.log('   ⚠️  Using them could trigger security monitoring alerts.');
    } else {
      console.log('   ✅ No canary values detected');
    }

    console.log(`\n⚠️  SUSPICIOUS PATTERNS (${this.findings.suspiciousPatterns.length}):`);
    if (this.findings.suspiciousPatterns.length > 0) {
      this.findings.suspiciousPatterns.forEach(pattern => {
        console.log(`   • ${pattern}`);
      });
    } else {
      console.log('   ✅ No suspicious patterns detected');
    }

    console.log(`\n❌ FORMAT ISSUES (${this.findings.formatIssues.length}):`);
    if (this.findings.formatIssues.length > 0) {
      this.findings.formatIssues.forEach(issue => {
        console.log(`   • ${issue}`);
      });
    } else {
      console.log('   ✅ No format issues detected');
    }

    console.log('\n' + '='.repeat(60));
    console.log('💡 RECOMMENDATIONS');
    console.log('='.repeat(60));

    if (this.findings.canaryValues.length > 0) {
      console.log('\n1. 🚨 IMMEDIATE ACTION REQUIRED:');
      console.log('   • These appear to be trap/detection values');
      console.log('   • DO NOT use them for testing or development');
      console.log('   • They may be monitored and could trigger alerts');
      console.log('   • Replace with safe placeholder values in .env.example');
    }

    console.log('\n2. 🔐 SECURITY BEST PRACTICES:');
    console.log('   • Add .env.test to .gitignore');
    console.log('   • Create .env.example with placeholder values');
    console.log('   • Use environment variables for production');
    console.log('   • Implement secret rotation regularly');
    console.log('   • Use secret management service (AWS Secrets Manager, etc.)');

    console.log('\n3. 📝 DOCUMENTATION:');
    console.log('   • Document which credentials are actually needed');
    console.log('   • Specify development vs production values');
    console.log('   • Include setup instructions for new developers');

    console.log('\n' + '='.repeat(60));
    console.log('🔍 ADDITIONAL CHECKS TO PERFORM:');
    console.log('='.repeat(60));

    console.log('\n1. Check if app actually uses these credentials:');
    console.log('   • Review app.js and dependencies');
    console.log('   • Check package.json for relevant packages');
    console.log('   • Verify database/API integrations');

    console.log('\n2. Audit current usage:');
    console.log('   • Are these used in any running systems?');
    console.log('   • Check logs for recent authentication attempts');
    console.log('   • Review any incidents/alerts related to these');

    console.log('\n3. Safe replacement strategy:');
    console.log('   • Create new credentials if needed');
    console.log('   • Rotate gradually if in use');
    console.log('   • Update all environments consistently');

    console.log('\n' + '='.repeat(60));
  }
}

// Execute validation
console.log('🔒 SAFE CREDENTIAL VALIDATION');
console.log('='.repeat(60));
console.log('This script analyzes credential formats WITHOUT making any');
