module.exports = app;

/**
 * Enhanced Express.js application with comprehensive error handling
 * and input validation focused on security best practices
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
require('dotenv').config();

// Initialize Express application
const app = express();

// ========================
// SECURITY MIDDLEWARE
// ========================

// 1. Helmet.js for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  crossOriginEmbedderPolicy: false,
}));

// 2. CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
  credentials: true,
  maxAge: 86400, // 24 hours
}));

// 3. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
    status: 429
  },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 4. Body parsing with limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ========================
// LOGGING MIDDLEWARE
// ========================

app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log({
      timestamp: new Date().toISOString(),
      method: req.method,
      url: req.url,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('User-Agent')
    });
  });
  next();
});

// ========================
// INPUT VALIDATION UTILITIES
// ========================

const validate = validations => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));
    const errors = validationResult(req);
    if (errors.isEmpty()) {
      return next();
    }
    res.status(400).json({ 
      errors: errors.array(),
      message: 'Validation failed'
    });
  };
};

// ========================
// ROUTES WITH VALIDATION
// ========================

// Health endpoint with request validation
app.get('/health', [
  // Validate query parameters if any
], (req, res) => {
  try {
    // Validate input if needed
    const { detailed } = req.query;

    if (detailed && detailed !== 'true' && detailed !== 'false') {
      return res.status(400).json({
        error: 'Invalid detailed parameter',
        message: 'detailed must be either "true" or "false"'
      });
    }

    const healthData = {
      status: 'healthy',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memoryUsage: process.memoryUsage()
    };

    if (detailed === 'true') {
      healthData.systemInfo = {
        nodeVersion: process.version,
        platform: process.platform,
        arch: process.arch
      };
    }

    res.json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      status: 'unhealthy',
      error: 'Internal server error during health check'
    });
  }
});

// Users endpoint with pagination and validation
app.get('/users', [
  // Validate query parameters
  validate([
    body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
    body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  ])
], async (req, res) => {
  try {
    const { page = 1, limit = 10 } = req.query;
    const pageNum = parseInt(page);
    const limitNum = parseInt(limit);

    // Database simulation - in real app, this would be a database call
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'user' },
      { id: 4, name: 'Diana', email: 'diana@example.com', role: 'user' },
      { id: 5, name: 'Eve', email: 'eve@example.com', role: 'user' },
    ];

    // Simulate pagination
    const startIndex = (pageNum - 1) * limitNum;
    const endIndex = pageNum * limitNum;
    const paginatedUsers = allUsers.slice(startIndex, endIndex);

    res.json({
      users: paginatedUsers,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total: allUsers.length,
        totalPages: Math.ceil(allUsers.length / limitNum)
      }
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Failed to fetch users',
      message: 'An internal server error occurred'
    });
  }
});

// New user creation endpoint with comprehensive validation
app.post('/users', [
  validate([
    body('name').trim().notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters'),
    body('email').trim().isEmail().normalizeEmail().withMessage('Valid email is required'),
    body('role').optional().isIn(['user', 'admin', 'moderator']).withMessage('Invalid role'),
    body('age').optional().isInt({ min: 18, max: 120 }).withMessage('Age must be between 18 and 120')
  ])
], async (req, res) => {
  try {
    const { name, email, role = 'user', age } = req.body;

    // Additional business logic validation
    if (role === 'admin' && (!req.user || req.user.role !== 'admin')) {
      return res.status(403).json({
        error: 'Forbidden',
        message: 'Only admins can create admin users'
      });
    }

    // Simulate user creation
    const newUser = {
      id: Date.now(), // In real app, this would be DB-generated
      name,
      email,
      role,
      age,
      createdAt: new Date().toISOString()
    };

    res.status(201).json({
      message: 'User created successfully',
      user: newUser
    });
  } catch (error) {
    console.error('User creation error:', error);

    if (error.name === 'ValidationError') {
      return res.status(400).json({
        error: 'Validation Error',
        message: error.message
      });
    }

    res.status(500).json({
      error: 'Failed to create user',
      message: 'An internal server error occurred'
    });
  }
});

// ========================
// ERROR HANDLING MIDDLEWARE
// ========================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.url}`,
    timestamp: new Date().toISOString()
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    error: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  // Don't leak internal errors in production
  const isProduction = process.env.NODE_ENV === 'production';
  const errorMessage = isProduction ? 'Internal server error' : err.message;

  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    message: errorMessage,
    ...(!isProduction && { stack: err.stack }),
    timestamp: new Date().toISOString()
  });
});

// ========================
// STARTUP AND SHUTDOWN
// ========================

// Graceful shutdown
const gracefulShutdown = (signal) => {
  console.log(`${signal} received. Starting graceful shutdown...`);

  const shutdownTimeout = setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000); // 10 second timeout

  server.close(() => {
    clearTimeout(shutdownTimeout);
    console.log('HTTP server closed');

    // Close database connections here if any
    console.log('Shutdown complete');
    process.exit(0);
  });
};

// Signal handlers
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Environment validation
const requiredEnvVars = ['NODE_ENV', 'PORT'];
if (process.env.NODE_ENV === 'production') {
  requiredEnvVars.push('DATABASE_URL', 'JWT_SECRET');
}

const missingEnvVars = requiredEnvVars.filter(varName => !process.env[varName]);
if (missingEnvVars.length > 0) {
  console.error('Missing required environment variables:', missingEnvVars);
  process.exit(1);
}

// Server startup
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log({
    message: 'Server started successfully',
    port: PORT,
    node_env: process.env.NODE_ENV || 'development',
    timestamp: new Date().toISOString()
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  gracefulShutdown('UNHANDLED_REJECTION');
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  gracefulShutdown('UNCAUGHT_EXCEPTION');
});

module.exports = { app, server };

