/**
 * Improved Express.js application with enhanced error handling
 * and basic security measures
 */

const express = require('express');
const app = express();

// ========================
// BASIC SECURITY SETTINGS
// ========================

// Disable x-powered-by header
app.disable('x-powered-by');

// Basic security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  next();
});

// Request size limits
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: true, limit: '1mb' }));

// ========================
// ERROR HANDLING UTILITIES
// ========================

class AppError extends Error {
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;

    Error.captureStackTrace(this, this.constructor);
  }
}

// ========================
// LOGGING MIDDLEWARE
// ========================

app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.url} - IP: ${req.ip}`);
  next();
});

// ========================
// INPUT VALIDATION
// ========================

const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

const validateNumber = (num, min, max) => {
  const parsed = parseInt(num, 10);
  return !isNaN(parsed) && parsed >= min && parsed <= max;
};

// ========================
// ENHANCED ROUTES
// ========================

app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error',
      message: 'Internal server error'
    });
  }
});

app.get('/users', (req, res) => {
  try {
    // Validate query parameters if provided
    const { page = 1, limit = 10 } = req.query;

    if (page && !validateNumber(page, 1, 100)) {
      return res.status(400).json({
        error: 'Invalid page parameter',
        message: 'Page must be a number between 1 and 100'
      });
    }

    if (limit && !validateNumber(limit, 1, 100)) {
      return res.status(400).json({
        error: 'Invalid limit parameter',
        message: 'Limit must be a number between 1 and 100'
      });
    }

    const pageNum = parseInt(page, 10);
    const limitNum = parseInt(limit, 10);

    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simple pagination
    const startIndex = (pageNum - 1) * limitNum;
    const endIndex = pageNum * limitNum;
    const paginatedUsers = allUsers.slice(startIndex, endIndex);

    res.json({
      users: paginatedUsers,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total: allUsers.length,
        hasMore: endIndex < allUsers.length
      }
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Failed to fetch users',
      message: 'An internal server error occurred'
    });
  }
});

// New endpoint with validation
app.post('/users', (req, res) => {
  try {
    const { name, email } = req.body;

    // Input validation
    if (!name || name.trim().length < 2 || name.trim().length > 50) {
      return res.status(400).json({
        error: 'Invalid name',
        message: 'Name must be between 2 and 50 characters'
      });
    }

    if (!email || !validateEmail(email)) {
      return res.status(400).json({
        error: 'Invalid email',
        message: 'Please provide a valid email address'
      });
    }

    // Sanitize input
    const sanitizedName = name.trim();
    const sanitizedEmail = email.trim().toLowerCase();

    // Create new user (in real app, this would save to database)
    const newUser = {
      id: Date.now(),
      name: sanitizedName,
      email: sanitizedEmail,
      createdAt: new Date().toISOString()
    };

    res.status(201).json({
      message: 'User created successfully',
      user: newUser
    });

  } catch (error) {
    console.error('Create user error:', error);
    res.status(500).json({
      error: 'Failed to create user',
      message: 'An internal server error occurred'
    });
  }
});

// ========================
// ERROR HANDLING
// ========================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.url} not found`,
    timestamp: new Date().toISOString()
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Global error handler:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method
  });

  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' && statusCode === 500 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({
    error: statusCode === 500 ? 'Internal Server Error' : 'Error',
    message: message,
    timestamp: new Date().toISOString()
  });
});

// ========================
// SERVER SETUP
// ========================

// Validate environment variables
const PORT = process.env.PORT || 3000;

// Graceful shutdown
const gracefulShutdown = () => {
  console.log('Received shutdown signal. Closing server...');

  const shutdownTimeout = setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);

  server.close(() => {
    clearTimeout(shutdownTimeout);
    console.log('Server closed successfully');
    process.exit(0);
  });
};

// Handle shutdown signals
process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// Handle unhandled rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  gracefulShutdown();
});

// Start server
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (${process.env.NODE_ENV || 'development'})`);
});

module.exports = { app, server };

# Minimal Improvements for app.js

## Current Code Issues

