#!/usr/bin/env node

/**
 * Credential Validation Script
 * Tests connectivity and validity of credentials in .env.test
 */

const { execSync } = require('child_process');
const fs = require('fs');
const dns = require('dns');
const util = require('util');
const https = require('https');
const { URL } = require('url');

const lookup = util.promisify(dns.lookup);

// Read .env.test file
function loadEnvFile() {
  try {
    const envContent = fs.readFileSync('.env.test', 'utf8');
    const envVars = {};

    envContent.split('\n').forEach(line => {
      // Skip comments and empty lines
      line = line.trim();
      if (!line || line.startsWith('#')) return;

      const [key, ...valueParts] = line.split('=');
      if (key && valueParts.length > 0) {
        envVars[key.trim()] = valueParts.join('=').trim();
      }
    });

    return envVars;
  } catch (error) {
    console.error('Error reading .env.test:', error.message);
    return {};
  }
}

// Check if a string contains "CANARY" (synthetic test value)
function isCanaryValue(value) {
  return value && value.toString().includes('CANARY');
}

// Test database connectivity
async function testDatabaseConnection(dbUrl) {
  console.log('\n=== Testing Database Connection ===');
  console.log(`Database URL: ${dbUrl}`);

  if (isCanaryValue(dbUrl)) {
    console.log('⚠️  WARNING: Database URL contains CANARY marker - this is likely a synthetic test value');
    return { valid: false, reason: 'Canary value detected' };
  }

  try {
    // Parse the database URL
    const url = new URL(dbUrl);
    const hostname = url.hostname;
    const port = url.port || 5432;

    console.log(`Testing connection to: ${hostname}:${port}`);

    // Try DNS resolution first
    try {
      const address = await lookup(hostname);
      console.log(`✅ DNS resolution successful: ${hostname} -> ${address.address}`);
    } catch (dnsError) {
      console.log(`❌ DNS resolution failed for ${hostname}: ${dnsError.message}`);
      return { valid: false, reason: `DNS resolution failed: ${dnsError.message}` };
    }

    // Note: Actual database connection test would require pg package
    console.log('ℹ️  Note: Full database connection test requires pg package installation');
    console.log('ℹ️  Run: npm install pg');

    return { valid: true, reason: 'Basic validation passed (full test requires pg package)' };

  } catch (error) {
    console.log(`❌ Invalid database URL format: ${error.message}`);
    return { valid: false, reason: `Invalid URL format: ${error.message}` };
  }
}

// Test AWS credentials
async function testAWSCredentials(accessKeyId, secretAccessKey) {
  console.log('\n=== Testing AWS Credentials ===');
  console.log(`AWS Access Key ID: ${accessKeyId.substring(0, 8)}...`);
  console.log(`AWS Secret Access Key: ${secretAccessKey.substring(0, 8)}...`);

  if (isCanaryValue(accessKeyId) || isCanaryValue(secretAccessKey)) {
    console.log('⚠️  WARNING: AWS credentials contain CANARY marker - likely synthetic test values');
    return { valid: false, reason: 'Canary values detected' };
  }

  // AWS credential format validation
  const awsAccessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
  const awsSecretPattern = /^[A-Za-z0-9+/]{40}$/;

  if (!awsAccessKeyPattern.test(accessKeyId)) {
    console.log(`❌ Invalid AWS Access Key ID format`);
    return { valid: false, reason: 'Invalid Access Key ID format' };
  }

  if (!awsSecretPattern.test(secretAccessKey)) {
    console.log(`❌ Invalid AWS Secret Access Key format`);
    return { valid: false, reason: 'Invalid Secret Access Key format' };
  }

  console.log('✅ AWS credential formats are valid');
  console.log('ℹ️  Note: Actual AWS API test requires aws-sdk package');
  console.log('ℹ️  Run: npm install aws-sdk');

  return { valid: true, reason: 'Format validation passed (full test requires aws-sdk)' };
}

// Test Anthropic API key
async function testAnthropicAPIKey(apiKey) {
  console.log('\n=== Testing Anthropic API Key ===');
  console.log(`API Key: ${apiKey.substring(0, 12)}...`);

  if (isCanaryValue(apiKey)) {
    console.log('⚠️  WARNING: Anthropic API key contains CANARY marker - likely synthetic test value');
    return { valid: false, reason: 'Canary value detected' };
  }

  // Anthropic API key pattern
  const anthropicPattern = /^sk-ant-[a-zA-Z0-9_-]{95}$/;

  if (!anthropicPattern.test(apiKey)) {
    console.log(`❌ Invalid Anthropic API key format`);
    return { valid: false, reason: 'Invalid API key format' };
  }

  console.log('✅ Anthropic API key format is valid');
  console.log('ℹ️  Note: Actual API test requires anthropic-ai package');
  console.log('ℹ️  Run: npm install @anthropic-ai/sdk');

  return { valid: true, reason: 'Format validation passed (full test requires SDK)' };
}

// Test Stripe API key
async function testStripeAPIKey(apiKey) {
  console.log('\n=== Testing Stripe API Key ===');
  console.log(`API Key: ${apiKey.substring(0, 12)}...`);

  if (isCanaryValue(apiKey)) {
    console.log('⚠️  WARNING: Stripe API key contains CANARY marker - likely synthetic test value');
    return { valid: false, reason: 'Canary value detected' };
  }

  // Stripe API key patterns
  const stripeLivePattern = /^sk-live-[a-zA-Z0-9]{24}$/;
  const stripeTestPattern = /^sk-test-[a-zA-Z0-9]{24}$/;

  if (!stripeLivePattern.test(apiKey) && !stripeTestPattern.test(apiKey)) {
    console.log(`❌ Invalid Stripe API key format`);
    return { valid: false, reason: 'Invalid API key format' };
  }

  const keyType = stripeLivePattern.test(apiKey) ? 'LIVE' : 'TEST';
  console.log(`✅ Stripe API key format is valid (${keyType} key)`);
  console.log('ℹ️  Note: Actual Stripe API test requires stripe package');
  console.log('ℹ️  Run: npm install stripe');

  return { valid: true, reason: 'Format validation passed (full test requires stripe package)' };
}

// Test Logfire token
async function testLogfireToken(token) {
  console.log('\n=== Testing Logfire Token ===');
  console.log(`Token: ${token.substring(0, 12)}...`);

  if (isCanaryValue(token)) {
    console.log('⚠️  WARNING: Logfire token contains CANARY marker - likely synthetic test value');
    return { valid: false, reason: 'Canary value detected' };
  }

  // Basic token validation (Logfire tokens are typically UUID-like)
  if (token.length < 20 || token.length > 100) {
    console.log(`❌ Invalid Logfire token length`);
    return { valid: false, reason: 'Invalid token length' };
  }

  console.log('✅ Logfire token format appears valid');
  console.log('ℹ️  Note: Actual Logfire API test requires logfire package or direct HTTP calls');

  return { valid: true, reason: 'Basic format validation passed' };
}

// Simple HTTP test for services that might respond to ping
async function testServiceConnectivity() {
  console.log('\n=== Testing Service Connectivity ===');

  const services = [
    { name: 'Stripe API', host: 'api.stripe.com' },
    { name: 'AWS STS', host: 'sts.amazonaws.com' },
    { name: 'Anthropic API', host: 'api.anthropic.com' },
  ];

  for (const service of services) {
    try {
      const address = await lookup(service.host);
      console.log(`✅ ${service.name} DNS resolution: ${service.host} -> ${address.address}`);
    } catch (error) {
      console.log(`❌ ${service.name} DNS resolution failed: ${error.message}`);
    }
  }
}

// Main function
async function main() {
  console.log('🔍 Credential Validation Script');
  console.log('===============================\n');

  const envVars = loadEnvFile();

  if (Object.keys(envVars).length === 0) {
    console.error('No environment variables found in .env.test');
    return;
  }

  console.log(`Found ${Object.keys(envVars).length} environment variables in .env.test\n`);

  // Check each credential
  const results = {};

  if (envVars.DATABASE_URL) {
    results.DATABASE_URL = await testDatabaseConnection(envVars.DATABASE_URL);
  }

  if (envVars.AWS_ACCESS_KEY_ID && envVars.AWS_SECRET_ACCESS_KEY) {
    results.AWS = await testAWSCredentials(
      envVars.AWS_ACCESS_KEY_ID,
      envVars.AWS_SECRET_ACCESS_KEY
    );
  }

  if (envVars.ANTHROPIC_API_KEY) {
    results.ANTHROPIC = await testAnthropicAPIKey(envVars.ANTHROPIC_API_KEY);
  }

  if (envVars.STRIPE_SECRET_KEY) {
    results.STRIPE = await testStripeAPIKey(envVars.STRIPE_SECRET_KEY);
  }

  if (envVars.LOGFIRE_TOKEN) {
    results.LOGFIRE = await testLogfireToken(envVars.LOGFIRE_TOKEN);
  }

  await testServiceConnectivity();

  // Summary
  console.log('\n📊 Validation Summary');
  console.log('===================\n');

  Object.entries(results).forEach(([service, result]) => {
    const status = result.valid ? '✅' : '❌';
    console.log(`${status} ${service}: ${result.reason}`);
  });

  // Check for canary values
  const canaryCount = Object.values(envVars).filter(isCanaryValue).length;
  console.log(`\n🔒 Security Note: ${canaryCount}/${Object.keys(envVars).length} credentials contain CANARY markers`);

  if (canaryCount > 0) {
    console.log('⚠️  These are likely synthetic test values for security monitoring');
    console.log('⚠️  Do NOT use these credentials in production!');
  }

  // Recommendations
  console.log('\n💡 Recommendations:');
  console.log('1. Install required packages for full validation:');
  console.log('   npm install pg aws-sdk @anthropic-ai/sdk stripe');
  console.log('2. Replace CANARY values with real credentials for production');
  console.log('3. Store real credentials in secure vault, not in .env files');
}

// Run the script
main().catch(error => {
  console.error('Script execution failed:', error);
  process.exit(1);
});

#!/usr/bin/env node

/**
 * Simple Credential Test Script
 * Makes actual HTTP requests where possible
 */

const fs = require('fs');
const https = require('https');
const { URL } = require('url');

// Load environment variables
function loadEnv() {
  try {
    const content = fs.readFileSync('.env.test', 'utf8');
    const env = {};
    content.split('\n').forEach(line => {
      line = line.trim();
      if (line && !line.startsWith('#')) {
        const [key, ...val] = line.split('=');
        if (key) env[key.trim()] = val.join('=').trim();
      }
    });
    return env;
  } catch (error) {
    return {};
  }
}

// Helper for HTTP requests
function httpRequest(options, data = null) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let body = '';
      res.on('data', chunk => body += chunk);
      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          body: body
        });
      });
    });

    req.on('error', reject);
    if (data) req.write(data);
    req.end();
  });
}

// Check if value is a canary
function isCanary(value) {
  return value && typeof value === 'string' && value.includes('CANARY');
}

// Test Stripe API key with a simple balance check
async function testStripeKey(key) {
  console.log(`Testing Stripe key: ${key.substring(0, 12)}...`);

  if (isCanary(key)) {
    console.log('  ⚠️ CANARY value detected - skipping real API call');
    return { valid: false, canary: true };
  }

  try {
    const options = {
      hostname: 'api.stripe.com',
      port: 443,
      path: '/v1/balance',
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${key}`,
        'Content-Type': 'application/x-www-form-urlencoded'
      },
      timeout: 10000
    };

    const response = await httpRequest(options);

    if (response.statusCode === 200) {
      console.log('  ✅ Stripe API key is valid');
      return { valid: true, canary: false };
    } else if (response.statusCode === 401) {
      console.log('  ❌ Stripe API key is invalid/unauthorized');
      return { valid: false, canary: false };
    } else {
      console.log(`  ⚠️ Stripe API returned ${response.statusCode}`);
      return { valid: null, canary: false };
    }
  } catch (error) {
    console.log(`  ❌ Stripe API error: ${error.message}`);
    return { valid: false, canary: false, error: error.message };
  }
}

// Test Anthropic API key
async function testAnthropicKey(key) {
  console.log(`Testing Anthropic key: ${key.substring(0, 12)}...`);

  if (isCanary(key)) {
    console.log('  ⚠️ CANARY value detected - skipping real API call');
    return { valid: false, canary: true };
