      console.log('  ✅ Anthropic API key accepted (got expected 400 for minimal request)');
      return { valid: true, canary: false };
    } else if (response.statusCode === 401 || response.statusCode === 403) {
      console.log('  ❌ Anthropic API key is invalid/unauthorized');
      return { valid: false, canary: false };
    } else {
      console.log(`  ⚠️ Anthropic API returned ${response.statusCode}`);
      try {
        const body = JSON.parse(response.body);
