// Enhanced Express application with security best practices
// This version includes comprehensive error handling and input validation

const express = require('express');
const helmet = require('helmet');
const compression = require('compression');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const { body, query, validationResult } = require('express-validator');
const Joi = require('joi');

const app = express();

// Security middleware setup
app.use(helmet()); // Set security HTTP headers
app.use(compression()); // Compress responses
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// Request logging
app.use(morgan('combined', {
  skip: (req, res) => req.path === '/health' // Skip health checks in logs
}));

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter); // Apply to all API routes

// Input validation middleware
const validateRequest = (schema, property = 'body') => {
  return (req, res, next) => {
    const { error } = schema.validate(req[property], { 
      abortEarly: false,
      allowUnknown: false 
    });

    if (error) {
      return res.status(400).json({
        success: false,
        error: 'Validation Error',
        details: error.details.map(err => ({
          field: err.path.join('.'),
          message: err.message
        }))
      });
    }
    next();
  };
};

// Request sanitization middleware
const sanitizeInput = (req, res, next) => {
  if (req.body) {
    sanitizeObject(req.body);
  }
  if (req.query) {
    sanitizeObject(req.query);
  }
  if (req.params) {
    sanitizeObject(req.params);
  }
  next();
};

function sanitizeObject(obj) {
  for (const key in obj) {
    if (typeof obj[key] === 'string') {
      // Basic XSS prevention - escape HTML entities
      obj[key] = obj[key]
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#x27;')
        .replace(/\//g, '&#x2F;');
    } else if (typeof obj[key] === 'object' && obj[key] !== null) {
      sanitizeObject(obj[key]);
    }
  }
}

// Apply sanitization to all routes
app.use(sanitizeInput);

// Health check endpoint with validation
app.get('/health', [
  query('detailed').optional().isBoolean().toBoolean(),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      error: 'Validation Error',
      details: errors.array()
    });
  }

  try {
    const detailed = req.query.detailed || false;
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: detailed ? process.memoryUsage() : undefined,
      nodeVersion: detailed ? process.version : undefined
    };

    res.json({
      success: true,
      data: healthData
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      success: false,
      error: 'Internal Server Error',
      message: 'Health check failed'
    });
  }
});

// Users endpoint with comprehensive validation
const userQuerySchema = Joi.object({
  page: Joi.number().integer().min(1).default(1),
  limit: Joi.number().integer().min(1).max(100).default(10),
  sortBy: Joi.string().valid('id', 'name', 'email').default('id'),
  sortOrder: Joi.string().valid('asc', 'desc').default('asc')
});

app.get('/users', validateRequest(userQuerySchema, 'query'), async (req, res) => {
  try {
    const { page, limit, sortBy, sortOrder } = req.query;

    // Mock database query with error simulation
    const users = await getUsersFromDatabase(page, limit, sortBy, sortOrder);

    res.json({
      success: true,
      data: users,
      pagination: {
        page: parseInt(page),
        limit: parseInt(limit),
        total: users.length
      }
    });
  } catch (error) {
    console.error('Error fetching users:', error);

    if (error.name === 'DatabaseError') {
      return res.status(503).json({
        success: false,
        error: 'Service Unavailable',
        message: 'Database connection failed'
      });
    }

    res.status(500).json({
      success: false,
      error: 'Internal Server Error',
      message: 'Failed to fetch users'
    });
  }
});

// Create user endpoint with comprehensive validation
const createUserSchema = Joi.object({
  name: Joi.string()
    .min(2)
    .max(50)
    .pattern(/^[a-zA-Z\s]+$/)
    .required()
    .messages({
      'string.pattern.base': 'Name can only contain letters and spaces',
      'string.min': 'Name must be at least 2 characters',
      'string.max': 'Name cannot exceed 50 characters'
    }),
  email: Joi.string()
    .email()
    .required()
    .messages({
      'string.email': 'Invalid email format'
    }),
  age: Joi.number()
    .integer()
    .min(18)
    .max(120)
    .optional()
});

app.post('/users', validateRequest(createUserSchema), async (req, res) => {
  try {
    // Additional business logic validation
    const { name, email, age } = req.body;

    // Check if user already exists (mock)
    const existingUser = await checkIfUserExists(email);
    if (existingUser) {
      return res.status(409).json({
        success: false,
        error: 'Conflict',
        message: 'User with this email already exists'
      });
    }

    // Create user (mock implementation)
    const newUser = await createUser({ name, email, age });

    res.status(201).json({
      success: true,
      data: newUser,
      message: 'User created successfully'
    });
  } catch (error) {
    console.error('Error creating user:', error);

    if (error.name === 'ValidationError') {
      return res.status(400).json({
        success: false,
        error: 'Validation Error',
        message: error.message
      });
    }

    res.status(500).json({
      success: false,
      error: 'Internal Server Error',
      message: 'Failed to create user'
    });
  }
});

// Get user by ID with parameter validation
const userIdSchema = Joi.object({
  id: Joi.string()
    .pattern(/^[0-9]+$/)
    .required()
    .messages({
      'string.pattern.base': 'ID must be a numeric string'
    })
});

app.get('/users/:id', validateRequest(userIdSchema, 'params'), async (req, res) => {
  try {
    const userId = req.params.id;

    // Validate numeric conversion
    const id = parseInt(userId, 10);
    if (isNaN(id) || id <= 0) {
      return res.status(400).json({
        success: false,
        error: 'Bad Request',
        message: 'Invalid user ID format'
      });
    }

    const user = await getUserById(id);

    if (!user) {
      return res.status(404).json({
        success: false,
        error: 'Not Found',
        message: `User with ID ${id} not found`
      });
    }

    res.json({
      success: true,
      data: user
    });
  } catch (error) {
    console.error('Error fetching user:', error);
    res.status(500).json({
      success: false,
      error: 'Internal Server Error',
      message: 'Failed to fetch user'
    });
  }
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Handle different types of errors
  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      success: false,
      error: 'Bad Request',
      message: 'Invalid JSON payload'
    });
  }

  // Default error response
  res.status(err.status || 500).json({
    success: false,
    error: err.name || 'Internal Server Error',
    message: process.env.NODE_ENV === 'production' 
      ? 'An unexpected error occurred' 
      : err.message
  });
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    success: false,
    error: 'Not Found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Mock database functions (replace with actual implementation)
async function getUsersFromDatabase(page, limit, sortBy, sortOrder) {
  // Simulate database delay
  await new Promise(resolve => setTimeout(resolve, 100));

  // Mock data
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com', age: 30 },
    { id: 2, name: 'Bob', email: 'bob@example.com', age: 25 },
    { id: 3, name: 'Charlie', email: 'charlie@example.com', age: 35 },
    { id: 4, name: 'Diana', email: 'diana@example.com', age: 28 },
    { id: 5, name: 'Eve', email: 'eve@example.com', age: 32 }
  ];

  // Apply pagination and sorting
  const sortedUsers = users.sort((a, b) => {
    const aVal = a[sortBy];
    const bVal = b[sortBy];
    if (sortOrder === 'asc') return aVal > bVal ? 1 : -1;
    return aVal < bVal ? 1 : -1;
  });

  const start = (page - 1) * limit;
  return sortedUsers.slice(start, start + limit);
}

async function checkIfUserExists(email) {
  await new Promise(resolve => setTimeout(resolve, 50));
  return false; // Mock - always returns false
}

async function createUser(userData) {
  await new Promise(resolve => setTimeout(resolve, 150));
  return {
    id: Math.floor(Math.random() * 1000) + 1,
    ...userData,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };
}

async function getUserById(id) {
  await new Promise(resolve => setTimeout(resolve, 100));

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com', age: 30 },
    { id: 2, name: 'Bob', email: 'bob@example.com', age: 25 }
  ];

  return users.find(user => user.id === id) || null;
}

// Graceful shutdown handling
function setupGracefulShutdown(server) {
  const signals = ['SIGINT', 'SIGTERM', 'SIGQUIT'];

  signals.forEach(signal => {
    process.on(signal, () => {
      console.log(`\n${signal} received. Starting graceful shutdown...`);

      server.close(() => {
        console.log('HTTP server closed');
        process.exit(0);
      });

      // Force shutdown after 10 seconds if graceful shutdown fails
      setTimeout(() => {
        console.error('Could not close connections in time, forcefully shutting down');
        process.exit(1);
      }, 10000);
    });
  });
}

// Configuration
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Start server
const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Setup graceful shutdown
setupGracefulShutdown(server);

module.exports = app;

# Code Comparison: Original vs Improved

## Original `app.js`

```javascript
