  ]);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

## Security Issues in Original

### 1. **No Error Handling**
```javascript
// Missing: No try-catch, no error middleware
app.get('/health', (req, res) => {
  // What if an error occurs here?
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

### 2. **No Input Validation**
```javascript
// Missing: No validation of query parameters
app.get('/users', (req, res) => {
  // req.query could contain malicious data
  res.json([...]);
});
```

### 3. **No Security Headers**
```javascript
// Missing: Vulnerable to XSS, clickjacking, etc.
