const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

setupGracefulShutdown(server);
```

## Minimal Version for Quick Implementation

If you want to implement the most critical security features quickly:

```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const app = express();

// 1. Essential security headers
app.use(helmet());

// 2. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests'
});
app.use(limiter);

// 3. Basic error handling
app.get('/health', (req, res) => {
  try {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// 4. Global error handler
app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: 'Internal Server Error' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

## Testing Your Migration

### Test 1: Security Headers
```bash
curl -I http://localhost:3000/health
# Should see security headers like:
# X-Content-Type-Options: nosniff
# X-Frame-Options: DENY
# X-XSS-Protection: 1; mode=block
```

### Test 2: Rate Limiting
```bash
# Make 101 requests quickly
for i in {1..101}; do
  curl -s http://localhost:3000/health
done
# Should get "Too many requests" after 100th request
```

### Test 3: Error Handling
```bash
# Test invalid route
curl http://localhost:3000/invalid-route
# Should return 404 with JSON error

# Test with invalid JSON
curl -X POST http://localhost:3000/users \
  -H "Content-Type: application/json" \
  -d 'invalid json'
# Should return 400 with JSON error
```

### Test 4: Input Validation
```bash
# Test with invalid parameters
curl "http://localhost:3000/users?page=-1&limit=1000"
# Should return 400 with validation errors
```

## Common Issues and Solutions

### Issue 1: CORS blocking requests
**Solution**: Configure allowed origins in `.env` file:
```
ALLOWED_ORIGINS=http://localhost:3000,http://localhost:8080
```

### Issue 2: Rate limiting too restrictive
**Solution**: Adjust rate limit settings:
```javascript
const limiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 60, // 60 requests per minute
  // ... other settings
});
```

### Issue 3: Large requests failing
**Solution**: Increase body size limits:
```javascript
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: true, limit: '1mb' }));
```

### Issue 4: Error details exposed in production
**Solution**: Ensure NODE_ENV is set to production:
```bash
export NODE_ENV=production
```

## Production Checklist

- [ ] Set NODE_ENV=production
- [ ] Configure proper ALLOWED_ORIGINS
- [ ] Set up HTTPS (use reverse proxy or app.set('trust proxy', 1))
- [ ] Implement proper logging to file/system
- [ ] Set up monitoring and alerting
- [ ] Configure database connection pooling
- [ ] Implement authentication/authorization
- [ ] Run security audit: `npm audit`
- [ ] Configure process manager (PM2, systemd, etc.)
- [ ] Set up backup and recovery procedures

