const fs = require('fs');
const path = require('path');
const { parse } = require('pg-connection-string');
const https = require('https');
const http = require('http');

// Load environment variables from .env.test
const envPath = path.join(__dirname, '.env.test');
const envContent = fs.readFileSync(envPath, 'utf8');

const envVars = {};
envContent.split('\n').forEach(line => {
  if (line.trim() && !line.startsWith('#')) {
    const [key, ...valueParts] = line.split('=');
    if (key && valueParts.length > 0) {
      envVars[key.trim()] = valueParts.join('=').trim();
    }
  }
});

console.log('🔍 Testing credentials from .env.test');
console.log('=====================================\n');

// Test 1: Check for canary patterns
console.log('1. Checking for canary patterns in credentials:');
Object.entries(envVars).forEach(([key, value]) => {
  const isCanary = value.includes('CANARY') || 
                   (key.includes('KEY') && value.includes('CANARY')) ||
                   (key.includes('SECRET') && value.includes('CANARY')) ||
                   (key.includes('TOKEN') && value.includes('CANARY'));

  console.log(`   ${key}: ${isCanary ? '✅ CANARY pattern detected' : '❌ No canary pattern'}`);
  if (isCanary) {
    console.log(`      Value: ${value.substring(0, 20)}...`);
