console.log('\n3. Testing AWS credentials format:');
const awsKeyId = envVars.AWS_ACCESS_KEY_ID;
const awsSecret = envVars.AWS_SECRET_ACCESS_KEY;

if (awsKeyId) {
  // AWS Access Key IDs typically start with AKIA and are 20 characters
  const isValidFormat = /^[A-Z0-9]{20}$/.test(awsKeyId);
