  console.log(`      Length: ${awsSecret.length} chars`);

  if (awsSecret.includes('CANARY')) {
    console.log(`   ⚠️  Contains CANARY marker - likely test/dummy credential`);
  }
}

console.log('\n4. Testing API key formats:');

// Test Stripe key
const stripeKey = envVars.STRIPE_SECRET_KEY;
if (stripeKey) {
  // Stripe keys typically start with sk-live-, sk-test-, rk_live_, or rk_test_
  const isStripeFormat = /^(sk|rk)_(live|test)_/.test(stripeKey);
  console.log(`   STRIPE_SECRET_KEY: ${isStripeFormat ? '✅ Valid Stripe format' : '❌ Invalid Stripe format'}`);
  console.log(`      Type: ${stripeKey.substring(0, 8)}...`);

  if (stripeKey.includes('CANARY')) {
    console.log(`   ⚠️  Contains CANARY marker - likely test/dummy credential`);
