console.log('      - Create .env.development with test values');
console.log('      - Use services\' sandbox/test environments');
console.log('      - Never use production credentials locally');

// Export for potential use in other tests
module.exports = {
  envVars,
  areAllCanary: allCredentialsHaveCanary,
  hasCanaryMarkers: canaryCount > 0
};

#!/usr/bin/env node

/**
 * Safe credential analyzer - doesn't make actual API calls
 * Only analyzes format and patterns
 */

const fs = require('fs');
const path = require('path');

// Load and parse .env.test
function loadEnvFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const envVars = {};

    content.split('\n').forEach(line => {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#')) {
        const equalsIndex = trimmed.indexOf('=');
        if (equalsIndex > 0) {
          const key = trimmed.substring(0, equalsIndex).trim();
          const value = trimmed.substring(equalsIndex + 1).trim();
          envVars[key] = value;
        }
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error loading ${filePath}:`, error.message);
    return {};
  }
}

// Analyze a single credential
function analyzeCredential(key, value) {
  const analysis = {
    key,
    value: value.substring(0, 15) + '...', // Show only first 15 chars
    fullLength: value.length,
    hasCanary: value.includes('CANARY'),
    formatValid: false,
    formatNotes: '',
    likelyReal: false,
    safetyRecommendation: ''
  };

  // Check specific credential types
  switch(key) {
    case 'DATABASE_URL':
      try {
        // Basic URL parsing
        if (value.startsWith('postgres://') || value.startsWith('postgresql://')) {
          analysis.formatValid = true;
          analysis.formatNotes = 'Valid PostgreSQL URL format';

          // Extract host
          const hostMatch = value.match(/@([^:/\s]+)/);
          if (hostMatch) {
            const host = hostMatch[1];
            analysis.formatNotes += `, Host: ${host}`;
            if (host.includes('.internal') || host === 'localhost') {
              analysis.formatNotes += ' (internal/private host)';
            }
          }
        }
      } catch (e) {
        analysis.formatNotes = `Parse error: ${e.message}`;
      }
      analysis.safetyRecommendation = 'Test with local test database only';
      break;

    case 'AWS_ACCESS_KEY_ID':
      // AWS Access Key IDs are 20 chars, start with AKIA
      analysis.formatValid = /^[A-Z0-9]{20}$/.test(value);
      analysis.formatNotes = analysis.formatValid ? 
        'Valid AWS Access Key format' : 
        'Invalid format (should be 20 chars, uppercase alphanumeric)';
      analysis.likelyReal = analysis.formatValid && !analysis.hasCanary;
      analysis.safetyRecommendation = 'Never use real AWS keys in test files';
      break;

    case 'AWS_SECRET_ACCESS_KEY':
      // AWS Secret Access Keys are 40 chars
      analysis.formatValid = value.length === 40;
      analysis.formatNotes = analysis.formatValid ?
        'Valid AWS Secret length' :
        `Invalid length (${value.length} chars, expected 40)`;
      analysis.likelyReal = analysis.formatValid && !analysis.hasCanary;
      analysis.safetyRecommendation = 'Treat as highly sensitive';
      break;

    case 'STRIPE_SECRET_KEY':
      // Stripe: sk-live-..., sk-test-..., rk_live_..., rk_test_...
      analysis.formatValid = /^(sk|rk)_(live|test)_/.test(value);
      analysis.formatNotes = analysis.formatValid ?
        `Valid Stripe ${value.substring(0, 8)} key` :
        'Invalid Stripe key format';
      analysis.likelyReal = analysis.formatValid && !analysis.hasCanary;
      analysis.safetyRecommendation = 'Use test keys for development';
      break;

    case 'ANTHROPIC_API_KEY':
      // Anthropic: sk-ant-...
      analysis.formatValid = value.startsWith('sk-ant-');
      analysis.formatNotes = analysis.formatValid ?
        'Valid Anthropic API key format' :
        'Invalid Anthropic key format';
      analysis.likelyReal = analysis.formatValid && !analysis.hasCanary;
      analysis.safetyRecommendation = 'Use only in secure environments';
      break;

    case 'LOGFIRE_TOKEN':
      analysis.formatValid = value.length > 10; // Arbitrary minimum
      analysis.formatNotes = `Token length: ${value.length} chars`;
      analysis.likelyReal = analysis.formatValid && !analysis.hasCanary;
      analysis.safetyRecommendation = 'Check if this is a monitoring token';
      break;

    default:
      analysis.formatNotes = 'Unknown credential type';
      analysis.safetyRecommendation = 'Review with security team';
  }

  return analysis;
}

// Main analysis function
function analyzeCredentials(envVars) {
  console.log('🔐 Credential Security Analysis');
  console.log('==============================\n');

  const analyses = [];
  let canaryCount = 0;
  let realCount = 0;

  // Analyze each credential
  Object.entries(envVars).forEach(([key, value]) => {
    const analysis = analyzeCredential(key, value);
    analyses.push(analysis);

    if (analysis.hasCanary) canaryCount++;
    if (analysis.likelyReal) realCount++;
  });

  // Display results
  analyses.forEach(analysis => {
    const status = analysis.hasCanary ? '🟡 CANARY' : 
                   analysis.likelyReal ? '🔴 POTENTIALLY REAL' : 
                   '⚪ UNKNOWN';

    console.log(`${status} ${analysis.key}`);
    console.log(`   Value: ${analysis.value}`);
    console.log(`   Length: ${analysis.fullLength} chars`);
    console.log(`   Format: ${analysis.formatValid ? '✅ Valid' : '❌ Invalid'} (${analysis.formatNotes})`);
    if (analysis.safetyRecommendation) {
      console.log(`   Safety: ${analysis.safetyRecommendation}`);
    }
    console.log('');
  });

  // Summary
  console.log('📊 Summary');
  console.log('==========');
  console.log(`Total credentials analyzed: ${analyses.length}`);
  console.log(`Canary credentials: ${canaryCount}`);
  console.log(`Potentially real credentials: ${realCount}`);
  console.log(`Unknown/other: ${analyses.length - canaryCount - realCount}`);

  // Recommendations based on findings
  console.log('\n🚨 Recommendations');
  console.log('=================');

  if (canaryCount === analyses.length) {
    console.log('✅ ALL credentials are canary values');
    console.log('   - These are intentionally fake for security monitoring');
    console.log('   - Do NOT replace with real values');
    console.log('   - May trigger security alerts if used');
    console.log('   - Keep as-is in test environments');
  } else if (realCount > 0) {
    console.log('⚠️  POTENTIALLY REAL CREDENTIALS DETECTED');
    console.log('   - Some credentials may be real/production');
    console.log('   - URGENT: Verify with security team');
    console.log('   - DO NOT commit to version control');
    console.log('   - Consider rotating/revoking these credentials');
  } else {
    console.log('ℹ️  Mixed or unclear credential status');
    console.log('   - Review each credential individually');
    console.log('   - Check with the development team');
    console.log('   - Consider implementing credential validation');
  }

  return {
    analyses,
    allCanary: canaryCount === analyses.length,
    hasRealCredentials: realCount > 0,
    stats: {
      total: analyses.length,
      canary: canaryCount,
      potentiallyReal: realCount
    }
  };
}

// Main execution
try {
  const envPath = path.join(__dirname, '.env.test');

  if (!fs.existsSync(envPath)) {
    console.error('❌ .env.test file not found');
    process.exit(1);
  }

  console.log(`📁 Analyzing: ${envPath}`);
  console.log('='.repeat(50));

  const envVars = loadEnvFile(envPath);

  if (Object.keys(envVars).length === 0) {
    console.log('No credentials found in .env.test');
    process.exit(0);
  }

  const results = analyzeCredentials(envVars);

  // Export results if needed
  module.exports = results;

} catch (error) {
  console.error('❌ Error during analysis:', error.message);
  process.exit(1);
}

#!/usr/bin/env node

/**
 * Simple credential analyzer without external dependencies
 */

const fs = require('fs');
const path = require('path');

// Parse database URL without external library
function parseDatabaseUrl(url) {
  if (!url) return null;

  try {
    // Simple parser for postgres:// URLs
    if (url.startsWith('postgres://') || url.startsWith('postgresql://')) {
      const withoutProtocol = url.replace(/^postgres(ql)?:\/\//, '');

      // Split user:password@host:port/database
      const atSplit = withoutProtocol.split('@');
      if (atSplit.length !== 2) return null;

      const [userPass, hostPortDb] = atSplit;
      const [user, password] = userPass.split(':');

      const slashSplit = hostPortDb.split('/');
      if (slashSplit.length !== 2) return null;

      const [hostPort, database] = slashSplit;
      const [host, port] = hostPort.includes(':') ? hostPort.split(':') : [hostPort, '5432'];

      return {
        user,
        password: password || null,
        host,
        port: parseInt(port) || 5432,
        database
      };
    }

    return null;
  } catch (error) {
    return { error: error.message };
  }
}

// Main analysis
function analyzeCredentials() {
  const envPath = path.join(__dirname, '.env.test');

  console.log('🔐 Credential Analysis for .env.test');
  console.log('====================================\n');

  if (!fs.existsSync(envPath)) {
    console.log('❌ .env.test file not found');
    return;
  }

  // Read and parse .env.test
  const content = fs.readFileSync(envPath, 'utf8');
  const lines = content.split('\n');
  const credentials = {};

  lines.forEach(line => {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const equalsIndex = trimmed.indexOf('=');
      if (equalsIndex > 0) {
        const key = trimmed.substring(0, equalsIndex).trim();
        const value = trimmed.substring(equalsIndex + 1).trim();
        credentials[key] = value;
      }
    }
  });

  console.log(`Found ${Object.keys(credentials).length} credentials:\n`);

  // Analyze each credential
  Object.entries(credentials).forEach(([key, value]) => {
    console.log(`${key}:`);
    console.log(`  Value: ${value.substring(0, 30)}${value.length > 30 ? '...' : ''}`);
    console.log(`  Length: ${value.length} characters`);

    // Check for canary markers
    const hasCanary = value.includes('CANARY');
    console.log(`  Canary Marker: ${hasCanary ? '✅ YES (test/dummy)' : '❌ NO (potentially real)'}`);

    // Type-specific analysis
    switch(key) {
      case 'DATABASE_URL':
        const dbInfo = parseDatabaseUrl(value);
        if (dbInfo && !dbInfo.error) {
          console.log(`  Type: PostgreSQL database`);
          console.log(`  Host: ${dbInfo.host}`);
          console.log(`  Port: ${dbInfo.port}`);
          console.log(`  Database: ${dbInfo.database}`);
          console.log(`  User: ${dbInfo.user}`);

          // Safety check
          if (dbInfo.host.includes('.internal')) {
            console.log(`  ⚠️  Host is internal (${dbInfo.host}) - not publicly accessible`);
          }
          if (hasCanary && dbInfo.password && dbInfo.password.includes('CANARY')) {
            console.log(`  ℹ️  Password contains CANARY marker - fake credential`);
          }
        } else if (dbInfo && dbInfo.error) {
          console.log(`  ❌ Parse error: ${dbInfo.error}`);
        }
        break;

      case 'AWS_ACCESS_KEY_ID':
        console.log(`  Type: AWS Access Key ID`);
        // AWS keys are typically 20 chars starting with AKIA
        const isAwsFormat = /^[A-Z0-9]{20}$/.test(value);
        console.log(`  Valid AWS Format: ${isAwsFormat ? '✅ YES' : '❌ NO'}`);
        if (value.startsWith('AKIA-CANARY')) {
          console.log(`  ℹ️  Starts with AKIA-CANARY - clearly fake`);
        }
        break;

      case 'AWS_SECRET_ACCESS_KEY':
        console.log(`  Type: AWS Secret Access Key`);
        // AWS secrets are typically 40 chars
        console.log(`  Length check: ${value.length === 40 ? '✅ 40 chars' : `❌ ${value.length} chars (expected 40)`}`);
        break;

      case 'STRIPE_SECRET_KEY':
        console.log(`  Type: Stripe Secret Key`);
        // Stripe: sk-live-, sk-test-, rk_live_, rk_test_
        const isStripeFormat = /^(sk|rk)_(live|test)_/.test(value);
        console.log(`  Valid Stripe Format: ${isStripeFormat ? '✅ YES' : '❌ NO'}`);
        if (isStripeFormat) {
          const type = value.substring(0, 8);
          console.log(`  Key Type: ${type}`);
        }
        break;

      case 'ANTHROPIC_API_KEY':
        console.log(`  Type: Anthropic API Key`);
        const isAnthropicFormat = value.startsWith('sk-ant-');
        console.log(`  Valid Anthropic Format: ${isAnthropicFormat ? '✅ YES' : '❌ NO'}`);
        break;

      case 'LOGFIRE_TOKEN':
        console.log(`  Type: Logfire Token`);
        console.log(`  Appears to be: ${hasCanary ? 'Canary token for monitoring' : 'Potentially real token'}`);
        break;
    }

    console.log(''); // Empty line between credentials
  });

  // Summary
  console.log('📊 Summary Analysis');
  console.log('===================');

  const total = Object.keys(credentials).length;
  const canaryCount = Object.values(credentials).filter(v => v.includes('CANARY')).length;
  const realCount = total - canaryCount;

  console.log(`Total credentials: ${total}`);
  console.log(`Canary/test credentials: ${canaryCount}`);
  console.log(`Potentially real credentials: ${realCount}`);

  console.log('\n🚨 Security Assessment');
  console.log('====================');

  if (canaryCount === total) {
    console.log('✅ ALL credentials contain CANARY markers');
    console.log('   These are intentionally fake for:');
    console.log('   - Security monitoring');
    console.log('   - Exfiltration detection');
    console.log('   - Alert testing');
    console.log('');
    console.log('   ⚠️  DO NOT attempt to use these for real connections');
    console.log('   ⚠️  May trigger security alarms if used');
    console.log('   ℹ️  Keep as-is for test environments');
  } else if (realCount > 0) {
    console.log('🔴 POTENTIALLY REAL CREDENTIALS DETECTED');
    console.log('');
    console.log('   IMMEDIATE ACTIONS REQUIRED:');
    console.log('   1. DO NOT run connectivity tests');
    console.log('   2. DO NOT commit to version control');
    console.log('   3. Contact security team immediately');
    console.log('   4. Consider credential rotation');
    console.log('');
    console.log('   Check these keys specifically:');
    Object.entries(credentials).forEach(([key, value]) => {
      if (!value.includes('CANARY')) {
        console.log(`      - ${key}`);
      }
    });
  } else {
    console.log('⚠️  Mixed or unclear status');
    console.log('   Review each credential above for details');
  }

  console.log('\n🔧 Recommended Next Steps');
  console.log('=======================');
  console.log('1. If credentials are all canary:');
  console.log('   - Leave .env.test as-is');
  console.log('   - Create .env.development for local dev');
