      console.log('Database Test:');
      console.log(`  Status: ${results.database.message}`);
      if (results.database.details) {
        Object.entries(results.database.details).forEach(([key, value]) => {
          console.log(`  ${key}: ${value}`);
        });
      }
      console.log(`  Safe to test?: ${results.database.safeToTest ? '✅ Yes' : '❌ No'}`);
      console.log('');
    }

    // AWS test
    if (this.credentials.AWS_ACCESS_KEY_ID && this.credentials.AWS_SECRET_ACCESS_KEY) {
      results.aws = this.simulateAwsTest(
        this.credentials.AWS_ACCESS_KEY_ID,
        this.credentials.AWS_SECRET_ACCESS_KEY
      );
      console.log('AWS Credentials Test:');
      console.log(`  Status: ${results.aws.message}`);
      if (results.aws.details) {
        Object.entries(results.aws.details).forEach(([key, value]) => {
          console.log(`  ${key}: ${value}`);
        });
      }
      console.log(`  Safe to test?: ${results.aws.safeToTest ? '✅ Yes' : '❌ No'}`);
      console.log('');
    }

    // Stripe test
    if (this.credentials.STRIPE_SECRET_KEY) {
      results.stripe = this.simulateApiKeyTest(this.credentials.STRIPE_SECRET_KEY, 'Stripe');
      console.log('Stripe API Key Test:');
      console.log(`  Status: ${results.stripe.message}`);
      if (results.stripe.details) {
        Object.entries(results.stripe.details).forEach(([key, value]) => {
          console.log(`  ${key}: ${value}`);
        });
      }
      console.log(`  Safe to test?: ${results.stripe.safeToTest ? '✅ Yes' : '❌ No'}`);
      console.log('');
    }

    // Anthropic test
    if (this.credentials.ANTHROPIC_API_KEY) {
      results.anthropic = this.simulateApiKeyTest(this.credentials.ANTHROPIC_API_KEY, 'Anthropic');
      console.log('Anthropic API Key Test:');
      console.log(`  Status: ${results.anthropic.message}`);
