// Basic input validation for query parameters
const validateQueryParam = (param, type, min, max) => {
  return (req, res, next) => {
    if (req.query[param]) {
      let value = req.query[param];

      // Type validation
      if (type === 'number') {
        value = parseInt(value);
        if (isNaN(value)) {
          return res.status(400).json({ 
            error: `${param} must be a number` 
          });
        }
        if (min !== undefined && value < min) {
          return res.status(400).json({ 
            error: `${param} must be at least ${min}` 
          });
        }
        if (max !== undefined && value > max) {
          return res.status(400).json({ 
            error: `${param} cannot exceed ${max}` 
          });
        }
      } else if (type === 'string') {
        // Basic string sanitization
        value = value.toString().trim();
        if (min !== undefined && value.length < min) {
          return res.status(400).json({ 
            error: `${param} must be at least ${min} characters` 
          });
        }
        if (max !== undefined && value.length > max) {
          return res.status(400).json({ 
            error: `${param} cannot exceed ${max} characters` 
          });
        }
      }

      req.validatedQuery = req.validatedQuery || {};
      req.validatedQuery[param] = value;
    }
    next();
  };
};

