// Enhanced application with improved security and error handling

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const expressValidator = require('express-validator');
const cors = require('cors');
require('dotenv').config();

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security
app.use(cors()); // Enable CORS with proper configuration
app.use(express.json()); // Parse JSON bodies
app.use(express.urlencoded({ extended: false })); // Parse URL-encoded bodies

// Rate limiting configuration
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all requests
app.use(limiter);

// Input validation middleware setup
// Note: express-validator has been deprecated in favor of express-validator/check
// This is for demonstration; consider using the updated version

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.url} - ${req.ip}`);
  next();
});

// Basic error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't expose stack traces in production
  const errorResponse = {
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal Server Error' 
      : err.message,
    status: 'error'
  };

  res.status(err.status || 500).json(errorResponse);
});

// Validate environment variables
if (!process.env.PORT) {
  console.warn('PORT environment variable not set, defaulting to 3000');
}

// Health endpoint with validation
app.get('/health', (req, res) => {
  try {
    const healthCheck = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memoryUsage: process.memoryUsage()
    };

    res.json(healthCheck);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Health check failed' 
    });
  }
});

// Users endpoint with input validation and sanitization
app.get('/users', (req, res) => {
  try {
    // Validate query parameters if any
    const { limit, offset } = req.query;

    // Validate and sanitize limit parameter
    let sanitizedLimit = 10; // Default
    if (limit) {
      const numLimit = parseInt(limit);
      if (!isNaN(numLimit) && numLimit > 0 && numLimit <= 100) {
        sanitizedLimit = numLimit;
      } else {
        return res.status(400).json({
          error: 'Limit must be a positive number between 1 and 100'
        });
      }
    }

    // Validate and sanitize offset parameter
    let sanitizedOffset = 0;
    if (offset) {
      const numOffset = parseInt(offset);
      if (!isNaN(numOffset) && numOffset >= 0) {
        sanitizedOffset = numOffset;
      } else {
        return res.status(400).json({
          error: 'Offset must be a non-negative number'
        });
      }
    }

    // Mock database query with simulated error handling
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Sanitize output to prevent accidental data leakage
    const sanitizedUsers = users.map(user => ({
      id: user.id,
      name: user.name,
      // Email might be considered PII - consider what to expose
      // Only expose email if necessary for the use case
    }));

    res.json({
      data: sanitizedUsers,
      pagination: {
        limit: sanitizedLimit,
        offset: sanitizedOffset,
        total: users.length
      }
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ 
      error: 'Failed to fetch users', 
      status: 'error' 
    });
  }
});

// Error route examples
app.get('/error-test', (req, res, next) => {
  // Example of proper error propagation
  const err = new Error('Test error');
  err.status = 400;
  next(err);
});

// 404 handler - must be after all routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.url,
    method: req.method
  });
});

// Graceful shutdown handling
const shutdown = (signal) => {
  console.log(`Received ${signal}, shutting down gracefully...`);
  process.exit(0);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Port configuration
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle server errors
server.on('error', (error) => {
  console.error('Server error:', error);

  if (error.code === 'EADDRINUSE') {
    console.error(`Port ${PORT} is already in use`);
  }

  process.exit(1);
});

module.exports = { app, server };

