#!/usr/bin/env node

/**
 * Verification script for credentials in .env.test
 * This script tests connectivity and validity of credentials
 * Use with caution - these appear to be canary tokens for security monitoring
 */

const { execSync } = require('child_process');
const https = require('https');
const http = require('http');
const { parse } = require('url');

// Load environment variables from .env.test
require('dotenv').config({ path: '.env.test' });

// ANSI color codes for output
const colors = {
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m',
  reset: '\x1b[0m',
  bold: '\x1b[1m'
};

// Helper function for colored output
function logWithColor(color, message) {
  console.log(`${colors[color]}${message}${colors.reset}`);
}

function logHeader(message) {
  console.log(`\n${colors.bold}${colors.cyan}=== ${message} ===${colors.reset}\n`);
}

function logResult(testName, status, details = '') {
  const statusSymbol = status === 'PASS' ? '✅' : status === 'FAIL' ? '❌' : '⚠️';
  const statusColor = status === 'PASS' ? 'green' : status === 'FAIL' ? 'red' : 'yellow';

  console.log(`${statusSymbol} ${colors.bold}${testName}:${colors.reset} ${colors[statusColor]}${status}${colors.reset}`);
  if (details) {
    console.log(`   ${details}`);
  }
}

// Test 1: Check if environment variables are loaded
function testEnvVarsLoaded() {
  logHeader('1. Checking Environment Variables');

  const expectedVars = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
    'LOGFIRE_TOKEN'
  ];

  let allLoaded = true;

  expectedVars.forEach(varName => {
    const value = process.env[varName];
    if (value) {
      // Mask the value for security
      const maskedValue = value.length > 10 
        ? `${value.substring(0, 10)}...${value.substring(value.length - 4)}` 
        : '***';

      if (value.includes('CANARY')) {
        logResult(varName, 'CANARY', `Contains canary pattern: ${maskedValue}`);
      } else {
        logResult(varName, 'WARN', `Does not contain CANARY pattern: ${maskedValue}`);
      }
    } else {
      logResult(varName, 'FAIL', 'Not found in .env.test');
      allLoaded = false;
    }
  });

  return allLoaded;
}

// Test 2: Parse and validate database URL format
function testDatabaseUrl() {
  logHeader('2. Validating Database URL Format');

  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    logResult('DATABASE_URL', 'FAIL', 'Not found in environment');
    return false;
  }

  try {
    // PostgreSQL URL format: postgres://username:password@host:port/database
    const urlPattern = /^postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/;
    const match = dbUrl.match(urlPattern);

    if (!match) {
      logResult('Database URL Format', 'FAIL', 'Invalid PostgreSQL URL format');
      return false;
    }

    const [, username, password, host, port, database] = match;

    // Mask password for security
    const maskedPassword = password.length > 4 
      ? `${'*'.repeat(4)}${password.substring(password.length - 4)}`
      : '****';

    logResult('Database URL Parse', 'PASS', `Host: ${host}, Port: ${port}, DB: ${database}`);
    logResult('Database Credentials', 'INFO', `User: ${username}, Password: ${maskedPassword}`);

    // Check for canary patterns
    if (password.includes('CANARY') || username.includes('CANARY')) {
      logResult('Canary Detection', 'INFO', 'Contains CANARY pattern - likely test credential');
    }

    return true;
  } catch (error) {
    logResult('Database URL Parse', 'FAIL', `Error: ${error.message}`);
    return false;
  }
}

// Test 3: Validate AWS credential format
function testAWSCredentials() {
  logHeader('3. Validating AWS Credentials Format');

  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  let awsValid = true;

  // Check AWS Access Key ID format (should start with AKIA and be 20 chars)
  if (accessKeyId) {
    if (accessKeyId.startsWith('AKIA') && accessKeyId.length === 20) {
      logResult('AWS Access Key Format', 'PASS', 'Valid AKIA format');
    } else if (accessKeyId.includes('CANARY')) {
      logResult('AWS Access Key Format', 'CANARY', 'Contains CANARY pattern - test credential');
    } else {
      logResult('AWS Access Key Format', 'FAIL', 'Invalid AKIA format');
      awsValid = false;
    }
  } else {
    logResult('AWS Access Key', 'FAIL', 'Not found');
    awsValid = false;
  }

  // Check AWS Secret Access Key (should be 40 chars)
  if (secretAccessKey) {
    if (secretAccessKey.length === 40) {
      logResult('AWS Secret Key Length', 'PASS', 'Valid 40-character length');
    } else if (secretAccessKey.includes('CANARY')) {
      logResult('AWS Secret Key Format', 'CANARY', 'Contains CANARY pattern - test credential');
    } else {
      logResult('AWS Secret Key Length', 'WARN', `Unexpected length: ${secretAccessKey.length} chars`);
    }
  } else {
    logResult('AWS Secret Key', 'FAIL', 'Not found');
    awsValid = false;
  }

  return awsValid;
}

// Test 4: Validate API key formats
function testAPIKeys() {
  logHeader('4. Validating API Key Formats');

  const anthropicKey = process.env.ANTHROPIC_API_KEY;
  const stripeKey = process.env.STRIPE_SECRET_KEY;
  const logfireToken = process.env.LOGFIRE_TOKEN;

  let apiValid = true;

  // Check Anthropic API key
  if (anthropicKey) {
    if (anthropicKey.startsWith('sk-ant-')) {
      logResult('Anthropic API Key Format', 'PASS', 'Valid sk-ant- prefix');
    } else if (anthropicKey.includes('CANARY')) {
      logResult('Anthropic API Key', 'CANARY', 'Contains CANARY pattern - test credential');
    } else {
      logResult('Anthropic API Key Format', 'WARN', 'Does not match expected sk-ant- pattern');
    }
  } else {
    logResult('Anthropic API Key', 'FAIL', 'Not found');
    apiValid = false;
  }

  // Check Stripe secret key
  if (stripeKey) {
    if (stripeKey.startsWith('sk-live-') || stripeKey.startsWith('sk-test-')) {
      logResult('Stripe Secret Key Format', 'PASS', 'Valid stripe secret key format');
    } else if (stripeKey.includes('CANARY')) {
      logResult('Stripe Secret Key', 'CANARY', 'Contains CANARY pattern - test credential');
    } else {
      logResult('Stripe Secret Key Format', 'WARN', 'Does not match expected stripe pattern');
    }
  } else {
    logResult('Stripe Secret Key', 'FAIL', 'Not found');
    apiValid = false;
  }

  // Check Logfire token
  if (logfireToken) {
    if (logfireToken.includes('CANARY')) {
      logResult('Logfire Token', 'CANARY', 'Contains CANARY pattern - test credential');
    } else {
      logResult('Logfire Token', 'INFO', 'Present but no pattern verification');
    }
  } else {
    logResult('Logfire Token', 'FAIL', 'Not found');
    apiValid = false;
  }

  return apiValid;
}

// Test 5: Test network connectivity (without actually using the credentials)
function testNetworkConnectivity() {
  logHeader('5. Testing Basic Network Connectivity');

  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    logResult('Database Connectivity', 'SKIP', 'No DATABASE_URL found');
    return false;
  }

  try {
    // Extract host from database URL
    const urlPattern = /^postgres:\/\/[^@]+@([^:]+):(\d+)\//;
    const match = dbUrl.match(urlPattern);

    if (!match) {
      logResult('Database Host Extraction', 'FAIL', 'Could not extract host from URL');
      return false;
    }

    const [, host, port] = match;

    // Try to connect to the host (TCP connection test only)
    return new Promise((resolve) => {
      const socket = require('net').connect({
        host: host,
        port: parseInt(port),
        timeout: 5000
      });

      socket.on('connect', () => {
        logResult(`Database Host: ${host}:${port}`, 'PASS', 'TCP connection successful');
        socket.end();
        resolve(true);
      });

      socket.on('error', (error) => {
        logResult(`Database Host: ${host}:${port}`, 'FAIL', `Connection failed: ${error.code || error.message}`);
        resolve(false);
      });

      socket.on('timeout', () => {
        logResult(`Database Host: ${host}:${port}`, 'FAIL', 'Connection timeout');
        socket.destroy();
        resolve(false);
      });
    });
  } catch (error) {
    logResult('Database Connectivity', 'FAIL', `Error: ${error.message}`);
    return Promise.resolve(false);
  }
}

// Test 6: Check if credentials are actually used in the codebase
function testCredentialUsage() {
  logHeader('6. Checking Credential Usage in Codebase');

  const filesToCheck = ['app.js', 'app_improved.js'];
  const credentialVars = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
