    socket.setTimeout(3000);

    return new Promise((resolve) => {
      socket.on('error', (error) => {
        log(`✗ Connection failed: ${error.code || error.message}`, 'red');
        resolve(false);
      });

      socket.on('timeout', () => {
        log('✗ Connection timeout', 'red');
        socket.destroy();
        resolve(false);
      });
    });
  } catch (error) {
    log(`✗ Connection error: ${error.message}`, 'red');
    return false;
  }
