// Enhanced application with improved security, error handling, and input validation

const express = require('express');
const helmet = require('helmet'); // For security headers
const rateLimit = require('express-rate-limit'); // For rate limiting
const cors = require('cors'); // For CORS configuration
const app = express();

// Middleware setup
app.use(helmet()); // Set security headers

// Configure CORS
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS || 'http://localhost:3000',
  credentials: true,
  optionsSuccessStatus: 200
}));

// Parse JSON bodies
app.use(express.json({ limit: '10kb' })); // Limit request body size to prevent DoS

// Rate limiting for different endpoints
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  skipSuccessfulRequests: false,
  standardHeaders: true,
  legacyHeaders: false,
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // Stricter limit for auth-related endpoints
  message: 'Too many requests from this IP, please try again later.',
});

// Apply rate limiting
app.use(generalLimiter);

// Input validation middleware
const validateHealthQuery = (req, res, next) => {
  // Validate query parameters if any are added
  const { debug } = req.query;

  if (debug && debug !== 'true' && debug !== 'false') {
    return res.status(400).json({ 
      error: 'Invalid query parameter', 
      message: 'debug parameter must be either "true" or "false"' 
    });
  }

  next();
};

const validateUserQuery = (req, res, next) => {
  const { limit, offset } = req.query;

  // Validate limit
  if (limit && !/^\d+$/.test(limit)) {
    return res.status(400).json({ 
      error: 'Invalid query parameter', 
      message: 'limit must be a positive integer' 
    });
  }

  // Validate offset
  if (offset && !/^\d+$/.test(offset)) {
    return res.status(400).json({ 
      error: 'Invalid query parameter', 
      message: 'offset must be a positive integer' 
    });
  }

  // Set reasonable defaults and limits
  const parsedLimit = limit ? Math.min(parseInt(limit), 100) : 10; // Max 100 items
  const parsedOffset = offset ? parseInt(offset) : 0;

  req.query.parsedLimit = parsedLimit;
  req.query.parsedOffset = parsedOffset;

  next();
};

// Sanitization middleware
const sanitizeInputs = (req, res, next) => {
  // Sanitize query parameters
  for (const key in req.query) {
    if (req.query[key]) {
      // Remove any HTML/script tags from query parameters
      req.query[key] = req.query[key].toString().replace(/<[^>]*>?/gm, '');
    }
  }

  // Sanitize body parameters if present
  if (req.body) {
    for (const key in req.body) {
      if (typeof req.body[key] === 'string') {
        req.body[key] = req.body[key].replace(/<[^>]*>?/gm, '');
      }
    }
  }

  next();
};

// Error handling middleware
const errorHandler = (err, req, res, next) => {
  console.error('Error:', err.message);
  console.error('Stack:', err.stack);

  // Don't leak error details in production
  if (process.env.NODE_ENV === 'production') {
    return res.status(500).json({ 
      error: 'Internal Server Error',
      message: 'Something went wrong. Please try again later.'
    });
  }

  // Provide more details in development
  res.status(500).json({ 
    error: err.name || 'Internal Server Error',
    message: err.message,
    stack: err.stack
  });
};

const notFoundHandler = (req, res, next) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: `The requested resource ${req.originalUrl} was not found`
  });
};

// Health check endpoint with validation
app.get('/health', validateHealthQuery, sanitizeInputs, (req, res, next) => {
  try {
    const healthData = { 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage()
    };

    // Add debug info only if explicitly requested
    if (req.query.debug === 'true') {
      healthData.debug = {
        nodeVersion: process.version,
        platform: process.platform,
        env: process.env.NODE_ENV || 'development'
      };
    }

    res.json(healthData);
  } catch (error) {
    next(error);
  }
});

// Users endpoint with validation, sanitization, and pagination
app.get('/users', authLimiter, validateUserQuery, sanitizeInputs, (req, res, next) => {
  try {
    // Sample user data - in production, this would come from a database
    const allUsers = [
      { id: 1, name: 'Alice Johnson', email: 'alice.johnson@example.com' },
      { id: 2, name: 'Bob Smith', email: 'bob.smith@example.com' },
      { id: 3, name: 'Carol Davis', email: 'carol.davis@example.com' },
      { id: 4, name: 'David Wilson', email: 'david.wilson@example.com' },
      { id: 5, name: 'Eve Brown', email: 'eve.brown@example.com' },
    ];

    const limit = req.query.parsedLimit;
    const offset = req.query.parsedOffset;

    // Implement pagination
    const paginatedUsers = allUsers.slice(offset, offset + limit);

    // Sanitize user data before sending (remove sensitive info)
    const sanitizedUsers = paginatedUsers.map(user => ({
      id: user.id,
      name: user.name,
      // Email masking for privacy
      email: user.email.replace(/(?<=.).(?=.*@)/g, '*')
    }));

    res.json({
      users: sanitizedUsers,
      pagination: {
        total: allUsers.length,
        limit: limit,
        offset: offset,
        hasMore: offset + limit < allUsers.length
      }
    });
  } catch (error) {
    next(error);
  }
});

// Example of a POST endpoint with validation
app.post('/users', sanitizeInputs, (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Input validation
    if (!name || typeof name !== 'string' || name.trim().length < 2 || name.trim().length > 50) {
      return res.status(400).json({ 
        error: 'Invalid input', 
        message: 'Name must be between 2 and 50 characters' 
      });
    }

    if (!email || typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      return res.status(400).json({ 
        error: 'Invalid input', 
        message: 'Valid email address is required' 
      });
    }

    // Sanitize inputs (done by middleware, but double-check)
    const sanitizedName = name.trim().replace(/<[^>]*>?/gm, '');
    const sanitizedEmail = email.trim().replace(/<[^>]*>?/gm, '');

    // In production: save to database, generate ID, etc.
    const newUser = {
      id: Date.now(), // Temporary ID - in production use proper ID generation
      name: sanitizedName,
      email: sanitizedEmail,
      createdAt: new Date().toISOString()
    };

    // Don't send full email in response for privacy
    const responseUser = {
      id: newUser.id,
      name: newUser.name,
      email: newUser.email.replace(/(?<=.).(?=.*@)/g, '*'),
      createdAt: newUser.createdAt
    };

    res.status(201).json({
      message: 'User created successfully',
      user: responseUser
    });

  } catch (error) {
    next(error);
  }
});

// Apply error handlers
app.use(notFoundHandler);
app.use(errorHandler);

// Graceful shutdown handling
const gracefulShutdown = () => {
  console.log('Received shutdown signal, closing server gracefully...');

  // In production, you might want to close database connections here
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force close after 10 seconds
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Handle graceful shutdown
process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

module.exports = app;

