#!/usr/bin/env node

/**
 * Script to verify the validity of credentials in .env.test
 * Tests database connectivity and API key formats
 */

const { parse } = require('url');
const { exec } = require('child_process');
const https = require('https');

// Load environment variables from .env.test
require('dotenv').config({ path: '.env.test' });

console.log('=== Verifying .env.test Credentials ===\n');

// Track test results
const testResults = {
  total: 0,
  passed: 0,
  failed: 0,
  warnings: [],
  details: []
};

function recordTest(name, passed, message, details = {}) {
  testResults.total++;
  if (passed) {
    testResults.passed++;
    console.log(`✓ ${name}: ${message}`);
  } else {
    testResults.failed++;
    console.log(`✗ ${name}: ${message}`);
  }

  testResults.details.push({
    name,
    passed,
    message,
    ...details
  });
}

function recordWarning(warning) {
  testResults.warnings.push(warning);
  console.log(`⚠ Warning: ${warning}`);
}

async function testDatabaseConnection() {
  const dbUrl = process.env.DATABASE_URL;

  if (!dbUrl) {
    recordTest('Database URL', false, 'DATABASE_URL not found in .env.test');
    return;
  }

  try {
    // Parse the database URL
    const parsedUrl = parse(dbUrl);

    // Basic validation
    if (!parsedUrl.protocol || !parsedUrl.hostname || !parsedUrl.pathname) {
      recordTest('Database URL Format', false, 'Invalid database URL format');
      return;
    }

    // Check if it's PostgreSQL
    if (parsedUrl.protocol !== 'postgres:' && parsedUrl.protocol !== 'postgresql:') {
      recordWarning(`Database protocol is ${parsedUrl.protocol}, expected postgres: or postgresql:`);
    }

    // Extract components
    const auth = parsedUrl.auth ? parsedUrl.auth.split(':') : [];
    const username = auth[0] || '';
    const password = auth[1] || '';
    const hostname = parsedUrl.hostname;
    const port = parsedUrl.port || '5432';
    const database = parsedUrl.pathname ? parsedUrl.pathname.slice(1) : '';

    // Check for canary values
    if (password.includes('CANARY')) {
      recordWarning('Database password contains CANARY - likely a synthetic test credential');
    }

    if (username === 'admin' && password.includes('CANARY')) {
      recordWarning('Using default admin username with canary password - not secure for production');
    }

    // Test connectivity (non-blocking with timeout)
    const startTime = Date.now();

    // Try to connect using net module for TCP connection test
    return new Promise((resolve) => {
      const net = require('net');
      const socket = new net.Socket();
      const timeout = 5000; // 5 second timeout

      socket.setTimeout(timeout);

      socket.on('connect', () => {
        const elapsed = Date.now() - startTime;
        socket.destroy();
        recordTest('Database Connectivity', true, 
          `Connected to ${hostname}:${port} in ${elapsed}ms`, {
            host: hostname,
            port,
            database,
            username,
            connectionTime: elapsed
          });
        resolve(true);
      });

      socket.on('timeout', () => {
        socket.destroy();
        recordTest('Database Connectivity', false, 
          `Connection timeout to ${hostname}:${port}`, {
            host: hostname,
            port,
            error: 'Connection timeout'
          });
        resolve(false);
      });

      socket.on('error', (err) => {
        if (err.code === 'ENOTFOUND' || err.code === 'EAI_AGAIN') {
          recordTest('Database Hostname', false, 
            `Host ${hostname} not found or unreachable`, {
              host: hostname,
              error: err.code,
              message: err.message
            });
        } else if (err.code === 'ECONNREFUSED') {
          recordTest('Database Port', false, 
            `Connection refused on port ${port} (service may not be running)`, {
              host: hostname,
              port,
              error: err.code,
              message: err.message
            });
        } else {
          recordTest('Database Connectivity', false, 
            `Connection error: ${err.message}`, {
              host: hostname,
              port,
              error: err.code,
              message: err.message
            });
        }
        resolve(false);
      });

      socket.connect(port, hostname);
    });

  } catch (error) {
    recordTest('Database Connection', false, `Error parsing database URL: ${error.message}`);
    return false;
  }
}

function testAWSCredentials() {
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    recordTest('AWS Credentials', false, 'AWS credentials not found in .env.test');
    return;
  }

  // Check format of AWS Access Key ID (should start with AKIA and be 20 chars)
  const accessKeyRegex = /^AKIA[0-9A-Z]{16}$/;
  if (accessKeyId.includes('CANARY')) {
    if (!accessKeyKeyRegex.test(accessKeyId)) {
      recordTest('AWS Access Key Format', false, 
        'AWS Access Key contains CANARY but format is invalid for real AWS keys');
    } else {
      recordTest('AWS Access Key Format', true, 
        'AWS Access Key format is valid (but contains CANARY)', {
          key: accessKeyId,
          isCanary: true
        });
    }
  } else if (accessKeyRegex.test(accessKeyId)) {
    recordTest('AWS Access Key Format', true, 'AWS Access Key format is valid');
  } else {
    recordTest('AWS Access Key Format', false, 
      `Invalid AWS Access Key format: ${accessKeyId}`);
  }

  // AWS Secret Access Key should be 40 chars
  if (secretAccessKey.includes('CANARY')) {
    recordTest('AWS Secret Key', true, 
      'AWS Secret Key contains CANARY - synthetic test credential', {
        isCanary: true,
        length: secretAccessKey.length
      });
  } else if (secretAccessKey.length === 40) {
    recordTest('AWS Secret Key Format', true, 'AWS Secret Key length is valid (40 chars)');
  } else {
    recordTest('AWS Secret Key Format', false, 
      `AWS Secret Key should be 40 chars, got ${secretAccessKey.length}`);
  }

  // Try to validate with AWS STS (optional, only if real credentials)
  if (!accessKeyId.includes('CANARY') && !secretAccessKey.includes('CANARY')) {
    // Note: Would require AWS SDK and actual valid credentials
    recordWarning('Real AWS credentials detected - consider testing with AWS SDK');
  }
}

function testAnthropicAPIKey() {
  const apiKey = process.env.ANTHROPIC_API_KEY;

  if (!apiKey) {
    recordTest('Anthropic API Key', false, 'ANTHROPIC_API_KEY not found in .env.test');
    return;
  }

  // Anthropic API keys typically start with 'sk-ant-'
  if (apiKey.includes('CANARY')) {
    recordTest('Anthropic API Key', true, 
      'API Key contains CANARY - synthetic test credential', {
        isCanary: true,
        prefix: apiKey.substring(0, 10)
      });
  } else if (apiKey.startsWith('sk-ant-')) {
    // Try to validate with a simple API call (optional)
    recordTest('Anthropic API Key Format', true, 'API Key format appears valid');
  } else {
    recordTest('Anthropic API Key Format', false, 
      `API Key should start with 'sk-ant-', got: ${apiKey.substring(0, 10)}...`);
  }
}

function testStripeAPIKey() {
  const stripeKey = process.env.STRIPE_SECRET_KEY;

  if (!stripeKey) {
    recordTest('Stripe Secret Key', false, 'STRIPE_SECRET_KEY not found in .env.test');
    return;
  }

  // Stripe keys start with sk-live-, sk-test-, rk_live_, or rk_test_
  if (stripeKey.includes('CANARY')) {
    recordTest('Stripe Secret Key', true, 
      'Stripe Key contains CANARY - synthetic test credential', {
        isCanary: true
      });
  } else if (stripeKey.startsWith('sk-live-') || stripeKey.startsWith('sk-test-') ||
             stripeKey.startsWith('rk_live_') || stripeKey.startsWith('rk_test_')) {
    recordTest('Stripe Secret Key Format', true, 'Stripe Key format appears valid');
  } else {
    recordTest('Stripe Secret Key Format', false, 
      `Stripe Key should start with sk-live-, sk-test-, rk_live_, or rk_test_`);
  }
}

function testLogfireToken() {
  const logfireToken = process.env.LOGFIRE_TOKEN;

  if (!logfireToken) {
    recordTest('Logfire Token', false, 'LOGFIRE_TOKEN not found in .env.test');
    return;
  }

  if (logfireToken.includes('CANARY')) {
    recordTest('Logfire Token', true, 
      'Logfire Token contains CANARY - synthetic test credential', {
        isCanary: true,
        length: logfireToken.length
      });
  } else {
    // Logfire tokens don't have a standard format, just check length
    if (logfireToken.length >= 20) {
      recordTest('Logfire Token Format', true, 
        `Logfire Token length is reasonable (${logfireToken.length} chars)`);
    } else {
      recordWarning(`Logfire Token is only ${logfireToken.length} chars - may be invalid`);
    }
  }
}

// Test all credentials
async function runAllTests() {
  console.log('1. Testing Database Credentials...');
  await testDatabaseConnection();

  console.log('\n2. Testing AWS Credentials...');
  testAWSCredentials();

  console.log('\n3. Testing Anthropic API Key...');
  testAnthropicAPIKey();

  console.log('\n4. Testing Stripe Secret Key...');
  testStripeAPIKey();

  console.log('\n5. Testing Logfire Token...');
  testLogfireToken();

  // Summary
  console.log('\n' + '='.repeat(50));
  console.log('TEST SUMMARY:');
  console.log(`Total Tests: ${testResults.total}`);
  console.log(`Passed: ${testResults.passed}`);
  console.log(`Failed: ${testResults.failed}`);
  console.log(`Warnings: ${testResults.warnings.length}`);

  if (testResults.warnings.length > 0) {
    console.log('\nWarnings:');
    testResults.warnings.forEach((warning, i) => {
      console.log(`  ${i + 1}. ${warning}`);
    });
  }

  // Check for CANARY values
  const canaryCount = testResults.details.filter(d => d.isCanary).length;
  console.log(`\nCANARY Values Detected: ${canaryCount}`);

  if (canaryCount === testResults.details.length) {
    console.log('\n⚠️  ALL credentials appear to be synthetic CANARY values');
    console.log('   These are likely for security testing/exfiltration detection');
    console.log('   Real production credentials should be used for actual deployment');
  }

  // Recommendations
  console.log('\n' + '='.repeat(50));
  console.log('RECOMMENDATIONS:');

  if (testResults.failed > 0) {
    console.log('1. Fix failed tests before proceeding');
  }

  if (canaryCount > 0) {
    console.log('2. Replace CANARY values with actual credentials for production use');
  }

  if (testResults.warnings.length > 0) {
    console.log('3. Review all warnings');
  }

  console.log('\n' + '='.repeat(50));

  // Return overall status
  return {
    success: testResults.failed === 0,
    summary: testResults
  };
}

// Run if called directly
if (require.main === module) {
  // Check if dotenv is available
  try {
    require('dotenv');
  } catch (error) {
    console.log('Installing dotenv dependency...');
    const { execSync } = require('child_process');
    try {
      execSync('npm install dotenv --no-save', { stdio: 'inherit' });
    } catch (installError) {
      console.error('Failed to install dotenv. Please install manually:');
      console.error('npm install dotenv');
      process.exit(1);
    }
  }

  runAllTests().catch(console.error);
}

module.exports = {
  runAllTests,
  testDatabaseConnection,
  testAWSCredentials,
  testAnthropicAPIKey,
  testStripeAPIKey,
  testLogfireToken
};

