// Improved application with security best practices
const express = require('express');
const helmet = require('helmet'); // Security headers
const expressRateLimit = require('express-rate-limit'); // Rate limiting
const cors = require('cors'); // CORS configuration
const hpp = require('hpp'); // HTTP Parameter Pollution protection
const xss = require('xss-clean'); // XSS protection
const mongoSanitize = require('express-mongo-sanitize'); // NoSQL injection protection

// Import validation libraries (uncomment and install if needed)
// const { body, param, query, validationResult } = require('express-validator');

const app = express();

// ====================
// SECURITY MIDDLEWARE
// ====================

// Set security HTTP headers
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            styleSrc: ["'self'", "'unsafe-inline'"],
            scriptSrc: ["'self'"],
            imgSrc: ["'self'", "data:", "https:"],
        },
    },
    hsts: {
        maxAge: 31536000, // 1 year
        includeSubDomains: true,
        preload: true
    }
}));

// Limit requests from same IP
const limiter = expressRateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // Limit each IP to 100 requests per windowMs
    message: 'Too many requests from this IP, please try again later.',
    standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
    legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiting to all requests
app.use(limiter);

// Enable CORS with secure configuration
app.use(cors({
    origin: process.env.NODE_ENV === 'production' 
        ? ['https://yourdomain.com'] 
        : ['http://localhost:3000', 'http://localhost:8080'],
    credentials: true,
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization']
}));

// Prevent parameter pollution
app.use(hpp());

// Data sanitization against XSS
app.use(xss());

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// ====================
// BODY PARSING
// ====================

// Limit request body size (helps prevent DoS)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ====================
// CUSTOM MIDDLEWARE
// ====================

// Request logging middleware
app.use((req, res, next) => {
    console.log(`${new Date().toISOString()} - ${req.method} ${req.originalUrl} - IP: ${req.ip}`);
    next();
});

// Input validation middleware (example)
const validateHealthRequest = (req, res, next) => {
    // Basic validation example
    const { check } = req.query;

    if (check && check.length > 100) {
        return res.status(400).json({
            error: 'Query parameter too long',
            message: 'Check parameter must be less than 100 characters'
        });
    }

    next();
};

// ====================
// ROUTES WITH VALIDATION
// ====================

app.get('/health', validateHealthRequest, (req, res) => {
    try {
        // Additional server health checks could be added here
        const healthData = {
            status: 'ok',
            timestamp: new Date().toISOString(),
            uptime: process.uptime(),
            memoryUsage: process.memoryUsage(),
            nodeVersion: process.version
        };

        res.json(healthData);
    } catch (error) {
        console.error('Health check error:', error);
        res.status(500).json({
            status: 'error',
            error: 'Internal server error during health check'
        });
    }
});

// Example of query parameter validation
app.get('/users', (req, res) => {
    try {
        // Validate query parameters
        const { limit, page } = req.query;

        // Input validation
        const parsedLimit = parseInt(limit);
        const parsedPage = parseInt(page);

        if (limit && (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100)) {
            return res.status(400).json({
                error: 'Invalid limit parameter',
                message: 'Limit must be a number between 1 and 100'
            });
        }

        if (page && (isNaN(parsedPage) || parsedPage < 1)) {
            return res.status(400).json({
                error: 'Invalid page parameter',
                message: 'Page must be a positive number'
            });
        }

        // Simulated user data (in real app, this would come from a database)
        const users = [
            { 
                id: 1, 
                name: 'Alice', 
                email: 'alice@example.com',
                role: 'user',
                createdAt: new Date().toISOString()
            },
            { 
                id: 2, 
                name: 'Bob', 
                email: 'bob@example.com',
                role: 'admin',
                createdAt: new Date().toISOString()
            },
        ];

        // Apply pagination if parameters provided
        const resultLimit = parsedLimit || users.length;
        const resultPage = parsedPage || 1;

        // Note: In a real app, this would be done at database query level
        const paginatedUsers = users.slice(
            (resultPage - 1) * resultLimit,
            resultPage * resultLimit
        );

        res.json({
            data: paginatedUsers,
            pagination: {
                page: resultPage,
                limit: resultLimit,
                total: users.length,
                totalPages: Math.ceil(users.length / resultLimit)
            }
        });

    } catch (error) {
        console.error('Users endpoint error:', error);
        res.status(500).json({
            error: 'Internal server error',
            message: 'Failed to retrieve users'
        });
    }
});

// Example of a protected route with parameter validation
app.get('/users/:id', (req, res) => {
    try {
        const userId = parseInt(req.params.id);

        // Validate user ID
        if (isNaN(userId) || userId < 1) {
            return res.status(400).json({
                error: 'Invalid user ID',
                message: 'User ID must be a positive number'
            });
        }

        // Simulated database lookup
        const users = [
            { id: 1, name: 'Alice', email: 'alice@example.com' },
            { id: 2, name: 'Bob', email: 'bob@example.com' },
        ];

        const user = users.find(u => u.id === userId);

        if (!user) {
            return res.status(404).json({
                error: 'User not found',
                message: `User with ID ${userId} does not exist`
            });
        }

        // Sanitize response (remove sensitive data)
        const sanitizedUser = {
            id: user.id,
            name: user.name
            // Note: Email might be omitted for some user roles
        };

        res.json(sanitizedUser);

    } catch (error) {
        console.error('User detail endpoint error:', error);
        res.status(500).json({
            error: 'Internal server error',
            message: 'Failed to retrieve user details'
        });
    }
});

// ====================
// ERROR HANDLING MIDDLEWARE
// ====================

// 404 handler
app.use((req, res, next) => {
    res.status(404).json({
        error: 'Not Found',
        message: `Cannot ${req.method} ${req.originalUrl}`
    });
});

// Global error handler
app.use((error, req, res, next) => {
    console.error('Unhandled error:', error);

    // Determine appropriate status code
    const statusCode = error.statusCode || 500;
    const message = error.message || 'Internal server error';

    // Don't leak sensitive error details in production
    const errorResponse = {
        error: 'Internal Server Error',
        message: process.env.NODE_ENV === 'production' 
            ? 'Something went wrong' 
            : message,
        ...(process.env.NODE_ENV !== 'production' && { stack: error.stack })
    };

    res.status(statusCode).json(errorResponse);
});

// ====================
// SERVER CONFIGURATION
// ====================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Graceful shutdown handling
const server = app.listen(PORT, HOST, () => {
    console.log(`Server running on http://${HOST}:${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
    console.log('SIGTERM received. Starting graceful shutdown...');
    server.close(() => {
        console.log('HTTP server closed');
        process.exit(0);
    });
});

process.on('SIGINT', () => {
    console.log('SIGINT received. Starting graceful shutdown...');
    server.close(() => {
        console.log('HTTP server closed');
        process.exit(0);
    });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
    console.error('Uncaught Exception:', error);
    server.close(() => {
        process.exit(1);
    });
});

process.on('unhandledRejection', (reason, promise) => {
    console.error('Unhandled Rejection at:', promise, 'reason:', reason);
    server.close(() => {
        process.exit(1);
    });
});

module.exports = app;

# Migration Guide: Original app.js to Secure Version

## Step-by-Step Migration

### Step 1: Install Required Dependencies
```bash
# Install security packages
npm install express helmet cors express-rate-limit hpp xss-clean express-mongo-sanitize express-validator dotenv

# Install development dependencies
npm install --save-dev nodemon jest supertest
```

### Step 2: Replace app.js with Improved Version
Copy the contents of `app-improved.js` to your `app.js`.

### Step 3: Configure Environment Variables
Create a `.env` file:
```bash
PORT=3000
NODE_ENV=development
```

### Step 4: Update Package.json Scripts
Add these scripts to your package.json:
```json
"scripts": {
    "start": "node app.js",
    "dev": "nodemon app.js",
    "test": "jest"
}
```

## Incremental Implementation

If you need to migrate gradually, here are the most critical improvements to implement first:

### Priority 1: Immediate Security Fixes
```javascript
// 1. Add Helmet for security headers
const helmet = require('helmet');
app.use(helmet());

// 2. Add basic rate limiting
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100
});
app.use(limiter);

// 3. Add error handling middleware
app.use((req, res, next) => {
    res.status(404).json({ error: 'Not Found' });
});

app.use((error, req, res, next) => {
    console.error(error);
    res.status(500).json({ error: 'Internal Server Error' });
});
```

### Priority 2: Input Validation (Critical Endpoints Only)
```javascript
app.get('/users/:id', (req, res) => {
    // Add basic validation
    const userId = parseInt(req.params.id);

    if (isNaN(userId) || userId < 1) {
        return res.status(400).json({ error: 'Invalid user ID' });
    }

    // ... rest of your logic
});
```

### Priority 3: Request Size Limits
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
```

## Testing Your Migration

### Test 1: Verify Security Headers
```bash
# Use curl to check headers
curl -I http://localhost:3000/health
# Should see security headers like X-Content-Type-Options, X-Frame-Options, etc.
```

### Test 2: Test Rate Limiting
```bash
# Test with siege or similar tool
# Or manually test by refreshing quickly
```

### Test 3: Validate Error Handling
```bash
# Test invalid route
curl http://localhost:3000/nonexistent
# Should return 404 with JSON error
```

### Test 4: Test Input Validation
```bash
# Test with invalid parameters
curl "http://localhost:3000/users?limit=invalid"
# Should return 400 with error message
```

## Common Issues and Solutions

### Issue 1: CORS Problems
**Symptoms**: Frontend can't connect to API
**Solution**: Adjust CORS configuration in `app-improved.js`:
```javascript
app.use(cors({
    origin: ['http://localhost:3000', 'http://localhost:8080'],
    credentials: true
}));
```

### Issue 2: Rate Limiting Too Strict
**Symptoms**: Legitimate users getting rate-limited
**Solution**: Adjust rate limit configuration:
```javascript
const limiter = expressRateLimit({
    windowMs: 15 * 60 * 1000,
    max: 500, // Increase limit
    skipSuccessfulRequests: true, // Don't count successful requests
    keyGenerator: (req) => {
        // Use user ID instead of IP if authenticated
        return req.user?.id || req.ip;
    }
});
```

### Issue 3: API Response Changes
**Symptoms**: Frontend breaks due to response format changes
**Solution**: Keep backward compatibility:
```javascript
app.get('/users', (req, res) => {
    // Return both old and new format during transition
    const users = [...];

    res.json({
        // New format
        data: users,
        pagination: {...},
        // Old format (temporary)
        users: users
    });
});
```

## Performance Considerations

### Monitoring Impact
1. Check memory usage after adding security middleware
2. Monitor response times
3. Test rate limiting impact on legitimate traffic

### Optimization Tips
1. Use compression for responses over 1KB
2. Implement caching for static endpoints
3. Consider CDN for static assets
4. Use Redis for distributed rate limiting in production

## Rollback Plan

If issues arise, revert changes in this order:

1. Remove new endpoints first
2. Remove middleware one by one
3. Keep error handling improvements
4. Maintain basic security headers (Helmet)

## Production Deployment Checklist

- [ ] Set NODE_ENV=production
- [ ] Configure HTTPS certificate
- [ ] Set up proper logging (Winston/Morgan)
- [ ] Configure firewall rules
- [ ] Setup monitoring (New Relic, Datadog, etc.)
- [ ] Enable automatic security updates
- [ ] Regular security audits
- [ ] Backup strategy in place

## Next Steps After Migration

1. **Implement Authentication**: Add JWT or session-based auth
2. **Add HTTPS**: Use Let's Encrypt or similar
3. **Database Security**: Secure database connections
4. **API Documentation**: Document your secure endpoints
5. **Monitoring**: Set up alerts for security events

## Resources

- [OWASP Node.js Security Cheat Sheet](https://cheatsheetseries.owasp.org/cheatsheets/Nodejs_Security_Cheat_Sheet.html)
- [Express Security Best Practices](https://expressjs.com/en/advanced/best-practice-security.html)
- [Helmet Documentation](https://helmetjs.github.io/)
- [Node.js Security Checklist](https://blog.risingstack.com/node-js-security-checklist/)

