#!/usr/bin/env node

/**
 * Test script to verify connectivity of test credentials
 * WARNING: These are canary credentials - DO NOT USE IN PRODUCTION
 */

const https = require('https');
const http = require('http');
const { URL } = require('url');

// Load environment variables from .env.test
require('dotenv').config({ path: '.env.test' });

console.log('=== Testing Canary Credentials Connectivity ===\n');
console.log('WARNING: These are canary/trap credentials for security monitoring\n');

const tests = [];

// Test 1: Parse DATABASE_URL
tests.push({
    name: 'DATABASE_URL Parsing',
    fn: () => {
        const dbUrl = process.env.DATABASE_URL;
        if (!dbUrl) {
            throw new Error('DATABASE_URL not found in .env.test');
        }

        try {
            // Try to parse the PostgreSQL URL
            // Note: We won't actually connect, just parse
            const url = new URL(dbUrl);
            const protocol = url.protocol;
            const hostname = url.hostname;
            const port = url.port;
            const username = url.username;

            console.log(`  Parsed DATABASE_URL: ${protocol}//${username}@${hostname}:${port}`);

            if (protocol !== 'postgres:') {
                return { success: false, message: 'Expected postgres protocol' };
            }

            if (!hostname.includes('db.internal')) {
                return { success: false, message: 'Hostname pattern check failed' };
            }

            return { success: true, message: 'URL parsing successful' };
        } catch (error) {
            return { success: false, message: `URL parsing error: ${error.message}` };
        }
    }
});

// Test 2: AWS Credentials Format
tests.push({
    name: 'AWS Credentials Format',
    fn: () => {
        const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
        const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

        if (!accessKeyId || !secretAccessKey) {
            throw new Error('AWS credentials not found in .env.test');
        }

        // Check if they contain the canary marker
        const hasCanaryMarker = accessKeyId.includes('CANARY') && 
                               secretAccessKey.includes('CANARY');

        if (!hasCanaryMarker) {
            return { success: false, message: 'Missing CANARY marker in AWS credentials' };
        }

        // Check AWS Access Key format (should start with AKIA)
        if (!accessKeyId.startsWith('AKIA')) {
            return { success: false, message: 'Invalid AWS Access Key format' };
        }

        return { success: true, message: 'AWS credentials have correct format with CANARY markers' };
    }
});

// Test 3: API Key Formats
tests.push({
    name: 'API Key Formats',
    fn: () => {
        const anthropicKey = process.env.ANTHROPIC_API_KEY;
        const stripeKey = process.env.STRIPE_SECRET_KEY;
        const logfireToken = process.env.LOGFIRE_TOKEN;

        const checks = [];

        if (anthropicKey) {
            const isValid = anthropicKey.includes('CANARY') && 
                           anthropicKey.startsWith('sk-ant-');
            checks.push({
                key: 'ANTHROPIC_API_KEY',
                valid: isValid,
                message: isValid ? 'Valid format with CANARY' : 'Invalid format'
            });
        }

        if (stripeKey) {
            const isValid = stripeKey.includes('CANARY') && 
                           stripeKey.startsWith('sk-live-');
            checks.push({
                key: 'STRIPE_SECRET_KEY',
                valid: isValid,
                message: isValid ? 'Valid format with CANARY' : 'Invalid format'
            });
        }

        if (logfireToken) {
            const isValid = logfireToken.includes('CANARY');
            checks.push({
                key: 'LOGFIRE_TOKEN',
                valid: isValid,
                message: isValid ? 'Contains CANARY marker' : 'Missing CANARY marker'
            });
        }

        const allValid = checks.every(c => c.valid);
        const messages = checks.map(c => `    ${c.key}: ${c.message}`).join('\n');

        return {
            success: allValid,
            message: `API Key checks:\n${messages}`
        };
    }
});

// Test 4: Network Connectivity Test (without using actual credentials)
tests.push({
    name: 'Network Connectivity',
    fn: () => {
        return new Promise((resolve) => {
            // Test a known public endpoint to check network connectivity
            const options = {
                hostname: 'httpbin.org',
                port: 443,
                path: '/ip',
                method: 'GET',
                timeout: 5000
            };

            const req = https.request(options, (res) => {
                let data = '';
                res.on('data', (chunk) => {
                    data += chunk;
                });

                res.on('end', () => {
                    try {
                        const response = JSON.parse(data);
                        resolve({
                            success: true,
                            message: `Network connectivity OK. Tested with httpbin.org (Status: ${res.statusCode})`
                        });
                    } catch (e) {
                        resolve({
                            success: true,
                            message: `Network connectivity OK. Received response (Status: ${res.statusCode})`
                        });
                    }
                });
            });

            req.on('error', (error) => {
                resolve({
                    success: false,
                    message: `Network error: ${error.message}`
                });
