  const content = fs.readFileSync(filePath, 'utf8');
  const envVars = {};

  content.split('\n').forEach(line => {
    line = line.trim();
    if (line && !line.startsWith('#')) {
      const [key, ...valueParts] = line.split('=');
      if (key && valueParts.length > 0) {
        envVars[key.trim()] = valueParts.join('=').trim();
      }
    }
  });

  return envVars;
}

// Test DNS resolution for a host
async function testDNSResolution(hostname) {
  return new Promise((resolve) => {
    dns.lookup(hostname, (err, address) => {
      if (err) {
        console.log(`  ❌ DNS resolution failed: ${err.message}`);
        resolve(false);
      } else {
        console.log(`  ✅ DNS resolves to: ${address}`);
        resolve(true);
      }
    });
  });
}

// Test TCP connectivity
function testTCPConnectivity(hostname, port) {
  try {
    // Use timeout to prevent hanging
    execSync(`timeout 5 nc -z -w 3 ${hostname} ${port}`, { stdio: 'pipe' });
    console.log(`  ✅ Port ${port} is reachable`);
    return true;
  } catch (error) {
    console.log(`  ❌ Port ${port} is NOT reachable`);
    console.log(`     Error: ${error.message}`);
    return false;
  }
}

