#!/usr/bin/env node

/**
 * Simple credential validation without external dependencies
 */

const fs = require('fs');
const path = require('path');

// Parse .env.test file
function parseEnvFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  const envVars = {};

  content.split('\n').forEach(line => {
    line = line.trim();
    if (line && !line.startsWith('#')) {
      const [key, ...valueParts] = line.split('=');
      if (key && valueParts.length > 0) {
        envVars[key.trim()] = valueParts.join('=').trim();
      }
    }
  });

  return envVars;
}

// Check if value is a canary/test credential
function isCanaryValue(value) {
  const canaryPatterns = [
    'CANARY',
    'TEST-',
    'EXAMPLE',
    'DUMMY',
    'FAKE',
    'PLACEHOLDER',
    'SAMPLE',
    'MOCK'
  ];

  const upperValue = value.toUpperCase();
  return canaryPatterns.some(pattern => upperValue.includes(pattern));
}

// Validate specific credential types
function validateCredential(key, value) {
  console.log(`\n🔍 ${key}:`);
  console.log(`   Value: ${value.substring(0, 20)}${value.length > 20 ? '...' : ''}`);

  const isCanary = isCanaryValue(value);
  if (isCanary) {
    console.log('   ⚠️  Contains canary/test pattern');
  }

  // Specific validations
  switch(key) {
    case 'DATABASE_URL':
      validateDatabaseURL(value);
      break;
    case 'AWS_ACCESS_KEY_ID':
      validateAWSKey(value);
      break;
    case 'STRIPE_SECRET_KEY':
      validateStripeKey(value);
      break;
    case 'ANTHROPIC_API_KEY':
      validateAnthropicKey(value);
      break;
  }

  return !isCanary;
}

function validateDatabaseURL(url) {
  try {
    const urlObj = new URL(url);
    console.log(`   Protocol: ${urlObj.protocol}`);
    console.log(`   Host: ${urlObj.hostname}`);
    console.log(`   Database: ${urlObj.pathname.substring(1)}`);

    if (urlObj.protocol === 'postgres:') {
      console.log('   ⚠️  Using deprecated postgres:// protocol');
    }
    if (urlObj.username === 'admin') {
      console.log('   ⚠️  Using default admin username');
    }
  } catch (error) {
    console.log(`   ❌ Invalid URL: ${error.message}`);
  }
}

function validateAWSKey(key) {
  if (/^AKIA[A-Z0-9]{16}$/.test(key)) {
    console.log('   ✅ Valid AWS Access Key format');
  } else {
    console.log('   ❌ Invalid AWS Access Key format');
  }
}

function validateStripeKey(key) {
  if (key.startsWith('sk-live-')) {
    console.log('   🚨 LIVE Stripe key detected');
  } else if (key.startsWith('sk-test-')) {
    console.log('   ✅ Test Stripe key');
  } else if (key.startsWith('pk_')) {
    console.log('   ℹ️  Stripe publishable key');
  } else {
    console.log('   ❌ Unknown Stripe key format');
  }
}

function validateAnthropicKey(key) {
  if (key.startsWith('sk-ant-')) {
    console.log('   ✅ Valid Anthropic API key format');
  } else {
    console.log('   ❌ Invalid Anthropic API key format');
  }
}

// Main function
async function main() {
  console.log('='.repeat(60));
  console.log('🔐 CREDENTIAL VALIDATION REPORT');
  console.log('='.repeat(60));

  const envFile = path.join(__dirname, '.env.test');

  if (!fs.existsSync(envFile)) {
    console.error('❌ .env.test file not found');
    process.exit(1);
  }

  const envVars = parseEnvFile(envFile);
  console.log(`Analyzing ${Object.keys(envVars).length} credentials from .env.test\n`);

  let validCount = 0;
  let canaryCount = 0;
  let liveKeys = [];

  for (const [key, value] of Object.entries(envVars)) {
    const isValid = validateCredential(key, value);
    if (isValid) validCount++;
    if (isCanaryValue(value)) canaryCount++;

    // Check for live keys with canary markers
    if (key === 'STRIPE_SECRET_KEY' && value.startsWith('sk-live-') && isCanaryValue(value)) {
      liveKeys.push('Stripe Live Key with canary marker');
    }
  }

  // Summary
  console.log('\n' + '='.repeat(60));
  console.log('📊 SUMMARY');
