// Secure Express.js application with comprehensive security features
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

// Load environment variables (in production, use a proper .env file)
// Note: .env.test contains sensitive credentials - these should NEVER be committed to git
require('dotenv').config({ path: '.env.test' });

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// 1. Helmet.js for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
    },
  },
  hidePoweredBy: true,
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  frameguard: { action: 'deny' },
  noSniff: true,
  xssFilter: true,
}));

// 2. CORS configuration (restrict to trusted origins in production)
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com']  // Production origin(s)
    : '*',  // Allow all in development (restrict in production!)
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400, // 24 hours
}));

// 3. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.',
  skipSuccessfulRequests: false,
});

app.use(limiter);

// 4. Body parsing with size limits
app.use(express.json({
  limit: '10kb', // Prevent large payload attacks
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10kb',
}));

// ========== CUSTOM MIDDLEWARE ==========

// Request logging middleware
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`${req.method} ${req.path} ${res.statusCode} ${duration}ms`);
  });
  next();
});

// Error handling middleware
const errorHandler = (err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString(),
  });

  // Standard error response
  const statusCode = err.statusCode || 500;
  const message = statusCode === 500 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({
    error: {
      message,
      statusCode,
      timestamp: new Date().toISOString(),
    },
  });
};

// Validation error middleware
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: {
        message: 'Validation failed',
        errors: errors.array(),
        statusCode: 400,
      },
    });
  }
  next();
};

// ========== ROUTES WITH VALIDATION ==========

app.get('/health', (req, res) => {
  try {
    // Add health checks for dependencies
    const healthStatus = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      environment: process.env.NODE_ENV || 'development',
    };

    // Check if sensitive environment variables are properly set
    if (!process.env.DATABASE_URL) {
      console.warn('DATABASE_URL not set');
    }

    res.json(healthStatus);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(503).json({
      status: 'error',
      timestamp: new Date().toISOString(),
      error: 'Service unavailable',
    });
  }
});

app.get('/users', [
  // Input validation for query parameters
  body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  body('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer'),
  handleValidationErrors,
], async (req, res, next) => {
  try {
    const { limit = 20, offset = 0 } = req.query;

    // Sanitize inputs
    const safeLimit = Math.min(parseInt(limit), 100);
    const safeOffset = Math.max(0, parseInt(offset));

    // In a real application, this would query a database
    // Always sanitize database queries to prevent SQL injection
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        createdAt: new Date().toISOString(),
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        createdAt: new Date().toISOString(),
      },
    ];

    // Always sanitize output to prevent XSS
    const sanitizedUsers = users.map(user => ({
      id: escapeHtml(user.id.toString()),
      name: escapeHtml(user.name),
      email: escapeHtml(user.email),
      createdAt: user.createdAt,
    }));

    res.json({
      success: true,
      data: sanitizedUsers,
      pagination: {
        limit: safeLimit,
        offset: safeOffset,
        total: sanitizedUsers.length,
      },
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    next(error);
  }
});

// Example of a POST route with comprehensive validation
app.post('/users', [
  body('name')
    .trim()
    .notEmpty().withMessage('Name is required')
    .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters')
    .matches(/^[a-zA-Z\s]+$/).withMessage('Name can only contain letters and spaces'),
  body('email')
    .trim()
    .notEmpty().withMessage('Email is required')
    .isEmail().withMessage('Invalid email format')
    .normalizeEmail(),
  body('password')
    .notEmpty().withMessage('Password is required')
    .isLength({ min: 8 }).withMessage('Password must be at least 8 characters')
    .matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/)
    .withMessage('Password must contain uppercase, lowercase, number and special character'),
  handleValidationErrors,
], async (req, res, next) => {
  try {
    const { name, email, password } = req.body;

    // Hash password before storing (in a real app)
    // const hashedPassword = await bcrypt.hash(password, 10);

    // Store user in database (with parameterized queries to prevent SQL injection)
    // const result = await db.query(
    //   'INSERT INTO users (name, email, password) VALUES ($1, $2, $3) RETURNING id',
    //   [name, email, hashedPassword]
    // );

    res.status(201).json({
      success: true,
      message: 'User created successfully',
      // Return minimal sensitive information
      data: {
        id: 3, // In real app: result.rows[0].id
        name: escapeHtml(name),
        email: escapeHtml(email),
      },
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    next(error);
  }
});

// ========== HELPER FUNCTIONS ==========

function escapeHtml(text) {
  if (typeof text !== 'string') return text;
  const map = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#039;',
  };
  return text.replace(/[&<>"']/g, m => map[m]);
}

function sanitizeInput(input) {
  if (typeof input !== 'string') return input;
  // Remove potentially malicious content
  return input
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
    .replace(/on\w+="[^"]*"/g, '')
    .replace(/on\w+='[^']*'/g, '')
    .replace(/javascript:/gi, '')
    .trim();
}

// ========== ERROR HANDLING ==========

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: {
      message: 'Route not found',
      statusCode: 404,
      path: req.path,
      timestamp: new Date().toISOString(),
    },
  });
});

// Register error handler
app.use(errorHandler);

// ========== SERVER STARTUP ==========

const PORT = process.env.PORT || 3000;

// Validate environment before starting
const requiredEnvVars = ['ANTHROPIC_API_KEY', 'DATABASE_URL']; // Add required env vars
const missingVars = requiredEnvVars.filter(varName => !process.env[varName]);

if (missingVars.length > 0) {
  console.error('Missing required environment variables:', missingVars);
  process.exit(1);
}

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to log to a service like Sentry
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // In production, you might want to restart the process
  process.exit(1);
});

module.exports = app;

