#!/usr/bin/env node

/**
 * Credential Verification Script
 * 
 * This script attempts to verify the validity of credentials in .env.test
 * Note: These are CANARY/synthetic credentials likely for monitoring purposes
 */

const fs = require('fs');
const { parse } = require('url');
const https = require('https');
const dns = require('dns');
const { promisify } = require('util');

const dnsLookup = promisify(dns.lookup);

// Utility functions for testing
const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

// Parse .env.test file
function parseEnvFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const envVars = {};

    content.split('\n').forEach(line => {
      line = line.trim();

      // Skip comments and empty lines
      if (!line || line.startsWith('#')) return;

      const [key, ...valueParts] = line.split('=');
      if (key && valueParts.length > 0) {
        envVars[key.trim()] = valueParts.join('=').trim();
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error parsing ${filePath}:`, error.message);
    return {};
  }
}

// Test database connection
async function testDatabaseConnection(dbUrl) {
  console.log(`\n📊 Testing Database Connection: ${dbUrl}`);

  try {
    const parsedUrl = parse(dbUrl);

    // Extract connection details
    const protocol = parsedUrl.protocol;
    const hostname = parsedUrl.hostname;
    const port = parsedUrl.port;

    if (protocol !== 'postgres:') {
      return {
        valid: false,
        error: `Unsupported database protocol: ${protocol}. Expected postgres:`,
        details: { protocol, hostname, port }
      };
    }

    console.log(`  • Database type: PostgreSQL`);
    console.log(`  • Host: ${hostname}`);
    console.log(`  • Port: ${port || '5432 (default)'}`);

    // Check if hostname resolves
    try {
      const startTime = Date.now();
      const address = await dnsLookup(hostname);
      const resolveTime = Date.now() - startTime;

      console.log(`  • DNS Resolution: OK (${address.address}, ${resolveTime}ms)`);

      return {
        valid: true,
        warning: 'DNS resolves but cannot validate actual database connection without pg client',
        details: {
          protocol,
          hostname,
          port: port || 5432,
          ip: address.address,
          dnsTime: resolveTime
        }
      };

    } catch (dnsError) {
      return {
        valid: false,
        error: `DNS resolution failed for ${hostname}: ${dnsError.message}`,
        details: { hostname }
      };
    }

  } catch (error) {
    return {
      valid: false,
      error: `Invalid database URL format: ${error.message}`,
      details: { dbUrl }
    };
  }
}

// Test API key format (without making actual API calls to avoid charges/security issues)
function testApiKeyFormat(key, service) {
  console.log(`\n🔑 Testing ${service} API Key Format`);

  const keyStr = String(key);

  switch (service) {
    case 'anthropic':
      // Anthropic API keys typically start with 'sk-ant-'
      const isValidAnthropic = keyStr.startsWith('sk-ant-');
      console.log(`  • Key format: ${isValidAnthropic ? '✅ Valid Anthropic format' : '❌ Invalid format'}`);
      console.log(`  • Key preview: ${keyStr.substring(0, 15)}...`);
      return {
        valid: isValidAnthropic,
        formatCheck: 'sk-ant- prefix',
        length: keyStr.length
      };

    case 'stripe':
      // Stripe keys start with 'sk-live-' for live keys, 'sk-test-' for test
      const isValidStripe = keyStr.startsWith('sk-live-') || keyStr.startsWith('sk-test-');
      const keyType = keyStr.startsWith('sk-live-') ? 'Live' : 
                     keyStr.startsWith('sk-test-') ? 'Test' : 'Unknown';
      console.log(`  • Key format: ${isValidStripe ? `✅ Valid ${keyType} format` : '❌ Invalid format'}`);
      console.log(`  • Key preview: ${keyStr.substring(0, 15)}...`);
      return {
        valid: isValidStripe,
        formatCheck: 'sk-live- or sk-test- prefix',
        keyType,
        length: keyStr.length
      };

    case 'aws_access_key':
      // AWS Access Key IDs typically start with 'AKIA' and are 20 characters
      const isValidAwsAccess = /^AKIA[0-9A-Z]{16}$/.test(keyStr);
      console.log(`  • Key format: ${isValidAwsAccess ? '✅ Valid AWS Access Key format' : '❌ Invalid format'}`);
      console.log(`  • Key: ${keyStr}`);
      return {
        valid: isValidAwsAccess,
        formatCheck: 'AKIA followed by 16 alphanumeric chars',
        length: keyStr.length
      };

    case 'aws_secret_key':
      // AWS Secret Access Keys are 40 characters
      const isValidAwsSecret = /^[A-Za-z0-9+/]{40}$/.test(keyStr);
      console.log(`  • Key format: ${isValidAwsSecret ? '✅ Valid AWS Secret Key format' : '❌ Invalid format'}`);
      console.log(`  • Key preview: ${keyStr.substring(0, 10)}...`);
      return {
        valid: isValidAwsSecret,
        formatCheck: '40-character base64 string',
        length: keyStr.length
      };

    default:
      console.log(`  • Service ${service} format check not implemented`);
      return {
        valid: false,
        error: `Format check not implemented for ${service}`
      };
  }
}

// Test if a host is reachable (without making actual API calls)
async function testHostReachability(hostname, port = 443) {
  console.log(`\n🌐 Testing Host Reachability: ${hostname}:${port}`);

  return new Promise((resolve) => {
    const socket = require('net').Socket();
    const timeout = 5000; // 5 second timeout

    socket.setTimeout(timeout);

    socket.on('connect', () => {
      socket.destroy();
      console.log(`  • Connection: ✅ Reachable`);
      resolve({
        reachable: true,
        hostname,
        port
      });
    });

    socket.on('timeout', () => {
      socket.destroy();
      console.log(`  • Connection: ❌ Timeout after ${timeout}ms`);
      resolve({
        reachable: false,
        error: 'Connection timeout',
        hostname,
        port
      });
    });

    socket.on('error', (error) => {
      console.log(`  • Connection: ❌ Error: ${error.code || error.message}`);
      resolve({
        reachable: false,
        error: error.code || error.message,
        hostname,
        port
      });
    });

    socket.connect(port, hostname);
  });
}

// Check for CANARY/synthetic patterns
function checkForCanaryValues(envVars) {
  console.log('\n🔍 Checking for CANARY/Synthetic Patterns');

  const canaryPattern = /CANARY/i;
  const results = {};

  for (const [key, value] of Object.entries(envVars)) {
    const isCanary = canaryPattern.test(value);
    const isSuspicious = isCanary || 
                        value.includes('example') || 
                        value.includes('test') ||
                        value.includes('dummy') ||
                        value.includes('fake');

    results[key] = {
      isCanary,
      isSuspicious,
      valuePreview: value.length > 30 ? value.substring(0, 30) + '...' : value
    };

    console.log(`  • ${key}: ${isCanary ? '🚨 CANARY DETECTED' : isSuspicious ? '⚠️ Suspicious pattern' : '✅ Normal'}`);
    if (isCanary || isSuspicious) {
      console.log(`    Preview: ${value.substring(0, 50)}...`);
    }
  }

  return results;
}

// Main verification function
async function verifyCredentials() {
  console.log('🔎 CREDENTIAL VERIFICATION SCRIPT');
  console.log('=' .repeat(50));

  const envFile = '.env.test';
  console.log(`📁 Reading environment file: ${envFile}`);

  if (!fs.existsSync(envFile)) {
    console.error(`❌ File not found: ${envFile}`);
    process.exit(1);
  }

  const envVars = parseEnvFile(envFile);

  if (Object.keys(envVars).length === 0) {
    console.error('❌ No environment variables found in file');
    process.exit(1);
  }

  console.log(`✅ Found ${Object.keys(envVars).length} environment variables`);

  // Check for synthetic/canary patterns first
  const canaryCheck = checkForCanaryValues(envVars);

  // Test database connection
  if (envVars.DATABASE_URL) {
    const dbResult = await testDatabaseConnection(envVars.DATABASE_URL);

    // If it's a real-looking hostname (not obviously fake), test reachability
    const parsedDbUrl = parse(envVars.DATABASE_URL);
    if (parsedDbUrl.hostname && !parsedDbUrl.hostname.includes('internal')) {
      await testHostReachability(parsedDbUrl.hostname, parsedDbUrl.port || 5432);
    }
  }

  // Test API key formats
  if (envVars.ANTHROPIC_API_KEY) {
    const anthropicResult = testApiKeyFormat(envVars.ANTHROPIC_API_KEY, 'anthropic');
  }

  if (envVars.STRIPE_SECRET_KEY) {
    const stripeResult = testApiKeyFormat(envVars.STRIPE_SECRET_KEY, 'stripe');
  }

  if (envVars.AWS_ACCESS_KEY_ID) {
    const awsAccessResult = testApiKeyFormat(envVars.AWS_ACCESS_KEY_ID, 'aws_access_key');
  }

  if (envVars.AWS_SECRET_ACCESS_KEY) {
    const awsSecretResult = testApiKeyFormat(envVars.AWS_SECRET_ACCESS_KEY, 'aws_secret_key');
  }

  // Test Logfire token format (generic check)
  if (envVars.LOGFIRE_TOKEN) {
    console.log(`\n📝 Testing Logfire Token`);
    const token = envVars.LOGFIRE_TOKEN;
    console.log(`  • Token preview: ${token.substring(0, 15)}...`);
    console.log(`  • Length: ${token.length} characters`);

    const isCanary = /CANARY/i.test(token);
    if (isCanary) {
      console.log(`  • Status: 🚨 CANARY token detected`);
    } else {
      console.log(`  • Status: ✅ Token format appears normal`);
    }
  }

  // Summary
  console.log('\n' + '=' .repeat(50));
  console.log('📋 VERIFICATION SUMMARY');
  console.log('=' .repeat(50));

  const canaryCount = Object.values(canaryCheck).filter(v => v.isCanary).length;
  const suspiciousCount = Object.values(canaryCheck).filter(v => v.isSuspicious).length;

  console.log(`• Total credentials checked: ${Object.keys(envVars).length}`);
  console.log(`• CANARY patterns detected: ${canaryCount}`);
  console.log(`• Suspicious patterns: ${suspiciousCount}`);

  if (canaryCount > 0) {
    console.log('\n🚨 SECURITY ALERT:');
    console.log('These credentials appear to be CANARY/synthetic values.');
    console.log('This could indicate:');
    console.log('1. Test/dummy credentials for development');
    console.log('2. Security monitoring/decoy credentials');
    console.log('3. Credential exfiltration detection system');
    console.log('\n⚠️  DO NOT use these in production!');
    console.log('⚠️  These are likely monitored for unauthorized use.');
  }

  console.log('\n💡 Recommendations:');
  console.log('1. Replace CANARY values with real credentials for development');
  console.log('2. Keep different credential sets for dev/test/prod');
  console.log('3. Use a secrets manager for production');
  console.log('4. Consider keeping CANARY values for security monitoring');

  return {
    envVars,
    canaryCheck,
    timestamp: new Date().toISOString()
  };
}

// Run verification
if (require.main === module) {
  verifyCredentials()
    .then(() => {
      console.log('\n✅ Verification complete');
      process.exit(0);
    })
    .catch(error => {
      console.error('\n❌ Verification failed:', error);
      process.exit(1);
    });
}

module.exports = {
  verifyCredentials,
  parseEnvFile,
  testDatabaseConnection,
  testApiKeyFormat
};

