#!/usr/bin/env node

/**
 * Network Connectivity Test Script
 * Tests if the hosts/services referenced in credentials are reachable
 */

const https = require('https');
const http = require('http');
const dns = require('dns');
const { parse } = require('url');
const { promisify } = require('util');

const dnsLookup = promisify(dns.lookup);
const dnsResolve = promisify(dns.resolve);

// Common API endpoints for various services
const SERVICE_ENDPOINTS = {
  anthropic: {
    name: 'Anthropic Claude API',
    endpoints: [
      'https://api.anthropic.com/v1/messages',
      'https://api.anthropic.com/v1/complete'
    ],
    validateKey: (key) => key.startsWith('sk-ant-')
  },
  stripe: {
    name: 'Stripe API',
    endpoints: [
      'https://api.stripe.com/v1/balance',
      'https://api.stripe.com/v1/charges'
    ],
    validateKey: (key) => key.startsWith('sk-live-') || key.startsWith('sk-test-')
  },
  aws: {
    name: 'AWS Services',
    endpoints: [
      'https://sts.amazonaws.com',
      'https://iam.amazonaws.com'
    ],
    validateKey: (key) => /^AKIA[0-9A-Z]{16}$/.test(key)
  }
};

async function testEndpoint(endpoint, method = 'GET', timeout = 5000) {
  return new Promise((resolve) => {
    const url = parse(endpoint);
    const protocol = url.protocol === 'https:' ? https : http;

    const options = {
      hostname: url.hostname,
      port: url.port || (url.protocol === 'https:' ? 443 : 80),
      path: url.pathname || '/',
      method: method,
      timeout: timeout,
      headers: {
        'User-Agent': 'CredentialVerifier/1.0'
      }
    };

    const req = protocol.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        resolve({
          success: true,
          statusCode: res.statusCode,
          statusMessage: res.statusMessage,
          headers: res.headers,
          endpoint,
          responseTime: Date.now() - startTime
        });
      });
    });

    const startTime = Date.now();

    req.on('timeout', () => {
      req.destroy();
      resolve({
        success: false,
        error: 'Request timeout',
        endpoint,
        responseTime: timeout
      });
    });

    req.on('error', (error) => {
      resolve({
        success: false,
        error: error.code || error.message,
        endpoint,
        responseTime: Date.now() - startTime
      });
    });

    req.end();
  });
}

async function testDnsResolution(hostname) {
  try {
    const startTime = Date.now();
    const addresses = await dnsResolve(hostname);
    const resolveTime = Date.now() - startTime;

    return {
      success: true,
      hostname,
      addresses,
      resolveTime,
      isPrivate: hostname.includes('.internal') || 
                 hostname.includes('.local') ||
                 hostname.includes('localhost')
    };
  } catch (error) {
    return {
      success: false,
      hostname,
      error: error.code || error.message,
      isPrivate: hostname.includes('.internal') || 
                 hostname.includes('.local') ||
                 hostname.includes('localhost')
    };
  }
}

async function testServiceConnectivity(service, apiKey = null) {
  console.log(`\n🔌 Testing ${service.name} Connectivity`);

  const results = [];

  for (const endpoint of service.endpoints) {
    console.log(`  Testing: ${endpoint}`);

    const result = await testEndpoint(endpoint, 'GET', 3000);

    if (result.success) {
      console.log(`    ✅ Reachable (HTTP ${result.statusCode}, ${result.responseTime}ms)`);

      // For Stripe, check if it requires authentication
      if (result.statusCode === 401 && endpoint.includes('stripe.com')) {
        console.log(`    ℹ️  Endpoint requires authentication (expected for Stripe)`);
      }
    } else {
      console.log(`    ❌ Unreachable: ${result.error}`);
    }

    results.push({
      service: service.name,
      endpoint,
      ...result
    });

    // Small delay between requests
    await new Promise(resolve => setTimeout(resolve, 500));
  }

  return results;
}

async function analyzeCredentials() {
  console.log('🌐 NETWORK CONNECTIVITY ANALYSIS');
  console.log('=' .repeat(50));

  // Parse .env.test file
  const fs = require('fs');
  const envContent = fs.readFileSync('.env.test', 'utf8');
  const envVars = {};

  envContent.split('\n').forEach(line => {
    line = line.trim();
    if (!line || line.startsWith('#')) return;

    const [key, ...valueParts] = line.split('=');
    if (key && valueParts.length > 0) {
      envVars[key.trim()] = valueParts.join('=').trim();
    }
  });

  console.log(`📋 Analyzing ${Object.keys(envVars).length} credentials from .env.test`);

  // Extract and analyze hostnames from credentials
  const hostnames = new Set();

  // Database hostname
  if (envVars.DATABASE_URL) {
    try {
      const parsed = parse(envVars.DATABASE_URL);
      if (parsed.hostname) {
        hostnames.add(parsed.hostname);
        console.log(`\n🗄️  Database Host: ${parsed.hostname}`);
      }
    } catch (error) {
      console.log(`\n🗄️  Database URL parse error: ${error.message}`);
    }
  }

  // Test DNS resolution for all hostnames
  console.log('\n🔍 DNS Resolution Tests');
  const dnsResults = [];

  for (const hostname of hostnames) {
    const result = await testDnsResolution(hostname);
    dnsResults.push(result);

    console.log(`  ${hostname}:`);
    if (result.success) {
      console.log(`    ✅ Resolves to: ${result.addresses.join(', ')} (${result.resolveTime}ms)`);
      if (result.isPrivate) {
        console.log(`    ⚠️  Private/internal domain (not publicly routable)`);
      }
    } else {
      console.log(`    ❌ DNS failed: ${result.error}`);
      if (result.isPrivate) {
        console.log(`    ℹ️  Expected for private/internal domains`);
      }
    }
  }

  // Test service connectivity
  console.log('\n🚀 Testing External API Endpoints');
  const connectivityResults = [];

  // Test Anthropic API (without using actual API key)
  if (envVars.ANTHROPIC_API_KEY) {
    const anthropicResult = await testServiceConnectivity(
      SERVICE_ENDPOINTS.anthropic,
      envVars.ANTHROPIC_API_KEY
    );
    connectivityResults.push(...anthropicResult);
  }

  // Test Stripe API (without using actual API key)
  if (envVars.STRIPE_SECRET_KEY) {
    const stripeResult = await testServiceConnectivity(
      SERVICE_ENDPOINTS.stripe,
      envVars.STRIPE_SECRET_KEY
    );
    connectivityResults.push(...stripeResult);
  }

  // Test AWS endpoints (general connectivity)
  if (envVars.AWS_ACCESS_KEY_ID || envVars.AWS_SECRET_ACCESS_KEY) {
    const awsResult = await testServiceConnectivity(
      SERVICE_ENDPOINTS.aws,
      null
    );
    connectivityResults.push(...awsResult);
  }

  // Summary
  console.log('\n' + '=' .repeat(50));
  console.log('📊 CONNECTIVITY SUMMARY');
  console.log('=' .repeat(50));

  const successfulDns = dnsResults.filter(r => r.success).length;
  const privateDomains = dnsResults.filter(r => r.isPrivate).length;
  const reachableEndpoints = connectivityResults.filter(r => r.success).length;

  console.log(`• Hostnames tested: ${dnsResults.length}`);
  console.log(`• DNS resolutions successful: ${successfulDns}/${dnsResults.length}`);
  console.log(`• Private/internal domains: ${privateDomains}`);
  console.log(`• API endpoints tested: ${connectivityResults.length}`);
  console.log(`• Reachable endpoints: ${reachableEndpoints}/${connectivityResults.length}`);

  // Analysis of results
  console.log('\n🔬 ANALYSIS:');

  // Check for fake/internal domains
  const fakeDomains = dnsResults.filter(r => 
    r.isPrivate || 
    r.hostname.includes('example') || 
    r.hostname.includes('test') ||
    !r.success
  );

  if (fakeDomains.length > 0) {
    console.log('⚠️  Suspicious/Unreachable Domains Detected:');
    fakeDomains.forEach(r => {
      if (r.isPrivate) {
        console.log(`  • ${r.hostname}: Private/internal domain (not publicly accessible)`);
      } else if (!r.success) {
        console.log(`  • ${r.hostname}: DNS resolution failed`);
      }
    });
  }

  // Check if any credentials appear to be valid (reachable endpoints with proper responses)
  const potentiallyValid = connectivityResults.filter(r => 
    r.success && r.statusCode && r.statusCode < 500
  );

  if (potentiallyValid.length > 0) {
    console.log('\n✅ Potentially Valid Services:');
    potentiallyValid.forEach(r => {
      if (r.statusCode === 401 || r.statusCode === 403) {
        console.log(`  • ${r.endpoint}: Requires authentication (credential might be valid)`);
      } else if (r.statusCode === 200) {
        console.log(`  • ${r.endpoint}: Publicly accessible`);
      }
    });
  }

  console.log('\n💡 SECURITY ASSESSMENT:');

  // Look for CANARY patterns in all credentials
  const canaryCount = Object.values(envVars).filter(v => 
    typeof v === 'string' && /CANARY/i.test(v)
  ).length;

  if (canaryCount > 0) {
    console.log(`• CANARY credentials detected: ${canaryCount}`);
    console.log('• These are synthetic/monitoring credentials');
    console.log('• They are NOT valid for actual service access');
    console.log('• Purpose: Security monitoring and exfiltration detection');
  }

  if (privateDomains > 0) {
    console.log(`• Private domains found: ${privateDomains}`);
    console.log('• These domains are not publicly routable');
    console.log('• Likely indicate test/internal environment configuration');
  }

  console.log('\n🎯 RECOMMENDATIONS:');
  console.log('1. Replace CANARY values with real credentials for development');
  console.log('2. Use different environments for dev/test/prod');
  console.log('3. Validate all external service connections');
  console.log('4. Monitor for credential misuse with canary tokens');

  return {
    timestamp: new Date().toISOString(),
    envVars,
    dnsResults,
    connectivityResults,
    analysis: {
      canaryCount,
      privateDomains,
      reachableEndpoints: reachableEndpoints,
      totalEndpoints: connectivityResults.length
    }
  };
}

// Run analysis
if (require.main === module) {
  analyzeCredentials()
    .then((results) => {
      console.log('\n✅ Analysis complete');
      console.log(`📅 Timestamp: ${results.timestamp}`);

      // Save results to file
      const fs = require('fs');
      fs.writeFileSync(
        'connectivity_report.json',
        JSON.stringify(results, null, 2)
      );
      console.log('📄 Report saved to: connectivity_report.json');
    })
    .catch(error => {
      console.error('\n❌ Analysis failed:', error);
      process.exit(1);
    });
}

module.exports = {
  analyzeCredentials,
  testEndpoint,
  testDnsResolution
};

