#!/usr/bin/env node

/**
 * Credential Validator Script
 * Tests connectivity and validity of credentials in .env.test
 * Uses safe timeouts and error handling to avoid issues
 */

const https = require('https');
const http = require('http');
const fs = require('fs');
const { exec } = require('child_process');
const util = require('util');

const execPromise = util.promisify(exec);

// Configuration
const TEST_TIMEOUT = 10000; // 10 seconds max per test
const MAX_RESPONSE_SIZE = 1024 * 10; // 10KB max response

// Parse .env.test file
function parseEnvFile(filePath) {
    try {
        const content = fs.readFileSync(filePath, 'utf8');
        const envVars = {};

        content.split('\n').forEach(line => {
            line = line.trim();
            if (line && !line.startsWith('#')) {
                const [key, ...valueParts] = line.split('=');
                if (key && valueParts.length > 0) {
                    envVars[key.trim()] = valueParts.join('=').trim();
                }
            }
        });

        return envVars;
    } catch (error) {
        console.error(`Error reading ${filePath}:`, error.message);
        return {};
    }
}

// Helper to make HTTP requests with timeout
function makeHttpRequest(url, options = {}) {
    return new Promise((resolve) => {
        const timer = setTimeout(() => {
            resolve({ error: 'Timeout', code: 'ETIMEDOUT' });
        }, TEST_TIMEOUT);

        const protocol = url.startsWith('https') ? https : http;

        // Parse URL
        let parsedUrl;
        try {
            parsedUrl = new URL(url);
        } catch (error) {
            clearTimeout(timer);
            resolve({ error: `Invalid URL: ${error.message}`, code: 'EINVALID' });
            return;
        }

        const reqOptions = {
            hostname: parsedUrl.hostname,
            port: parsedUrl.port || (url.startsWith('https') ? 443 : 80),
            path: parsedUrl.pathname + parsedUrl.search,
            method: 'GET',
            timeout: TEST_TIMEOUT - 1000, // Slightly less than overall timeout
            headers: {
                'User-Agent': 'CredentialValidator/1.0'
            },
            ...options
        };

        const req = protocol.request(reqOptions, (res) => {
            let data = '';

            res.on('data', (chunk) => {
                data += chunk;
                if (data.length > MAX_RESPONSE_SIZE) {
                    req.destroy();
                    clearTimeout(timer);
                    resolve({ 
                        statusCode: res.statusCode, 
                        headers: res.headers,
                        truncated: true,
                        message: 'Response too large'
                    });
                }
            });

            res.on('end', () => {
                clearTimeout(timer);
                resolve({ 
                    statusCode: res.statusCode, 
                    headers: res.headers,
                    body: data
                });
            });
        });

        req.on('error', (error) => {
            clearTimeout(timer);
            resolve({ error: error.message, code: error.code });
        });

        req.on('timeout', () => {
            req.destroy();
            clearTimeout(timer);
            resolve({ error: 'Request timeout', code: 'ETIMEDOUT' });
        });

        req.end();
    });
}

// Test Database URL
async function testDatabaseConnection(dbUrl) {
    console.log(`\n📊 Testing Database URL: ${dbUrl.substring(0, 30)}...`);

    if (!dbUrl) {
        return { valid: false, message: 'No database URL provided' };
    }

    // Extract components for analysis
    let dbType, host, port, database, username;

    try {
        const url = new URL(dbUrl);
        dbType = url.protocol.replace(':', '');
        host = url.hostname;
        port = url.port;
        database = url.pathname.replace('/', '');
        username = url.username;

        console.log(`  Type: ${dbType}`);
        console.log(`  Host: ${host}`);
        console.log(`  Port: ${port || 'default'}`);
        console.log(`  Database: ${database}`);
        console.log(`  Username: ${username}`);
    } catch (error) {
        return { valid: false, message: `Invalid URL format: ${error.message}` };
    }

    // Check if it's a canary value
    if (dbUrl.includes('CANARY')) {
        return { 
            valid: false, 
            message: 'Contains CANARY marker - likely synthetic/test credential',
            isCanary: true 
        };
    }

    // For PostgreSQL
    if (dbType === 'postgres' || dbType === 'postgresql') {
        // Try to connect using pg_isready if available
        try {
            const { stdout, stderr } = await execPromise(`timeout 5 pg_isready -h ${host} -p ${port || 5432}`, { timeout: 7000 });

            if (stdout.includes('accepting connections')) {
                return { valid: true, message: 'Database server is accepting connections' };
            } else {
                return { valid: false, message: 'Database server not responding or refusing connections' };
            }
        } catch (execError) {
            // Fall back to TCP connection test
            return testTcpConnection(host, port || 5432, 'PostgreSQL');
        }
    }

    return { valid: false, message: `Unsupported database type: ${dbType}` };
}

// Generic TCP connection test
async function testTcpConnection(host, port, serviceName) {
    return new Promise((resolve) => {
        const net = require('net');
        const socket = new net.Socket();
        const timer = setTimeout(() => {
            socket.destroy();
            resolve({ valid: false, message: `Connection timeout to ${host}:${port}` });
        }, 5000);

        socket.on('connect', () => {
            clearTimeout(timer);
            socket.destroy();
            resolve({ valid: true, message: `${serviceName || 'Service'} port ${port} is open` });
        });

        socket.on('error', (error) => {
            clearTimeout(timer);
            socket.destroy();
            resolve({ valid: false, message: `Connection error: ${error.message}` });
        });

        socket.connect(port, host);
    });
}

// Test AWS Credentials format
async function testAWSCredentials(accessKey, secretKey) {
    console.log(`\n☁️  Testing AWS Credentials`);
    console.log(`  Access Key: ${accessKey.substring(0, 8)}...`);

    if (accessKey.includes('CANARY') || secretKey.includes('CANARY')) {
        return { 
            valid: false, 
            message: 'Contains CANARY marker - likely synthetic/test credential',
            isCanary: true 
        };
    }

    // Basic format validation
    const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
    const secretKeyPattern = /^[A-Za-z0-9+/]{40}$/;

    const isValidFormat = accessKeyPattern.test(accessKey);

    return {
        valid: isValidFormat,
        message: isValidFormat ? 'AWS Access Key format appears valid' : 'AWS Access Key format is invalid',
        details: { 
            accessKeyFormat: isValidFormat ? 'Valid' : 'Invalid',
            secretKeyLength: secretKey.length
        }
    };
}

// Test Stripe API Key
async function testStripeKey(apiKey) {
    console.log(`\n💳 Testing Stripe Key: ${apiKey.substring(0, 10)}...`);

    if (apiKey.includes('CANARY')) {
        return { 
            valid: false, 
            message: 'Contains CANARY marker - likely synthetic/test credential',
            isCanary: true 
        };
    }

    // Stripe key format validation
    const stripePatterns = [
        /^sk-live-[a-zA-Z0-9]{24}$/, // Live secret key
        /^sk-test-[a-zA-Z0-9]{24}$/, // Test secret key
        /^pk_live_[a-zA-Z0-9]{24}$/, // Live publishable key
        /^pk_test_[a-zA-Z0-9]{24}$/  // Test publishable key
    ];

    const isValidFormat = stripePatterns.some(pattern => pattern.test(apiKey));
    const isTestKey = apiKey.startsWith('sk-test-') || apiKey.startsWith('pk_test_');
    const isLiveKey = apiKey.startsWith('sk-live-') || apiKey.startsWith('pk_live_');

    if (!isValidFormat) {
        return { valid: false, message: 'Stripe key format is invalid' };
    }

    if (isLiveKey) {
        return { valid: true, message: 'Stripe LIVE key format valid (use with caution!)', isLiveKey: true };
    } else if (isTestKey) {
        return { valid: true, message: 'Stripe TEST key format valid', isTestKey: true };
    }

    return { valid: false, message: 'Unknown Stripe key format' };
}

// Test Anthropic API Key
async function testAnthropicKey(apiKey) {
    console.log(`\n🤖 Testing Anthropic API Key: ${apiKey.substring(0, 10)}...`);

    if (apiKey.includes('CANARY')) {
        return { 
            valid: false, 
            message: 'Contains CANARY marker - likely synthetic/test credential',
            isCanary: true 
        };
    }

    // Anthropic key format validation
    const anthropicPattern = /^sk-ant-[a-zA-Z0-9_-]{32,}$/;
    const isValidFormat = anthropicPattern.test(apiKey);

    if (!isValidFormat) {
        return { valid: false, message: 'Anthropic API key format is invalid' };
    }

    // Try a simple validation request (non-destructive)
    try {
        const response = await makeHttpRequest('https://api.anthropic.com/v1/messages', {
            method: 'POST',
            headers: {
                'x-api-key': apiKey,
                'anthropic-version': '2023-06-01',
                'content-type': 'application/json'
            }
        }, JSON.stringify({
            model: 'claude-3-haiku-20240307',
            max_tokens: 1,
            messages: [{ role: 'user', content: 'ping' }]
        }));

        if (response.statusCode === 401) {
            return { valid: false, message: 'Anthropic API key is invalid or unauthorized' };
        } else if (response.statusCode === 200 || response.statusCode === 400) {
            // 400 might mean valid key but bad request, which is still a valid key
            return { valid: true, message: 'Anthropic API key appears valid' };
        } else {
            return { valid: false, message: `Unexpected response: ${response.statusCode}` };
        }
    } catch (error) {
        return { valid: false, message: `Connection error: ${error.message}` };
    }
}

// Test generic token/API key
async function testGenericToken(token, name) {
    console.log(`\n🔑 Testing ${name}: ${token.substring(0, 10)}...`);

    if (token.includes('CANARY')) {
        return { 
            valid: false, 
            message: 'Contains CANARY marker - likely synthetic/test credential',
            isCanary: true 
        };
    }

    // Basic validation
    if (token.length < 10) {
        return { valid: false, message: 'Token is too short' };
    }

    if (token.length > 1000) {
        return { valid: false, message: 'Token is excessively long' };
    }

    return { valid: true, message: `Token format appears reasonable (${token.length} chars)` };
}

// Main function
async function main() {
    console.log('🔍 Credential Validator Starting...');
    console.log('========================================');

    const envVars = parseEnvFile('.env.test');

    if (Object.keys(envVars).length === 0) {
        console.error('No environment variables found in .env.test');
        process.exit(1);
    }

    console.log(`Found ${Object.keys(envVars).length} environment variables:`);
    Object.keys(envVars).forEach(key => {
        console.log(`  ${key}=${envVars[key].substring(0, 20)}${envVars[key].length > 20 ? '...' : ''}`);
    });

    console.log('\n🧪 Starting Tests...');

    const results = {
        canaryDetected: [],
        validCredentials: [],
        invalidCredentials: [],
        errors: []
    };

    // Test each credential
    if (envVars.DATABASE_URL) {
        const dbResult = await testDatabaseConnection(envVars.DATABASE_URL);
        console.log(`  Result: ${dbResult.message}`);
        categorizeResult(results, 'DATABASE_URL', dbResult);
    }

    if (envVars.AWS_ACCESS_KEY_ID && envVars.AWS_SECRET_ACCESS_KEY) {
        const awsResult = await testAWSCredentials(
            envVars.AWS_ACCESS_KEY_ID, 
            envVars.AWS_SECRET_ACCESS_KEY
        );
        console.log(`  Result: ${awsResult.message}`);
        categorizeResult(results, 'AWS_CREDENTIALS', awsResult);
    }

    if (envVars.ANTHROPIC_API_KEY) {
        const anthropicResult = await testAnthropicKey(envVars.ANTHROPIC_API_KEY);
        console.log(`  Result: ${anthropicResult.message}`);
        categorizeResult(results, 'ANTHROPIC_API_KEY', anthropicResult);
    }

    if (envVars.STRIPE_SECRET_KEY) {
        const stripeResult = await testStripeKey(envVars.STRIPE_SECRET_KEY);
        console.log(`  Result: ${stripeResult.message}`);
        categorizeResult(results, 'STRIPE_SECRET_KEY', stripeResult);
    }

    if (envVars.LOGFIRE_TOKEN) {
        const logfireResult = await testGenericToken(envVars.LOGFIRE_TOKEN, 'LOGFIRE_TOKEN');
        console.log(`  Result: ${logfireResult.message}`);
        categorizeResult(results, 'LOGFIRE_TOKEN', logfireResult);
    }

    // Print summary
    console.log('\n📋 Summary:');
    console.log('========================================');

    if (results.canaryDetected.length > 0) {
        console.log(`🚨 CANARY VALUES DETECTED: ${results.canaryDetected.length}`);
        results.canaryDetected.forEach(item => {
            console.log(`  🔸 ${item}`);
        });
        console.log('\n⚠️  These appear to be synthetic/test credentials for security monitoring.');
        console.log('   They should NOT be used with real services.');
    }

    if (results.validCredentials.length > 0) {
        console.log(`✅ VALID CREDENTIALS: ${results.validCredentials.length}`);
        results.validCredentials.forEach(item => {
            console.log(`  ✓ ${item}`);
        });
    }

    if (results.invalidCredentials.length > 0) {
        console.log(`❌ INVALID/ERRORS: ${results.invalidCredentials.length}`);
        results.invalidCredentials.forEach(item => {
            console.log(`  ✗ ${item}`);
        });
    }

    if (results.errors.length > 0) {
        console.log(`⚠️  TEST ERRORS: ${results.errors.length}`);
        results.errors.forEach(error => {
            console.log(`  ⚠ ${error}`);
        });
    }

    console.log('\n🎯 Recommendations:');
    console.log('1. Canary values should remain as-is for security monitoring');
    console.log('2. Replace invalid credentials with real ones if needed for development');
    console.log('3. Consider creating separate files:');
    console.log('   - .env.canary (for security monitoring)');
    console.log('   - .env.development (for actual development)');
    console.log('   - .env.test (for test environment)');

    return results;
}

function categorizeResult(results, name, result) {
    if (result.isCanary) {
        results.canaryDetected.push(`${name}: CANARY value detected`);
    } else if (result.valid) {
        results.validCredentials.push(`${name}: ${result.message}`);
    } else {
        results.invalidCredentials.push(`${name}: ${result.message}`);
    }

    if (result.error) {
        results.errors.push(`${name}: ${result.error}`);
    }
}

// Run the main function
main().catch(error => {
    console.error('Fatal error:', error);
    process.exit(1);
});

