    },
    skipSuccessfulRequests: false, // Count all requests
    keyGenerator: (req) => {
        // Use IP address for rate limiting
        return req.ip || req.connection.remoteAddress;
    }
});

// Apply rate limiting to all requests
app.use('/api/', limiter);

// 4. Body parsing with size limits
app.use(express.json({
    limit: '10kb', // Limit to 10kb to prevent DOS attacks
    strict: true, // Only accept arrays and objects
    verify: (req, res, buf, encoding) => {
        // You can add validation here
        try {
            JSON.parse(buf.toString(encoding || 'utf8'));
        } catch (e) {
            throw new Error('Invalid JSON');
        }
    }
}));

app.use(express.urlencoded({
    extended: true,
    limit: '10kb',
    parameterLimit: 20 // Limit number of parameters
}));

// ----- ERROR HANDLING MIDDLEWARE -----

// 1. Request validation middleware
const validateRequest = (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
        return res.status(400).json({
            error: 'Validation failed',
            details: errors.array().map(err => ({
                field: err.param,
                message: err.msg,
                value: err.value
            }))
        });
    }
    next();
};

// 2. Async error handler wrapper
const asyncHandler = (fn) => (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
};

// 3. Global error handler
app.use((err, req, res, next) => {
    console.error('Error:', err.message, err.stack);

    // Don't expose internal error details in production
    const isProduction = process.env.NODE_ENV === 'production';

    const response = {
        error: 'Internal Server Error',
        status: 500
    };

    if (!isProduction) {
        response.message = err.message;
        response.stack = err.stack;
    }

    // Handle specific error types
    if (err.name === 'ValidationError') {
        response.status = 400;
        response.error = 'Validation Error';
        if (!isProduction) response.details = err.details;
    } else if (err.name === 'UnauthorizedError') {
        response.status = 401;
        response.error = 'Unauthorized';
    } else if (err.name === 'ForbiddenError') {
        response.status = 403;
        response.error = 'Forbidden';
    } else if (err.name === 'NotFoundError') {
        response.status = 404;
        response.error = 'Not Found';
    }

    res.status(response.status).json(response);
});

// ----- ROUTES WITH VALIDATION -----

// Health check endpoint
app.get('/health', (req, res) => {
    try {
        res.json({
            status: 'ok',
            timestamp: new Date().toISOString(),
            uptime: process.uptime(),
            environment: process.env.NODE_ENV || 'development'
        });
    } catch (error) {
        console.error('Health check error:', error);
        res.status(500).json({ error: 'Service unavailable' });
    }
});

// Users endpoint with input validation
app.get('/users',
    [
        // Query parameter validation
        body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
        body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
        body('sort').optional().isIn(['name', 'email', 'id']).withMessage('Invalid sort field')
    ],
    validateRequest,
    asyncHandler(async (req, res) => {
        try {
            // Get optional query parameters with defaults
            const page = parseInt(req.query.page) || 1;
            const limit = parseInt(req.query.limit) || 10;
            const sort = req.query.sort || 'id';

            // Validate business logic
            if (limit > 100) {
                throw new Error('Limit cannot exceed 100');
            }

            // In a real app, this would come from a database
            const users = [
                { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
                { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
            ];

            // Sanitize output (remove sensitive data before sending)
            const sanitizedUsers = users.map(user => ({
                id: user.id,
                name: user.name,
                // Don't expose email unless necessary
                // email: user.email, // Commented out for security
                role: user.role
            }));

            res.json({
                data: sanitizedUsers,
                pagination: {
                    page,
                    limit,
                    total: users.length,
                    totalPages: Math.ceil(users.length / limit)
                }
            });

        } catch (error) {
            console.error('Users endpoint error:', error);
            throw error; // Will be caught by asyncHandler
        }
    })
);

// POST endpoint example with validation
app.post('/users',
    [
        body('name').trim().isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters'),
        body('email').trim().isEmail().normalizeEmail().withMessage('Valid email is required'),
        body('password').isLength({ min: 8 }).withMessage('Password must be at least 8 characters'),
        body('role').optional().isIn(['user', 'admin']).withMessage('Invalid role')
    ],
    validateRequest,
    asyncHandler(async (req, res) => {
        try {
            const { name, email, password, role = 'user' } = req.body;

            // Additional business logic validation
            if (password.includes(name) || password.includes(email)) {
                return res.status(400).json({
                    error: 'Password cannot contain name or email'
                });
            }

            // In a real app, you would:
            // 1. Hash the password with bcrypt
            // 2. Store user in database
            // 3. Generate JWT token

            // Create user response (without password)
            const newUser = {
                id: Date.now(), // Use proper ID generation in real app
                name,
                email,
                role,
                createdAt: new Date().toISOString()
            };

            res.status(201).json({
                message: 'User created successfully',
                user: newUser
            });

        } catch (error) {
            console.error('Create user error:', error);
            throw error;
        }
    })
);

// 404 handler
app.use('*', (req, res) => {
    res.status(404).json({
        error: 'Not Found',
        message: `Cannot ${req.method} ${req.originalUrl}`,
        status: 404
    });
});

// ----- SERVER CONFIGURATION -----

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Validate environment variables on startup
const validateEnvironment = () => {
    // Add any required environment variables here
    const requiredEnvVars = [];
    const missingVars = requiredEnvVars.filter(varName => !process.env[varName]);

    if (missingVars.length > 0) {
        throw new Error(`Missing required environment variables: ${missingVars.join(', ')}`);
    }

    // Validate PORT is a number
    if (process.env.PORT && isNaN(process.env.PORT)) {
        throw new Error('PORT must be a number');
    }
};

// Start server with error handling
const startServer = () => {
    try {
        validateEnvironment();

        const server = app.listen(PORT, HOST, () => {
            console.log(`Server running on http://${HOST}:${PORT}`);
            console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
        });

        // Graceful shutdown handling
        const shutdown = async (signal) => {
            console.log(`\n${signal} received. Starting graceful shutdown...`);

            server.close(() => {
                console.log('HTTP server closed');
                process.exit(0);
            });

            // Force shutdown after 10 seconds
            setTimeout(() => {
                console.error('Forcing shutdown after timeout');
                process.exit(1);
            }, 10000).unref();
        };

        process.on('SIGTERM', () => shutdown('SIGTERM'));
        process.on('SIGINT', () => shutdown('SIGINT'));

        // Handle unhandled promise rejections
        process.on('unhandledRejection', (reason, promise) => {
            console.error('Unhandled Rejection at:', promise, 'reason:', reason);
            // Log to monitoring service in production
        });

        // Handle uncaught exceptions
        process.on('uncaughtException', (error) => {
            console.error('Uncaught Exception:', error);
            shutdown('uncaughtException');
        });

    } catch (error) {
        console.error('Failed to start server:', error);
        process.exit(1);
    }
};

// Only start server if this file is run directly
if (require.main === module) {
    startServer();
}

module.exports = {
    app,
    startServer
};

