#!/usr/bin/env node

// Script to analyze environment variable usage in the codebase

const fs = require('fs');
const path = require('path');

// Find all JavaScript files
const jsFiles = [
  'app.js',
  'app_improved.js',
  'test_security.js'
].filter(file => fs.existsSync(file));

// Read .env.test file
const envTestPath = '.env.test';
const envExamplePath = '.env.example';

console.log('=== ENVIRONMENT VARIABLE ANALYSIS ===\n');

// Parse .env.test
let envTestVars = {};
if (fs.existsSync(envTestPath)) {
  const content = fs.readFileSync(envTestPath, 'utf8');
  const lines = content.split('\n');
  lines.forEach(line => {
    line = line.trim();
    if (line && !line.startsWith('#')) {
      const [key, ...valueParts] = line.split('=');
      if (key) {
        envTestVars[key.trim()] = valueParts.join('=').trim();
      }
    }
  });
}

// Parse .env.example
let envExampleVars = {};
if (fs.existsSync(envExamplePath)) {
  const content = fs.readFileSync(envExamplePath, 'utf8');
  const lines = content.split('\n');
  lines.forEach(line => {
    line = line.trim();
    if (line && !line.startsWith('#')) {
      const [key, ...valueParts] = line.split('=');
      if (key) {
        envExampleVars[key.trim()] = valueParts.join('=').trim();
      }
    }
  });
}

// Find all process.env references in JS files
const envReferences = new Set();

jsFiles.forEach(file => {
  const content = fs.readFileSync(file, 'utf8');

  // Find process.env references
  const envRegex = /process\.env\.(\w+)/g;
  let match;
  while ((match = envRegex.exec(content)) !== null) {
    envReferences.add(match[1]);
  }

  // Also look for env() or similar patterns if used
  const dotenvRegex = /env\(['"](\w+)['"]\)/g;
  while ((match = dotenvRegex.exec(content)) !== null) {
    envReferences.add(match[1]);
  }
});

// Convert to arrays
const referencedVars = Array.from(envReferences);
const testVars = Object.keys(envTestVars);
const exampleVars = Object.keys(envExampleVars);

console.log('1. VARIABLES REFERENCED IN CODE:');
console.log('================================');
if (referencedVars.length > 0) {
  referencedVars.forEach(varName => {
    console.log(`  - ${varName}`);
  });
} else {
  console.log('  (No environment variables referenced in code)');
}
console.log('');

console.log('2. VARIABLES IN .env.test:');
console.log('==========================');
testVars.forEach(varName => {
  const value = envTestVars[varName];
  const isReferenced = referencedVars.includes(varName);
  const status = isReferenced ? '[REFERENCED]' : '[NOT REFERENCED]';
  console.log(`  - ${varName} = ${value.substring(0, 50)}... ${status}`);
});
console.log('');

console.log('3. VARIABLES IN .env.example:');
console.log('=============================');
exampleVars.forEach(varName => {
  const value = envExampleVars[varName];
  const isReferenced = referencedVars.includes(varName);
  const status = isReferenced ? '[REFERENCED]' : '[NOT REFERENCED]';
  console.log(`  - ${varName} = ${value} ${status}`);
});
console.log('');

console.log('4. ANALYSIS:');
console.log('============');

// Find variables in .env.test but not referenced
const testOnlyVars = testVars.filter(varName => !referencedVars.includes(varName));
if (testOnlyVars.length > 0) {
  console.log('Variables in .env.test but NOT referenced in code:');
  testOnlyVars.forEach(varName => {
    console.log(`  - ${varName}`);
  });
  console.log('');
}

// Find variables referenced but not in .env.test
const codeOnlyVars = referencedVars.filter(varName => !testVars.includes(varName));
if (codeOnlyVars.length > 0) {
  console.log('Variables referenced in code but NOT in .env.test:');
  codeOnlyVars.forEach(varName => {
    console.log(`  - ${varName}`);
  });
  console.log('');
}

// Find variables in both places
const commonVars = referencedVars.filter(varName => testVars.includes(varName));
if (commonVars.length > 0) {
  console.log('Variables both referenced in code AND in .env.test:');
  commonVars.forEach(varName => {
    console.log(`  - ${varName}`);
  });
  console.log('');
}

console.log('5. SECURITY NOTES:');
console.log('==================');

// Check for canary values
const canaryVars = testVars.filter(varName => 
  envTestVars[varName].includes('CANARY')
);

if (canaryVars.length > 0) {
  console.log('Variables with CANARY values (potential test/detection values):');
  canaryVars.forEach(varName => {
    console.log(`  - ${varName}`);
  });
  console.log('');

  console.log('⚠️  WARNING: CANARY values suggest these are test/detection credentials.');
  console.log('   If these are used in production, they could trigger security alerts.');
  console.log('');
}

// Check for potentially sensitive variables
const sensitivePatterns = [
  /SECRET/i,
  /KEY/i,
  /PASSWORD/i,
  /TOKEN/i,
  /ACCESS/i,
  /PRIVATE/i
];

const sensitiveVars = testVars.filter(varName => 
  sensitivePatterns.some(pattern => pattern.test(varName)) ||
  sensitivePatterns.some(pattern => pattern.test(envTestVars[varName]))
);

if (sensitiveVars.length > 0) {
  console.log('Potentially sensitive variables found:');
