    const isReferenced = referencedVars.includes(varName);
    const status = isReferenced ? 'USED' : 'UNUSED';
    console.log(`  - ${varName} (${status})`);
  });
  console.log('');
}

console.log('6. RECOMMENDATIONS:');
console.log('===================');

if (testOnlyVars.length > 0) {
  console.log('1. Investigate unused variables in .env.test:');
  console.log('   These variables may be used by other parts of the system.');
  console.log('   Or they may be leftover configuration that should be removed.');
  console.log('');
}

if (codeOnlyVars.length > 0) {
  console.log('2. Add missing variables to .env.test:');
  codeOnlyVars.forEach(varName => {
    console.log(`   - Add ${varName}=value to .env.test`);
  });
  console.log('');
}

console.log('3. Before applying security fixes:');
console.log('   - Audit actual usage of .env.test variables');
console.log('   - Determine if unused variables should be removed');
console.log('   - Add validation for environment variables');
