        process.exit(1);
    }

    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    lines.forEach((line, index) => {
        line = line.trim();
        if (line && !line.startsWith('#')) {
            const equalsIndex = line.indexOf('=');
            if (equalsIndex !== -1) {
                const key = line.substring(0, equalsIndex).trim();
                const value = line.substring(equalsIndex + 1).trim();
                envVars[key] = value;
            }
        }
    });

    return envVars;
}

// Format validation functions
function validateDatabaseUrl(url) {
    console.log(`  Validating DATABASE_URL format...`);

    try {
        // Parse URL
        const parsed = new URL(url);

        // Check protocol
        if (!parsed.protocol.startsWith('postgres')) {
            return { valid: false, error: `Invalid protocol: ${parsed.protocol}` };
        }

        // Check for required components
        if (!parsed.hostname) {
            return { valid: false, error: 'Missing hostname' };
        }

        if (!parsed.port) {
            return { valid: false, error: 'Missing port' };
        }

        // Extract username/password from URL
        const auth = parsed.username ? `${parsed.username}:${parsed.password || ''}` : '';

        return {
            valid: true,
            details: {
                protocol: parsed.protocol.replace(':', ''),
                hostname: parsed.hostname,
                port: parsed.port,
                database: parsed.pathname.replace('/', ''),
                hasUsername: !!parsed.username,
                hasPassword: !!parsed.password,
                authLength: auth.length
            }
        };

    } catch (error) {
        return { valid: false, error: `Invalid URL format: ${error.message}` };
    }
}

function validateAwsCredentials(accessKey, secretKey) {
    console.log(`  Validating AWS credentials format...`);

    // AWS Access Key ID format: typically starts with AKIA and is 20 chars
    const accessKeyPattern = /^[A-Z0-9]{20}$/;
    const secretKeyPattern = /^[A-Za-z0-9+/]{40}$/;

    const results = {
        accessKey: {
            valid: accessKeyPattern.test(accessKey),
            length: accessKey.length,
            startsWithAKIA: accessKey.startsWith('AKIA')
        },
        secretKey: {
            valid: secretKeyPattern.test(secretKey),
            length: secretKey.length
        }
    };

    return {
        valid: results.accessKey.valid && results.secretKey.valid,
        details: results
    };
}

function validateApiKeyFormat(key, service) {
    console.log(`  Validating ${service} API key format...`);

    const patterns = {
        anthropic: /^sk-ant-[A-Za-z0-9_-]{32,}$/,
        stripe: /^(sk|pk)_(live|test)_[A-Za-z0-9_-]{24,}$/,
        generic: /^[A-Za-z0-9_-]{20,}$/
    };

    let pattern = patterns[service] || patterns.generic;
    const isValid = pattern.test(key);

    return {
        valid: isValid,
        details: {
            length: key.length,
            patternMatched: service,
            startsWith: key.substring(0, Math.min(20, key.length))
        }
    };
}

function validateTokenFormat(token, service) {
    console.log(`  Validating ${service} token format...`);

    const isValid = token.length >= 16; // Basic length check

    return {
        valid: isValid,
        details: {
            length: token.length,
            containsCanary: token.includes('CANARY')
        }
    };
}

// Safe connectivity test (without actually connecting to sensitive services)
function safeConnectivityTest(envVars) {
    console.log('\n=== SAFE CONNECTIVITY CHECKS ===');

    // Only test local services or safe endpoints
    const tests = [];

    // If we have a database URL with localhost, we could test
    if (envVars.DATABASE_URL) {
