                    port: parsed.port,
                    local: true
                });
            } else {
                console.log(`  ⚠️  Database is not local (${parsed.hostname}), skipping connectivity test`);
            }
        } catch (error) {
            console.log(`  ⚠️  Could not parse database URL for connectivity test`);
        }
    }

    return tests;
}

// Check if values appear to be test/detection values
function analyzeCanaryValues(envVars) {
    console.log('\n=== CANARY VALUE ANALYSIS ===');

    const canaryVars = [];
    Object.entries(envVars).forEach(([key, value]) => {
        if (value.includes('CANARY')) {
            canaryVars.push({
