#!/usr/bin/env node

/**
 * Advanced credential analysis script
 * Examines patterns to determine if credentials are likely stale or active
 */

const fs = require('fs');

// Read environment variables from .env.test
function readEnvVars() {
    const envVars = {};
    const content = fs.readFileSync('.env.test', 'utf8');
    const lines = content.split('\n');

    lines.forEach(line => {
        line = line.trim();
        if (line && !line.startsWith('#')) {
            const equalsIndex = line.indexOf('=');
            if (equalsIndex !== -1) {
                const key = line.substring(0, equalsIndex).trim();
                const value = line.substring(equalsIndex + 1).trim();
                envVars[key] = value;
            }
        }
    });

    return envVars;
}

// Analyze patterns to determine staleness
function analyzeStaleness(envVars) {
    console.log('\n🔍 STALENESS ANALYSIS');
    console.log('====================\n');

    const analysis = {};

    Object.entries(envVars).forEach(([key, value]) => {
        const item = { key, value, indicators: [] };

        // Indicator 1: Contains "CANARY"
        if (value.includes('CANARY')) {
            item.indicators.push({
                type: 'CANARY_VALUE',
                confidence: 'HIGH',
                message: 'Contains "CANARY" - likely test/detection value',
                stalenessLikelihood: 'HIGH'
            });
        }

        // Indicator 2: Contains "test" or "staging" in values
        const envKeywords = ['test', 'staging', 'sandbox', 'dev', 'development'];
        envKeywords.forEach(keyword => {
            if (value.toLowerCase().includes(keyword)) {
                item.indicators.push({
                    type: 'ENVIRONMENT_KEYWORD',
                    confidence: 'MEDIUM',
                    message: `Contains "${keyword}" - likely non-production environment`,
                    stalenessLikelihood: 'MEDIUM'
                });
            }
        });

        // Indicator 3: Pattern analysis
        if (key.includes('SECRET') || key.includes('KEY') || key.includes('TOKEN')) {
            // Check if value looks like a placeholder
            const placeholderPatterns = [
                /^YOUR_.*_HERE$/i,
                /^placeholder$/i,
                /^changeme$/i,
                /^replace_with_.*$/i,
                /^\[.*\]$/,
                /^<.*>$/
            ];

            placeholderPatterns.forEach(pattern => {
                if (pattern.test(value)) {
                    item.indicators.push({
                        type: 'PLACEHOLDER_PATTERN',
                        confidence: 'VERY_HIGH',
                        message: 'Matches placeholder pattern',
                        stalenessLikelihood: 'VERY_HIGH'
                    });
                }
            });
        }

        // Indicator 4: Unused by current code
        // (This would require checking if the variable is referenced in app.js)
        item.indicators.push({
            type: 'UNUSED_IN_CODE',
            confidence: 'HIGH',
            message: 'Not referenced in app.js or app_improved.js',
            stalenessLikelihood: 'MEDIUM'
        });

        // Indicator 5: Database URL analysis
        if (key === 'DATABASE_URL') {
            try {
                const url = new URL(value);
                if (url.hostname.includes('.internal')) {
                    item.indicators.push({
                        type: 'INTERNAL_HOSTNAME',
                        confidence: 'MEDIUM',
                        message: 'Uses internal hostname (.internal)',
                        stalenessLikelihood: 'MEDIUM'
                    });
                }

                if (url.username === 'admin') {
                    item.indicators.push({
                        type: 'DEFAULT_USERNAME',
                        confidence: 'LOW',
                        message: 'Uses default "admin" username',
                        stalenessLikelihood: 'LOW'
                    });
                }
            } catch (e) {
                // Invalid URL
            }
        }

        // Indicator 6: AWS key patterns
        if (key.includes('AWS')) {
            // Real AWS keys start with AKIA, AIPA, ASIA, etc.
            if (value.startsWith('AKIA') && value.includes('CANARY')) {
                item.indicators.push({
                    type: 'CANARY_AWS_KEY',
                    confidence: 'HIGH',
                    message: 'AWS key with CANARY text - definitely test',
                    stalenessLikelihood: 'VERY_HIGH'
                });
            }
        }

        analysis[key] = item;
    });

    return analysis;
}

// Generate recommendations
function generateRecommendations(analysis) {
    console.log('\n💡 RECOMMENDATIONS');
    console.log('=================\n');

    const recommendations = [];

    Object.values(analysis).forEach(item => {
        const hasHighStaleness = item.indicators.some(ind => 
            ind.stalenessLikelihood === 'VERY_HIGH' || ind.stalenessLikelihood === 'HIGH'
        );

        const hasCanary = item.indicators.some(ind => ind.type === 'CANARY_VALUE');

        if (hasCanary) {
            recommendations.push({
                variable: item.key,
                action: 'INVESTIGATE',
                priority: 'HIGH',
                reason: 'Contains CANARY value - could be security test credential',
                steps: [
                    '1. Check with security team about purpose',
                    '2. Determine if this is a honeypot/test credential',
                    '3. Verify if real service integration is needed',
                    '4. Document purpose before modifying'
                ]
            });
        } else if (hasHighStaleness) {
            recommendations.push({
                variable: item.key,
                action: 'REVIEW',
                priority: 'MEDIUM',
                reason: 'Multiple indicators suggest stale credential',
                steps: [
                    '1. Check if service is still used',
                    '2. Test connectivity with safe methods',
                    '3. Update or remove if no longer needed'
                ]
            });
        } else {
            recommendations.push({
                variable: item.key,
                action: 'VALIDATE',
                priority: 'LOW',
                reason: 'No clear staleness indicators found',
                steps: [
                    '1. Verify format is correct',
                    '2. Test in non-production environment',
                    '3. Document validation results'
                ]
            });
        }
    });

    // Add general recommendations
    recommendations.push({
        variable: 'ALL',
        action: 'SECURITY_REVIEW',
        priority: 'CRITICAL',
        reason: 'Credentials found in .env.test but not used in code',
        steps: [
            '1. Audit why these credentials exist',
            '2. Ensure .env.test is NOT in production',
            '3. Implement credential rotation if real',
            '4. Consider using secrets manager instead'
        ]
    });

    return recommendations;
}

// Main function
async function main() {
    console.log('🔐 Credential Staleness Analysis');
    console.log('================================\n');

    // Read environment variables
    const envVars = readEnvVars();
    console.log(`Analyzing ${Object.keys(envVars).length} credentials from .env.test\n`);

    // Perform staleness analysis
    const analysis = analyzeStaleness(envVars);

    // Display detailed analysis
    Object.values(analysis).forEach(item => {
