#!/usr/bin/env node

/**
 * Safe credential verification script
 * Checks if credentials follow expected patterns WITHOUT making actual connections
 */

const fs = require('fs');
const dns = require('dns');
const { promisify } = require('util');

const resolve4 = promisify(dns.resolve4);
const resolveCname = promisify(dns.resolveCname);

// Patterns for different credential types
const PATTERNS = {
    // AWS Access Key IDs start with AKIA, ASIA, or AIPA and are 20 chars
    AWS_ACCESS_KEY: /^(AKIA|ASIA|AIPA)[A-Z0-9]{16,17}$/,

    // AWS Secret Keys are base64-like, 40 chars
    AWS_SECRET_KEY: /^[A-Za-z0-9+/]{40}$/,

    // Stripe keys start with sk-live-, sk-test-, pk_live_, or pk_test_
    STRIPE_KEY: /^(sk|pk)_(live|test)_[a-zA-Z0-9]{24,}$/,

    // Database URL patterns
    DATABASE_URL: {
        POSTGRES: /^postgres(ql)?:\/\/.+/,
        MYSQL: /^mysql:\/\/.+/,
        MONGODB: /^mongodb(\+srv)?:\/\/.+/
    },

    // Common API key patterns (varies by service)
    API_KEY: /^[a-zA-Z0-9_-]{20,}$/,

    // JWT tokens (typical pattern)
    JWT_TOKEN: /^[A-Za-z0-9-_]+\.[A-Za-z0-9-_]+\.[A-Za-z0-9-_]+$/
};

// Test if a hostname resolves (safe DNS check)
async function testHostnameResolution(hostname) {
    try {
        console.log(`  📡 Checking DNS for: ${hostname}`);
        const addresses = await resolve4(hostname);
        return {
            resolves: true,
            addresses: addresses.slice(0, 3), // Only show first 3
            message: `Resolves to ${addresses.length} IP(s)`
        };
    } catch (error) {
        // Check for CNAME
        try {
            const cnames = await resolveCname(hostname);
            return {
                resolves: true,
                addresses: cnames,
                message: `Resolves to CNAME: ${cnames[0]}`
            };
        } catch (cnameError) {
            return {
                resolves: false,
                error: error.code === 'ENOTFOUND' ? 'Host not found' : error.message,
                message: 'Does not resolve'
            };
        }
    }
}

// Safe validation without connections
function validateCredential(key, value) {
    console.log(`\n🔍 ${key}`);
    console.log(`   Value: ${value.substring(0, 30)}${value.length > 30 ? '...' : ''}`);

    const results = {
        key,
        valuePreview: value.substring(0, 20) + '...',
        length: value.length,
        containsCanary: value.includes('CANARY'),
        validation: {}
    };

    // Check for CANARY pattern
    if (results.containsCanary) {
        console.log(`   ⚠️  Contains "CANARY" - likely test credential`);
        results.validation.canaryDetected = true;
        results.validation.likelyTest = true;
    }

    // Check specific patterns based on key name
    if (key.includes('DATABASE_URL')) {
        results.type = 'database_url';

        // Parse URL safely
        try {
            const url = new URL(value);
            results.validation.urlValid = true;
            results.validation.protocol = url.protocol;
            results.validation.hostname = url.hostname;
            results.validation.port = url.port || 'default';
            results.validation.hasCredentials = !!(url.username || url.password);

            console.log(`   ✅ Valid URL format`);
            console.log(`   📊 Protocol: ${url.protocol}`);
            console.log(`   🌐 Host: ${url.hostname}`);

            // Check protocol pattern
            for (const [dbType, pattern] of Object.entries(PATTERNS.DATABASE_URL)) {
                if (pattern.test(value)) {
                    results.validation.databaseType = dbType;
                    console.log(`   💾 Type: ${dbType}`);
                    break;
                }
            }

        } catch (error) {
            results.validation.urlValid = false;
            results.validation.error = error.message;
            console.log(`   ❌ Invalid URL: ${error.message}`);
        }
    }
    else if (key.includes('AWS_ACCESS_KEY')) {
        results.type = 'aws_access_key';
        const isValid = PATTERNS.AWS_ACCESS_KEY.test(value);
        results.validation.patternValid = isValid;
        results.validation.startsWithAKIA = value.startsWith('AKIA');

        console.log(`   ${isValid ? '✅' : '❌'} Pattern: ${isValid ? 'Valid AWS format' : 'Invalid AWS format'}`);
        console.log(`   🔑 Starts with AKIA: ${value.startsWith('AKIA')}`);
    }
    else if (key.includes('AWS_SECRET')) {
        results.type = 'aws_secret_key';
        const isValid = PATTERNS.AWS_SECRET_KEY.test(value);
        results.validation.patternValid = isValid;

        console.log(`   ${isValid ? '✅' : '❌'} Pattern: ${isValid ? 'Valid AWS secret format' : 'Invalid format'}`);
    }
    else if (key.includes('STRIPE')) {
        results.type = 'stripe_key';
        const isValid = PATTERNS.STRIPE_KEY.test(value);
        results.validation.patternValid = isValid;
        results.validation.environment = value.includes('_live_') ? 'live' : 
                                       value.includes('_test_') ? 'test' : 'unknown';

        console.log(`   ${isValid ? '✅' : '❌'} Pattern: ${isValid ? 'Valid Stripe format' : 'Invalid Stripe format'}`);
        console.log(`   🏦 Environment: ${results.validation.environment}`);
    }
    else if (key.includes('API_KEY') || key.includes('TOKEN')) {
        results.type = 'api_key';
        const isValid = PATTERNS.API_KEY.test(value);
        results.validation.patternValid = isValid;

        console.log(`   ${isValid ? '✅' : '❌'} Pattern: ${isValid ? 'Valid API key format' : 'Invalid format'}`);
    }
    else {
        results.type = 'unknown';
        console.log(`   ℹ️  Unknown credential type`);
    }

    // Check length
    console.log(`   📏 Length: ${value.length} characters`);

    // Check for common placeholder patterns
    const placeholderPatterns = [
        { pattern: /^YOUR_.*_HERE$/i, name: 'YOUR_*_HERE placeholder' },
        { pattern: /^placeholder$/i, name: '"placeholder" text' },
        { pattern: /^changeme$/i, name: '"changeme" text' },
        { pattern: /^\[.*\]$/, name: 'bracketed placeholder' },
        { pattern: /^<.*>$/, name: 'angled placeholder' },
        { pattern: /^test.*$/i, name: 'test value' },
        { pattern: /^example.*$/i, name: 'example value' }
    ];

    for (const { pattern, name } of placeholderPatterns) {
        if (pattern.test(value)) {
            console.log(`   ⚠️  Looks like ${name}`);
            results.validation.placeholderDetected = true;
            break;
        }
    }

    return results;
}

// Main function
async function main() {
    console.log('🔐 SAFE Credential Verification');
    console.log('================================\n');
    console.log('NOTE: This script performs SAFE checks only.');
    console.log('      It will NOT connect to actual services.\n');

    // Read .env.test
    const envVars = {};
    const content = fs.readFileSync('.env.test', 'utf8');
    const lines = content.split('\n');

    lines.forEach(line => {
        line = line.trim();
        if (line && !line.startsWith('#')) {
            const equalsIndex = line.indexOf('=');
            if (equalsIndex !== -1) {
                const key = line.substring(0, equalsIndex).trim();
                const value = line.substring(equalsIndex + 1).trim();
                envVars[key] = value;
            }
        }
    });

    console.log(`Found ${Object.keys(envVars).length} credentials to verify\n`);

    // Validate each credential
    const validationResults = [];

    for (const [key, value] of Object.entries(envVars)) {
        const result = validateCredential(key, value);
        validationResults.push(result);
    }

    // Summary
    console.log('\n📊 VERIFICATION SUMMARY');
    console.log('======================\n');

    const total = validationResults.length;
    const withCanary = validationResults.filter(r => r.containsCanary).length;
    const likelyTest = validationResults.filter(r => 
        r.validation.likelyTest || 
        r.validation.placeholderDetected ||
        r.containsCanary
    ).length;

    console.log(`Total credentials checked: ${total}`);
    console.log(`Contain "CANARY": ${withCanary}`);
    console.log(`Likely test credentials: ${likelyTest}`);
    console.log(`Likely real credentials: ${total - likelyTest}`);

    // DNS resolution check for hostnames found
    console.log('\n🌐 DNS RESOLUTION CHECKS');
    console.log('=======================\n');

    const hostnames = new Set();
    validationResults.forEach(result => {
        if (result.validation.hostname && !result.validation.hostname.includes('localhost')) {
            hostnames.add(result.validation.hostname);
        }
    });

    if (hostnames.size > 0) {
        console.log(`Found ${hostnames.size} unique hostnames to check:\n`);

        for (const hostname of hostnames) {
            const resolution = await testHostnameResolution(hostname);
            console.log(`   ${hostname}: ${resolution.resolves ? '✅' : '❌'} ${resolution.message}`);
            if (resolution.addresses) {
                console.log(`      IPs: ${resolution.addresses.join(', ')}`);
            }
        }
    } else {
        console.log('No external hostnames found to check.');
    }

    // Final assessment
    console.log('\n🔒 FINAL ASSESSMENT');
    console.log('==================\n');

    if (withCanary === total) {
        console.log('🚨 ALL credentials contain CANARY values!');
        console.log('');
        console.log('IMPLICATIONS:');
        console.log('• These are almost certainly test/detection credentials');
        console.log('• They may be security honeypots or monitoring tools');
        console.log('• Attempting to use them could trigger security alerts');
        console.log('• They are likely NOT connected to real services');
        console.log('');
        console.log('RECOMMENDATIONS:');
        console.log('1. DO NOT attempt to validate by connecting to services');
        console.log('2. Contact your security team for guidance');
        console.log('3. Document these as test credentials');
        console.log('4. Ask if real credentials are needed for development');
    } else if (withCanary > 0) {
        console.log('⚠️  Mixed credentials found');
        console.log('');
        console.log('IMPLICATIONS:');
        console.log('• Some credentials may be real, some test');
        console.log('• Need to verify which are in active use');
        console.log('• Use extreme caution when testing');
        console.log('');
        console.log('RECOMMENDATIONS:');
        console.log('1. Separate CANARY and non-CANARY credentials');
        console.log('2. Test non-CANARY credentials in sandbox first');
        console.log('3. Check with team about credential status');
    } else {
        console.log('✅ No CANARY values detected');
        console.log('');
        console.log('IMPLICATIONS:');
        console.log('• Credentials may be real (but still verify)');
        console.log('• Should be treated as sensitive until proven otherwise');
        console.log('');
        console.log('RECOMMENDATIONS:');
        console.log('1. Test credentials in non-production environment');
        console.log('2. Verify format matches service requirements');
        console.log('3. Rotate credentials if they have been exposed');
    }

    // List credentials by type
    console.log('\n📋 CREDENTIALS BY TYPE');
    console.log('=====================\n');

    const byType = {};
    validationResults.forEach(result => {
        const type = result.type || 'unknown';
        byType[type] = byType[type] || [];
        byType[type].push(result.key);
    });

    Object.entries(byType).forEach(([type, keys]) => {
        console.log(`${type}:`);
        keys.forEach(key => console.log(`  • ${key}`));
        console.log('');
    });
}

// Run with safety disclaimer
console.log('='.repeat(60));
console.log('🚨 SAFETY DISCLAIMER 🚨');
console.log('='.repeat(60));
console.log('This script performs SAFE verification only.');
console.log('It will NOT connect to external services.');
console.log('It will NOT validate credentials with APIs.');
console.log('It will NOT trigger security alerts.');
console.log('='.repeat(60));
console.log('');

main().catch(error => {
    console.error('Verification error:', error);
    process.exit(1);
});

