// Improved application with security best practices
// Enhanced error handling and input validation

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const morgan = require('morgan');
require('dotenv').config();

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// 1. Security headers with Helmet
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            styleSrc: ["'self'", "'unsafe-inline'"],
            scriptSrc: ["'self'"],
            imgSrc: ["'self'", "data:", "https:"],
            connectSrc: ["'self'"],
            fontSrc: ["'self'"],
            objectSrc: ["'none'"],
            mediaSrc: ["'self'"],
            frameSrc: ["'none'"],
        },
    },
    hsts: {
        maxAge: 31536000,
        includeSubDomains: true,
        preload: true
    },
    referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
}));

// 2. CORS configuration - restrict to trusted origins
const allowedOrigins = process.env.ALLOWED_ORIGINS 
    ? process.env.ALLOWED_ORIGINS.split(',') 
    : ['http://localhost:3000'];

app.use(cors({
    origin: function (origin, callback) {
        // Allow requests with no origin (like mobile apps or curl requests)
        if (!origin) return callback(null, true);

        if (allowedOrigins.indexOf(origin) === -1) {
            const msg = `The CORS policy for this site does not allow access from the specified origin: ${origin}`;
            return callback(new Error(msg), false);
        }
        return callback(null, true);
    },
    credentials: true,
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With']
}));

// 3. Rate limiting to prevent brute force attacks
const apiLimiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // Limit each IP to 100 requests per windowMs
    message: {
        error: 'Too many requests from this IP, please try again after 15 minutes'
    },
    standardHeaders: true,
    legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(apiLimiter);

// 4. Request parsing with limits
app.use(express.json({
    limit: '10kb', // Prevent large payloads
    verify: (req, res, buf) => {
        // Optional: Add custom verification logic here
        req.rawBody = buf.toString();
    }
}));

app.use(express.urlencoded({
    extended: true,
    limit: '10kb'
}));

// 5. Request logging
app.use(morgan('combined', {
    skip: (req, res) => process.env.NODE_ENV === 'test',
    stream: process.stdout
}));

// ========== VALIDATION MIDDLEWARE ==========

// Generic validation error handler
const validateRequest = (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
        return res.status(400).json({
            error: 'Validation failed',
            details: errors.array().map(err => ({
                field: err.param,
                message: err.msg,
                value: err.value
            }))
        });
    }
    next();
};

// Sanitization middleware
const sanitizeInput = (req, res, next) => {
    // Basic input sanitization
    if (req.body) {
        for (const key in req.body) {
            if (typeof req.body[key] === 'string') {
                req.body[key] = req.body[key].trim();
            }
        }
    }
    next();
};

// ========== ERROR HANDLING MIDDLEWARE ==========

// Async error handler wrapper
const asyncHandler = (fn) => (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
};

// Custom error classes
class ValidationError extends Error {
    constructor(message, details = []) {
        super(message);
        this.name = 'ValidationError';
        this.statusCode = 400;
        this.details = details;
    }
}

class NotFoundError extends Error {
    constructor(message = 'Resource not found') {
        super(message);
        this.name = 'NotFoundError';
        this.statusCode = 404;
    }
}

class UnauthorizedError extends Error {
    constructor(message = 'Unauthorized access') {
        super(message);
        this.name = 'UnauthorizedError';
        this.statusCode = 401;
    }
}

// Global error handler
app.use((err, req, res, next) => {
    console.error('Error:', {
        message: err.message,
        stack: err.stack,
        timestamp: new Date().toISOString(),
        path: req.path,
        method: req.method,
        ip: req.ip
    });

    // Set default status code
    const statusCode = err.statusCode || 500;

    // Prepare error response
    const errorResponse = {
        error: err.name || 'InternalServerError',
        message: err.message || 'An unexpected error occurred',
        timestamp: new Date().toISOString(),
        path: req.path
    };

    // Add details if available
    if (err.details) {
        errorResponse.details = err.details;
    }

    // For production, don't expose stack trace
    if (process.env.NODE_ENV !== 'production' && err.stack) {
        errorResponse.stack = err.stack;
    }

    res.status(statusCode).json(errorResponse);
});

// ========== ENVIRONMENT VALIDATION ==========

// Validate required environment variables
const requiredEnvVars = ['NODE_ENV', 'PORT'];
const missingEnvVars = requiredEnvVars.filter(varName => !process.env[varName]);

if (missingEnvVars.length > 0) {
    console.error('Missing required environment variables:', missingEnvVars);
    process.exit(1);
}

// ========== APPLICATION ROUTES ==========

// Health endpoint with validation
app.get('/health', [
    // Add any query parameter validation if needed
], asyncHandler(async (req, res) => {
    // Simulate health checks
    const healthChecks = {
        uptime: process.uptime(),
        timestamp: new Date().toISOString(),
        database: { status: 'connected' }, // Add actual DB check
        memory: process.memoryUsage(),
        responseTime: process.hrtime(),
    };

    res.json({
        status: 'healthy',
        ...healthChecks
    });
}));

// Users endpoint with query validation
app.get('/users', [
    // Validate query parameters
    body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    body('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer'),
    sanitizeInput,
    validateRequest
], asyncHandler(async (req, res) => {
    // Extract and sanitize query parameters
    const limit = req.query.limit 
        ? parseInt(req.query.limit, 10) 
        : 10;
    const offset = req.query.offset 
        ? parseInt(req.query.offset, 10) 
        : 0;

    // Validate parsed values
    if (isNaN(limit) || limit < 1 || limit > 100) {
        throw new ValidationError('Invalid limit parameter', [
            { field: 'limit', message: 'Must be between 1 and 100' }
        ]);
    }

    if (isNaN(offset) || offset < 0) {
        throw new ValidationError('Invalid offset parameter', [
            { field: 'offset', message: 'Must be a positive integer' }
        ]);
    }

    // In a real application, you would query the database here
    const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter based on limit and offset
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
        success: true,
        data: paginatedUsers,
        pagination: {
            total: users.length,
            limit,
            offset,
            hasMore: offset + limit < users.length
        }
    });
}));

// 404 handler for undefined routes
app.use('*', (req, res) => {
    throw new NotFoundError(`Cannot ${req.method} ${req.originalUrl}`);
});

// ========== SERVER SETUP ==========

const PORT = process.env.PORT || 3000;

// Graceful shutdown handling
const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV}`);
    console.log(`Allowed origins: ${allowedOrigins.join(', ')}`);
});

// Graceful shutdown handlers
const gracefulShutdown = (signal) => {
    console.log(`\nReceived ${signal}. Starting graceful shutdown...`);

    server.close(() => {
        console.log('HTTP server closed');

        // Close database connections here if you have them
        // database.close().then(() => {
        //     console.log('Database connections closed');
        //     process.exit(0);
        // });

        process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
        console.error('Could not close connections in time, forcefully shutting down');
        process.exit(1);
    }, 10000);
};

// Handle termination signals
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
    console.error('Uncaught Exception:', error);
    gracefulShutdown('uncaughtException');
});

process.on('unhandledRejection', (reason, promise) => {
    console.error('Unhandled Rejection at:', promise, 'reason:', reason);
    gracefulShutdown('unhandledRejection');
});

module.exports = app;

// Security tests for the improved application
const request = require('supertest');
const app = require('./app_improved.js');

describe('Security Features Validation', () => {
  describe('HTTP Security Headers', () => {
    test('should include security headers', async () => {
      const response = await request(app).get('/health');

      // Essential security headers
      expect(response.headers['x-content-type-options']).toBe('nosniff');
      expect(response.headers['x-frame-options']).toBe('DENY');
      expect(response.headers['x-xss-protection']).toBe('0');
      expect(response.headers['content-security-policy']).toBeDefined();
      expect(response.headers['strict-transport-security']).toBeDefined();
      expect(response.headers['referrer-policy']).toBeDefined();
    });
  });

  describe('Rate Limiting', () => {
    test('should enforce rate limits', async () => {
      // Make multiple requests to trigger rate limiting
      const requests = Array(105).fill(null).map(() => 
        request(app).get('/health')
      );

      const responses = await Promise.all(requests);

      // Check if rate limiting is working
      const rateLimitedResponses = responses.filter(res => res.status === 429);
      expect(rateLimitedResponses.length).toBeGreaterThan(0);
    });
  });

  describe('Input Validation', () => {
    test('should reject invalid limit parameter', async () => {
      const response = await request(app)
        .get('/users')
        .query({ limit: 'invalid' });

      expect(response.status).toBe(400);
      expect(response.body.error).toBe('ValidationError');
    });

    test('should reject negative limit parameter', async () => {
      const response = await request(app)
        .get('/users')
        .query({ limit: -1 });

      expect(response.status).toBe(400);
      expect(response.body.error).toBe('ValidationError');
    });

    test('should reject large limit parameter', async () => {
      const response = await request(app)
        .get('/users')
        .query({ limit: 1000 });

      expect(response.status).toBe(400);
      expect(response.body.error).toBe('ValidationError');
    });
  });

  describe('Error Handling', () => {
    test('should return structured error for invalid routes', async () => {
      const response = await request(app).get('/nonexistent');

      expect(response.status).toBe(404);
      expect(response.body.error).toBe('NotFoundError');
      expect(response.body.message).toBeDefined();
      expect(response.body.timestamp).toBeDefined();
    });

