#!/usr/bin/env node

/**
 * Credential Validation Test Script
 * 
 * CAUTION: This script tests credentials that appear to be canary tokens.
 * Testing these may trigger security alerts if monitored.
 * Use with caution and only in isolated testing environments.
 */

const fs = require('fs');
const path = require('path');
const { exec } = require('child_process');
const https = require('https');
const { parse } = require('pg-connection-string');

// Parse .env.test file
const envTestPath = path.join(__dirname, '.env.test');
const envContent = fs.readFileSync(envTestPath, 'utf8');

// Extract environment variables
const envVars = {};
envContent.split('\n').forEach(line => {
  if (line.trim() && !line.startsWith('#')) {
    const [key, ...valueParts] = line.split('=');
    if (key && valueParts.length > 0) {
      envVars[key.trim()] = valueParts.join('=').trim();
    }
  }
});

console.log('🔍 Testing credentials from .env.test');
console.log('=====================================\n');

// Track results
const results = {
  tested: 0,
  valid: 0,
  invalid: 0,
  warnings: []
};

// Helper function to check if value looks like a canary token
function isCanaryToken(value) {
  return value && (
    value.includes('CANARY') || 
    /sk-(live|test)_/.test(value) ||
    /AKIA[A-Z0-9]{16}/.test(value) ||
    /sk-ant-[a-zA-Z0-9]+/.test(value)
  );
}

// Test 1: Database URL
async function testDatabaseURL() {
  const dbUrl = envVars.DATABASE_URL;
  results.tested++;

  console.log('1. Database URL Test:');
  console.log(`   URL: ${dbUrl ? dbUrl.replace(/:[^:@]+@/, ':****@') : 'Not found'}`);

  if (!dbUrl) {
    console.log('   ❌ No DATABASE_URL found');
    results.invalid++;
    return;
  }

  // Check if it looks like a canary
  if (isCanaryToken(dbUrl)) {
    console.log('   ⚠️  Appears to be a CANARY token (synthetic credential)');
    results.warnings.push('DATABASE_URL appears to be a canary token');
  }

  try {
    // Parse the connection string to validate format
    const config = parse(dbUrl);
    console.log('   ✅ Connection string format is valid');
    console.log(`   📊 Database: ${config.database}, Host: ${config.host}, Port: ${config.port}`);

    // Try to make a simple connection (with timeout to avoid hanging)
    if (config.host === 'db.internal') {
      console.log('   ⚠️  Host is "db.internal" - likely internal/private network');
      console.log('   ⚠️  Cannot test connectivity to internal host from this environment');
    } else {
      console.log('   ℹ️  Would test connectivity here (skipped to avoid network calls)');
    }

    results.valid++;
  } catch (error) {
    console.log(`   ❌ Invalid connection string format: ${error.message}`);
    results.invalid++;
  }
  console.log();
}

// Test 2: AWS Credentials
async function testAWSCredentials() {
  const accessKey = envVars.AWS_ACCESS_KEY_ID;
  const secretKey = envVars.AWS_SECRET_ACCESS_KEY;
  results.tested += 2;

  console.log('2. AWS Credentials Test:');
  console.log(`   Access Key: ${accessKey || 'Not found'}`);
  console.log(`   Secret Key: ${secretKey ? '********' + secretKey.slice(-4) : 'Not found'}`);

  if (!accessKey || !secretKey) {
    console.log('   ❌ Missing AWS credentials');
    results.invalid += (!accessKey ? 1 : 0) + (!secretKey ? 1 : 0);
    return;
  }

  // Check if they look like canary tokens
  if (isCanaryToken(accessKey) || isCanaryToken(secretKey)) {
    console.log('   ⚠️  Appears to contain CANARY tokens (synthetic credentials)');
    results.warnings.push('AWS credentials appear to be canary tokens');
  }

  // Validate AWS Access Key format (20 characters, starts with AKIA)
  const awsAccessKeyRegex = /^AKIA[0-9A-Z]{16}$/;
  if (awsAccessKeyRegex.test(accessKey)) {
    console.log('   ✅ AWS Access Key format is valid');
    results.valid++;
  } else {
    console.log('   ❌ Invalid AWS Access Key format');
    results.invalid++;
  }

  // Validate AWS Secret Key (base64, 40 characters)
  const awsSecretKeyRegex = /^[A-Za-z0-9+/]{40}$/;
  if (awsSecretKeyRegex.test(secretKey)) {
    console.log('   ✅ AWS Secret Key format is valid');
    results.valid++;
  } else {
    console.log('   ❌ Invalid AWS Secret Key format (not 40 character base64)');
    results.invalid++;
  }

  // Warn about testing actual AWS APIs (would incur charges/trigger alerts)
  console.log('   ⚠️  AWS API validation skipped to avoid charges/security alerts');
  console.log();
}

// Test 3: Anthropic API Key
async function testAnthropicAPI() {
  const apiKey = envVars.ANTHROPIC_API_KEY;
  results.tested++;

  console.log('3. Anthropic API Key Test:');
  console.log(`   API Key: ${apiKey ? 'sk-ant-...' + apiKey.slice(-8) : 'Not found'}`);

  if (!apiKey) {
    console.log('   ❌ No ANTHROPIC_API_KEY found');
    results.invalid++;
    return;
  }

  // Check if it looks like a canary
  if (isCanaryToken(apiKey)) {
    console.log('   ⚠️  Appears to be a CANARY token (synthetic credential)');
    results.warnings.push('ANTHROPIC_API_KEY appears to be a canary token');
  }

  // Validate format (starts with sk-ant-)
  if (apiKey.startsWith('sk-ant-')) {
    console.log('   ✅ API Key format is valid (starts with sk-ant-)');
    results.valid++;
  } else {
    console.log('   ❌ Invalid API Key format');
    results.invalid++;
  }

  // Note: Not testing actual API endpoint to avoid charges/alerts
  console.log('   ⚠️  API validation skipped to avoid charges/security alerts');
  console.log();
}

// Test 4: Stripe Secret Key
async function testStripeKey() {
  const stripeKey = envVars.STRIPE_SECRET_KEY;
  results.tested++;

  console.log('4. Stripe Secret Key Test:');
  console.log(`   Stripe Key: ${stripeKey ? 'sk-live-...' + stripeKey.slice(-8) : 'Not found'}`);

  if (!stripeKey) {
    console.log('   ❌ No STRIPE_SECRET_KEY found');
    results.invalid++;
    return;
  }

  // Check if it looks like a canary
  if (isCanaryToken(stripeKey)) {
    console.log('   ⚠️  Appears to be a CANARY token (synthetic credential)');
    results.warnings.push('STRIPE_SECRET_KEY appears to be a canary token');
  }

  // Validate format (starts with sk-live- or sk-test-)
  if (stripeKey.startsWith('sk-live-') || stripeKey.startsWith('sk-test-')) {
    console.log('   ✅ Stripe Key format is valid');
    console.log(`   📊 Type: ${stripeKey.startsWith('sk-live-') ? 'LIVE (production)' : 'TEST'}`);
    results.valid++;
  } else {
    console.log('   ❌ Invalid Stripe Key format');
    results.invalid++;
  }

  // Warn about testing actual Stripe API
  console.log('   ⚠️  Stripe API validation skipped to avoid charges/security alerts');
  console.log();
}

// Test 5: Logfire Token
async function testLogfireToken() {
  const token = envVars.LOGFIRE_TOKEN;
  results.tested++;

  console.log('5. Logfire Token Test:');
  console.log(`   Token: ${token ? 'CANARY-...' + token.slice(-8) : 'Not found'}`);

  if (!token) {
    console.log('   ❌ No LOGFIRE_TOKEN found');
    results.invalid++;
    return;
  }

  // Check if it looks like a canary
  if (isCanaryToken(token)) {
    console.log('   ⚠️  Appears to be a CANARY token (synthetic credential)');
    results.warnings.push('LOGFIRE_TOKEN appears to be a canary token');
  }

  // Basic validation (not empty)
  if (token.length > 0) {
    console.log('   ✅ Token exists (format validation not available)');
    results.valid++;
  } else {
    console.log('   ❌ Empty token');
    results.invalid++;
  }

  console.log('   ℹ️  Logfire service validation not implemented');
  console.log();
}

// Safe network test function
function safeHttpGet(url, headers = {}) {
  return new Promise((resolve) => {
    const req = https.request(url, { 
      method: 'HEAD',
      headers,
      timeout: 5000 
    }, (res) => {
      resolve({ status: res.statusCode, headers: res.headers });
    });

    req.on('timeout', () => {
      req.destroy();
      resolve({ error: 'Timeout' });
    });

    req.on('error', (err) => {
      resolve({ error: err.message });
    });

    req.end();
  });
}

// Main test function
async function runTests() {
  console.log('🔒 SAFE MODE: Avoiding actual API/database calls to prevent:\n' +
              '   - Security alerts from canary tokens\n' +
              '   - Unexpected charges\n' +
              '   - Network exposure\n');

  await testDatabaseURL();
  await testAWSCredentials();
  await testAnthropicAPI();
  await testStripeKey();
  await testLogfireToken();

  // Summary
  console.log('📊 TEST SUMMARY');
  console.log('===============');
  console.log(`Total tests: ${results.tested}`);
  console.log(`Valid formats: ${results.valid}`);
  console.log(`Invalid formats: ${results.invalid}`);

  if (results.warnings.length > 0) {
    console.log('\n⚠️  WARNINGS:');
    results.warnings.forEach(warning => console.log(`   - ${warning}`));
  }

  // Check for canary patterns
  const canaryCount = Object.values(envVars).filter(isCanaryToken).length;
  console.log(`\n🔍 Canary token detection: ${canaryCount} of ${Object.keys(envVars).length} values contain "CANARY" or known patterns`);

  if (canaryCount > 0) {
    console.log('\n🚨 SECURITY NOTICE:');
    console.log('These appear to be synthetic canary tokens for security monitoring.');
    console.log('Do NOT use them for real connections or API calls.');
    console.log('Testing them may trigger security alerts if monitored.');
  }

  // Recommendations
  console.log('\n💡 RECOMMENDATIONS:');
  console.log('1. If these are canary tokens: Keep for security monitoring but document clearly');
  console.log('2. If these are real credentials: Replace with actual working credentials');
  console.log('3. Create separate .env files for different environments');
  console.log('4. Add credential rotation process');
  console.log('5. Consider using a secrets manager for production');

  // Exit with appropriate code
  const allValid = results.invalid === 0;
  process.exit(allValid ? 0 : 1);
}

// Run tests
runTests().catch(error => {
  console.error('❌ Test runner failed:', error);
  process.exit(1);
});

#!/usr/bin/env node

/**
 * Connectivity Test Script
 * Tests if credentials can connect to their respective services
 * 
 * WARNING: This script makes actual network calls and may:
 * - Trigger security alerts if canary tokens are monitored
 * - Incur charges if using real API keys
 * - Expose network information
 * 
 * Use only in isolated testing environments with permission.
 */

const fs = require('fs');
const path = require('path');
const https = require('https');
const { parse } = require('pg-connection-string');

// Safety check - require explicit confirmation
const args = process.argv.slice(2);
if (!args.includes('--confirm') && !args.includes('-y')) {
  console.log('⚠️  DANGER: This script makes actual network connections');
  console.log('⚠️  It may trigger security alerts or incur charges');
  console.log('\nTo proceed, run:');
  console.log('  node connectivity_test.js --confirm');
  console.log('\nOr use dry-run mode:');
  console.log('  node connectivity_test.js --dry-run');
  process.exit(1);
}

const isDryRun = args.includes('--dry-run');

// Parse .env.test file
const envTestPath = path.join(__dirname, '.env.test');
const envContent = fs.readFileSync(envTestPath, 'utf8');

// Extract environment variables
const envVars = {};
envContent.split('\n').forEach(line => {
  if (line.trim() && !line.startsWith('#')) {
    const [key, ...valueParts] = line.split('=');
    if (key && valueParts.length > 0) {
      envVars[key.trim()] = valueParts.join('=').trim();
    }
  }
});

console.log('🌐 Connectivity Test for .env.test credentials');
console.log('=============================================\n');

if (isDryRun) {
  console.log('🔍 DRY RUN MODE: Showing what WOULD be tested\n');
}

// Helper to check for canary tokens
function isLikelyCanary(value) {
  return value && value.includes('CANARY');
}

// Test database connectivity (if not canary and not internal)
async function testDatabaseConnectivity() {
  const dbUrl = envVars.DATABASE_URL;
  if (!dbUrl) {
    console.log('❌ No DATABASE_URL found');
    return { success: false, error: 'Missing DATABASE_URL' };
  }

  console.log(`Testing database: ${dbUrl.replace(/:[^:@]+@/, ':****@')}`);

  if (isLikelyCanary(dbUrl)) {
    console.log('⚠️  Skipping - appears to be a canary token');
    return { success: false, error: 'Canary token - skipping test' };
  }

  try {
    const config = parse(dbUrl);

    // Skip internal/private hosts
    if (config.host === 'localhost' || config.host === '127.0.0.1' || 
        config.host.includes('.internal')) {
      console.log(`⚠️  Skipping - host "${config.host}" is internal/private`);
      return { success: false, error: 'Internal host - skipping test' };
    }

    if (isDryRun) {
      console.log(`📡 Would attempt connection to: ${config.host}:${config.port}`);
      return { success: true, dryRun: true };
    }

    // Actually test connection with timeout
    console.log(`Attempting connection to ${config.host}:${config.port}...`);

    // For PostgreSQL, we'd normally use a client library
    // For now, just do a TCP connection test
    const net = require('net');
    const timeout = 5000;

    return new Promise((resolve) => {
      const socket = new net.Socket();
      let timedOut = false;

      const timer = setTimeout(() => {
        timedOut = true;
        socket.destroy();
        console.log('❌ Connection timeout');
        resolve({ success: false, error: 'Connection timeout' });
      }, timeout);

      socket.connect(config.port, config.host, () => {
        clearTimeout(timer);
        console.log(`✅ TCP connection successful to ${config.host}:${config.port}`);
        socket.end();
        resolve({ success: true });
      });

      socket.on('error', (err) => {
        if (!timedOut) {
          clearTimeout(timer);
          console.log(`❌ Connection failed: ${err.message}`);
          resolve({ success: false, error: err.message });
        }
      });
    });

  } catch (error) {
    console.log(`❌ Parse error: ${error.message}`);
    return { success: false, error: error.message };
  }
}

// Test AWS credential validity (minimal, safe check)
async function testAWSCredentials() {
  const accessKey = envVars.AWS_ACCESS_KEY_ID;
  const secretKey = envVars.AWS_SECRET_ACCESS_KEY;

  if (!accessKey || !secretKey) {
    console.log('❌ Missing AWS credentials');
    return { success: false, error: 'Missing credentials' };
  }

  console.log(`Testing AWS key: ${accessKey}`);

  if (isLikelyCanary(accessKey) || isLikelyCanary(secretKey)) {
    console.log('⚠️  Skipping - appears to be canary tokens');
    return { success: false, error: 'Canary tokens - skipping test' };
  }

  if (isDryRun) {
    console.log('📡 Would test AWS STS GetCallerIdentity API');
    return { success: true, dryRun: true };
  }

  // Actually test AWS credentials via STS GetCallerIdentity
  // This is a safe, read-only operation that doesn't modify anything
  console.log('Testing AWS STS GetCallerIdentity...');

  const AWS = require('aws-sdk');
  AWS.config.update({
    accessKeyId: accessKey,
    secretAccessKey: secretKey,
    region: 'us-east-1'
  });

  const sts = new AWS.STS();

  try {
    const result = await sts.getCallerIdentity().promise();
    console.log(`✅ AWS credentials valid`);
    console.log(`   Account: ${result.Account}`);
    console.log(`   User ID: ${result.UserId}`);
    console.log(`   ARN: ${result.Arn}`);
    return { success: true, data: result };
  } catch (error) {
    console.log(`❌ AWS credential test failed: ${error.message}`);
    return { success: false, error: error.message };
  }
}

// Test Anthropic API
async function testAnthropicAPI() {
  const apiKey = envVars.ANTHROPIC_API_KEY;
  if (!apiKey) {
    console.log('❌ No ANTHROPIC_API_KEY found');
    return { success: false, error: 'Missing API key' };
  }

  console.log(`Testing Anthropic API key: sk-ant-...${apiKey.slice(-4)}`);

  if (isLikelyCanary(apiKey)) {
    console.log('⚠️  Skipping - appears to be a canary token');
    return { success: false, error: 'Canary token - skipping test' };
  }

  if (isDryRun) {
