/**
 * Credential Analyzer
 * Analyzes .env.test credentials without making network calls
 * Safely determines if credentials are valid, stale, or canary tokens
 */

const fs = require('fs');
const path = require('path');

// Parse .env.test file
const envTestPath = path.join(__dirname, '.env.test');
const envContent = fs.readFileSync(envTestPath, 'utf8');

console.log('🔍 Analyzing credentials in .env.test');
console.log('=====================================\n');

// Extract and analyze each variable
const lines = envContent.split('\n');
const credentials = [];

lines.forEach((line, index) => {
  line = line.trim();

  // Skip comments and empty lines
  if (!line || line.startsWith('#')) {
    return;
  }

  const [key, ...valueParts] = line.split('=');
  if (!key || valueParts.length === 0) return;

  const keyName = key.trim();
  const value = valueParts.join('=').trim();

  credentials.push({ key: keyName, value, lineNumber: index + 1 });
});

// Analyze each credential
credentials.forEach(cred => {
  console.log(`📋 ${cred.key}:`);
  console.log(`   Value: ${obfuscateValue(cred.key, cred.value)}`);

  const analysis = analyzeCredential(cred.key, cred.value);

  console.log(`   Type: ${analysis.type}`);
  console.log(`   Status: ${analysis.status}`);

  if (analysis.details) {
    console.log(`   Details: ${analysis.details}`);
  }

  if (analysis.recommendation) {
    console.log(`   Recommendation: ${analysis.recommendation}`);
  }

  console.log();
});

// Summary
console.log('📊 ANALYSIS SUMMARY');
console.log('===================\n');

const types = {};
const statuses = {};

credentials.forEach(cred => {
  const analysis = analyzeCredential(cred.key, cred.value);
  types[analysis.type] = (types[analysis.type] || 0) + 1;
  statuses[analysis.status] = (statuses[analysis.status] || 0) + 1;
});

console.log('By Type:');
Object.entries(types).forEach(([type, count]) => {
  console.log(`  ${type}: ${count}`);
});

console.log('\nBy Status:');
Object.entries(statuses).forEach(([status, count]) => {
  console.log(`  ${status}: ${count}`);
});

// Count canary tokens
const canaryCount = credentials.filter(c => 
  c.value.includes('CANARY') || analyzeCredential(c.key, c.value).type === 'Canary Token'
).length;

console.log(`\n🚨 Canary Tokens Detected: ${canaryCount} of ${credentials.length}`);

if (canaryCount > 0) {
  console.log('\n⚠️  SECURITY NOTE:');
  console.log('Canary tokens are synthetic credentials for security monitoring.');
  console.log('They are designed to trigger alerts if used or exfiltrated.');
  console.log('Do NOT use them for actual API calls or database connections.');
}

// Recommendations
console.log('\n💡 RECOMMENDATIONS:');
if (canaryCount === credentials.length) {
  console.log('1. ALL credentials are canary tokens');
  console.log('2. Replace with actual working credentials for development');
  console.log('3. Keep canary file separate or clearly marked');
} else if (canaryCount > 0) {
