  console.log('2. Separate canary tokens from working credentials');
  console.log('3. Verify real credentials are still valid');
} else {
  console.log('1. No canary tokens detected');
  console.log('2. Test if credentials are still valid');
  console.log('3. Rotate any credentials that have been in use for >90 days');
}

console.log('\n🔧 Next Steps:');
console.log('1. For safe validation: node test_credentials.js');
console.log('2. For actual testing (CAUTION): node connectivity_test.js --dry-run');
console.log('3. To see what would be tested: node connectivity_test.js --dry-run');

// Helper functions
function obfuscateValue(key, value) {
  if (!value) return '[empty]';

  // Don't obfuscate URLs as much
  if (key.includes('URL')) {
    return value.replace(/:[^:@]+@/, ':****@');
  }

  // Obfuscate secrets
  if (key.includes('SECRET') || key.includes('KEY') || key.includes('TOKEN')) {
    if (value.length <= 8) return '****';
    return value.substring(0, 4) + '****' + value.substring(value.length - 4);
  }

  return value;
}

function analyzeCredential(key, value) {
  const analysis = {
    type: 'Unknown',
    status: 'Unknown',
    details: null,
    recommendation: null
  };

  // Check for canary tokens
  if (value.includes('CANARY')) {
    analysis.type = 'Canary Token';
    analysis.status = 'Synthetic/Monitored';
    analysis.details = 'Designed for exfiltration detection';
    analysis.recommendation = 'Do not use for real connections';
    return analysis;
  }

  // Database URL analysis
  if (key === 'DATABASE_URL') {
    analysis.type = 'Database Connection';

    try {
      const url = new URL(value);
      analysis.details = `Protocol: ${url.protocol}, Host: ${url.hostname}`;

      if (url.hostname.includes('.internal') || url.hostname === 'localhost') {
        analysis.status = 'Internal/Private';
        analysis.recommendation = 'Test in appropriate network environment';
      } else {
        analysis.status = 'External';
        analysis.recommendation = 'Verify connectivity and permissions';
      }
    } catch (error) {
      analysis.status = 'Invalid Format';
      analysis.details = `URL parse error: ${error.message}`;
    }

    return analysis;
  }

  // AWS credentials analysis
  if (key.includes('AWS')) {
    analysis.type = 'AWS Credential';

    if (key === 'AWS_ACCESS_KEY_ID') {
      // AWS Access Key format: AKIA followed by 16 alphanumeric chars
      const isValidFormat = /^AKIA[0-9A-Z]{16}$/.test(value);
      analysis.status = isValidFormat ? 'Valid Format' : 'Invalid Format';
      analysis.details = `Length: ${value.length} chars`;

      if (!isValidFormat) {
        analysis.recommendation = 'AWS Access Keys should be 20 chars starting with AKIA';
      }
    } else if (key === 'AWS_SECRET_ACCESS_KEY') {
      // AWS Secret Key: 40 character base64
      const isValidFormat = /^[A-Za-z0-9+/]{40}$/.test(value);
      analysis.status = isValidFormat ? 'Valid Format' : 'Invalid Format';
      analysis.details = `Length: ${value.length} chars`;

      if (!isValidFormat) {
        analysis.recommendation = 'AWS Secret Keys should be 40 character base64';
      }
    }

    return analysis;
  }

  // API Key analysis
  if (key.includes('API_KEY') || key.includes('_KEY')) {
    analysis.type = 'API Key/Token';

    if (value.startsWith('sk-ant-')) {
      analysis.status = 'Anthropic Format';
      analysis.details = 'Anthropic Claude API key';
    } else if (value.startsWith('sk-live-') || value.startsWith('sk-test-')) {
      analysis.status = value.startsWith('sk-live-') ? 'Stripe Live' : 'Stripe Test';
      analysis.details = 'Stripe payment API key';
      analysis.recommendation = value.startsWith('sk-live-') 
        ? 'LIVE key - use with caution' 
        : 'Test key - safe for development';
    } else if (value.startsWith('sk-')) {
      analysis.status = 'Generic API Key';
      analysis.details = 'Starts with sk- (common format)';
    } else {
      analysis.status = 'Unknown Format';
    }

    // Check if token looks old/stale
    if (value.length < 10) {
      analysis.recommendation = 'Key seems very short - may be invalid';
    }

    return analysis;
  }

  // Generic token analysis
  if (key.includes('TOKEN')) {
    analysis.type = 'Authentication Token';

    if (value.length < 16) {
      analysis.status = 'Potentially Invalid';
      analysis.recommendation = 'Tokens are typically longer than 16 chars';
    } else if (value.length >= 16 && value.length <= 64) {
      analysis.status = 'Standard Length';
    } else {
      analysis.status = 'Long Token';
    }

    return analysis;
  }

  // Default analysis
  analysis.type = 'Configuration Value';
  analysis.status = 'Unknown Validity';
  analysis.recommendation = 'Test with appropriate service';

  return analysis;
}

