// Improved Express application with comprehensive error handling and security features
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, query, validationResult } = require('express-validator');
const winston = require('winston');

// Initialize Express app
const app = express();

// ====================
// 1. SECURITY MIDDLEWARE
// ====================

// Security headers with Helmet
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            styleSrc: ["'self'", "'unsafe-inline'"],
            scriptSrc: ["'self'"],
            imgSrc: ["'self'", "data:", "https:"],
        },
    },
    hsts: {
        maxAge: 31536000,
        includeSubDomains: true,
        preload: true
    }
}));

// CORS configuration (restrict to specific origins in production)
app.use(cors({
    origin: process.env.NODE_ENV === 'production' 
        ? ['https://yourdomain.com'] 
        : ['http://localhost:3000', 'http://localhost:8080'],
    credentials: true,
    optionsSuccessStatus: 200
}));

// Rate limiting
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // limit each IP to 100 requests per windowMs
    message: 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false,
});
app.use(limiter);

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ====================
// 2. LOGGING CONFIGURATION
// ====================

const logger = winston.createLogger({
    level: process.env.NODE_ENV === 'production' ? 'info' : 'debug',
    format: winston.format.combine(
        winston.format.timestamp(),
        winston.format.errors({ stack: true }),
        winston.format.json()
    ),
    transports: [
        new winston.transports.Console({
            format: winston.format.combine(
                winston.format.colorize(),
                winston.format.simple()
            )
        }),
        new winston.transports.File({ filename: 'error.log', level: 'error' }),
        new winston.transports.File({ filename: 'combined.log' })
    ],
});

// Request logging middleware
app.use((req, res, next) => {
    logger.info({
        method: req.method,
        url: req.url,
        ip: req.ip,
        userAgent: req.get('User-Agent')
    });
    next();
});

// ====================
// 3. VALIDATION MIDDLEWARE
// ====================

// Validation error handler
const validateRequest = (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
        return res.status(400).json({
            success: false,
            errors: errors.array().map(err => ({
                param: err.param,
                msg: err.msg,
                location: err.location
            }))
        });
    }
    next();
};

// ====================
// 4. ROUTES WITH VALIDATION
// ====================

// Health endpoint with validation
app.get('/health', 
    query('detailed').optional().isBoolean().withMessage('detailed must be a boolean'),
    validateRequest,
    (req, res) => {
        try {
            const response = {
                status: 'ok',
                timestamp: new Date().toISOString(),
                uptime: process.uptime(),
                memoryUsage: process.memoryUsage()
            };

            if (req.query.detailed === 'true') {
                response.details = {
                    nodeVersion: process.version,
                    platform: process.platform,
                    env: process.env.NODE_ENV || 'development'
                };
            }

            res.json(response);
        } catch (error) {
            logger.error('Health check error:', error);
            res.status(500).json({
                success: false,
                error: 'Internal server error',
                message: process.env.NODE_ENV === 'development' ? error.message : undefined
            });
        }
    }
);

// Users endpoint with validation and pagination
app.get('/users',
    query('page').optional().isInt({ min: 1 }).withMessage('page must be a positive integer'),
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('limit must be between 1 and 100'),
    query('search').optional().isString().trim().escape().withMessage('search must be a string'),
    validateRequest,
    async (req, res) => {
        try {
            const { page = 1, limit = 10, search = '' } = req.query;
            const offset = (page - 1) * limit;

            // This would typically come from a database - simulating for demo
            const users = [
                { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
                { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
                { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'admin' }
            ];

            // Filter users based on search query
            const filteredUsers = search 
                ? users.filter(user => 
                    user.name.toLowerCase().includes(search.toLowerCase()) ||
                    user.email.toLowerCase().includes(search.toLowerCase())
                ) 
                : users;

            // Paginate results
            const paginatedUsers = filteredUsers.slice(offset, offset + parseInt(limit));

            res.json({
                success: true,
                data: paginatedUsers,
                pagination: {
                    page: parseInt(page),
                    limit: parseInt(limit),
                    total: filteredUsers.length,
                    totalPages: Math.ceil(filteredUsers.length / limit)
                }
            });
        } catch (error) {
            logger.error('Users endpoint error:', error);
            res.status(500).json({
                success: false,
                error: 'Failed to fetch users',
                message: process.env.NODE_ENV === 'development' ? error.message : undefined
            });
        }
    }
);

// Example POST endpoint with validation
app.post('/users',
    body('name').isString().trim().notEmpty().withMessage('Name is required'),
    body('email').isEmail().normalizeEmail().withMessage('Valid email is required'),
    body('role').optional().isIn(['user', 'admin']).withMessage('Role must be either user or admin'),
    validateRequest,
    async (req, res) => {
        try {
            const { name, email, role = 'user' } = req.body;

            // Here you would typically save to database
            logger.info(`Creating user: ${email}`);

            res.status(201).json({
                success: true,
                message: 'User created successfully',
                data: {
                    id: Date.now(), // Simulated ID
                    name,
                    email,
                    role,
                    createdAt: new Date().toISOString()
                }
            });
        } catch (error) {
            logger.error('Create user error:', error);
            res.status(500).json({
                success: false,
                error: 'Failed to create user',
                message: process.env.NODE_ENV === 'development' ? error.message : undefined
            });
        }
    }
);

// ====================
// 5. ERROR HANDLING MIDDLEWARE
// ====================

// 404 Handler
app.use((req, res, next) => {
    res.status(404).json({
        success: false,
        error: 'Resource not found',
        message: `Cannot ${req.method} ${req.url}`
    });
});

// Global error handler
app.use((error, req, res, next) => {
    logger.error('Unhandled error:', error);

    // Handle different types of errors
    if (error.type === 'entity.parse.failed') {
        return res.status(400).json({
            success: false,
            error: 'Invalid JSON payload'
        });
    }

    // Default error response
    const statusCode = error.statusCode || 500;
    const response = {
        success: false,
        error: error.message || 'Internal server error'
    };

    // Only include stack trace in development
    if (process.env.NODE_ENV === 'development') {
        response.stack = error.stack;
    }

    res.status(statusCode).json(response);
});

// ====================
// 6. SERVER SETUP
// ====================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
    logger.error('Uncaught Exception:', error);
    process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
    logger.error('Unhandled Rejection:', reason);
    process.exit(1);
});

const server = app.listen(PORT, () => {
    logger.info(`Server running in ${NODE_ENV} mode on port ${PORT}`);
});

// Graceful shutdown
const shutdown = (signal) => {
    logger.info(`${signal} received. Starting graceful shutdown...`);

    server.close(() => {
        logger.info('HTTP server closed.');
        process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
        logger.error('Could not close connections in time, forcefully shutting down');
        process.exit(1);
    }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

module.exports = { app, server };

# Security Improvements and Best Practices for app.js

## Summary of Issues in Original app.js

1. **No Input Validation**: No validation of query parameters, request bodies, or headers
2. **No Error Handling**: No centralized error handling or proper error responses
3. **Missing Security Headers**: No protection against common web vulnerabilities
4. **No Rate Limiting**: Vulnerable to DoS attacks
5. **No Logging**: No request/error logging for monitoring and debugging
6. **No Environment Configuration**: Hardcoded values and no environment-based settings

## Key Improvements Made

### 1. **Security Headers (Helmet.js)**
```javascript
app.use(helmet({
    contentSecurityPolicy: { ... },
    hsts: { maxAge: 31536000, includeSubDomains: true, preload: true }
}));
```
- **CSP**: Prevents XSS attacks by controlling resource loading
- **HSTS**: Forces HTTPS connections
- **XSS Protection**: Browser XSS filter
- **No Sniff**: Prevents MIME type sniffing

### 2. **Input Validation & Sanitization (express-validator)**
```javascript
app.get('/users',
    query('page').optional().isInt({ min: 1 }),
    query('limit').optional().isInt({ min: 1, max: 100 }),
    query('search').optional().isString().trim().escape(),
    validateRequest,
    // ... handler
);
```
- **Type validation**: Ensures correct data types
- **Range validation**: Limits numeric values to safe ranges
- **Sanitization**: Trims and escapes user input
- **Custom validators**: Business logic validation

### 3. **Comprehensive Error Handling**
```javascript
// Global error handler
app.use((error, req, res, next) => {
    logger.error('Unhandled error:', error);

    // Handle specific error types
    if (error.type === 'entity.parse.failed') {
        return res.status(400).json({ error: 'Invalid JSON payload' });
    }

    // Never expose stack traces in production
    const response = {
        success: false,
        error: error.message || 'Internal server error'
    };

    if (process.env.NODE_ENV === 'development') {
        response.stack = error.stack;
    }

    res.status(error.statusCode || 500).json(response);
});
```

### 4. **Rate Limiting**
```javascript
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // 100 requests per IP
    message: 'Too many requests'
});
app.use(limiter);
```
- Prevents brute force and DoS attacks
- Configurable limits based on endpoint sensitivity

### 5. **Request Logging & Monitoring**
```javascript
const logger = winston.createLogger({
    level: process.env.NODE_ENV === 'production' ? 'info' : 'debug',
    format: winston.format.combine(
        winston.format.timestamp(),
        winston.format.errors({ stack: true }),
        winston.format.json()
    ),
    transports: [
        new winston.transports.Console(),
        new winston.transports.File({ filename: 'error.log', level: 'error' })
    ]
});
```

### 6. **Environment-Based Configuration**
```javascript
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// CORS configuration varies by environment
app.use(cors({
    origin: process.env.NODE_ENV === 'production' 
        ? ['https://yourdomain.com'] 
        : ['http://localhost:3000', 'http://localhost:8080']
}));
```

### 7. **Graceful Shutdown**
```javascript
const shutdown = (signal) => {
    logger.info(`${signal} received. Starting graceful shutdown...`);

    server.close(() => {
        logger.info('HTTP server closed.');
        process.exit(0);
    });

    // Force shutdown after timeout
    setTimeout(() => {
        logger.error('Could not close connections in time');
        process.exit(1);
    }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
```

## Additional Security Recommendations

### 8. **Environment Variables**
```bash
# .env file (NEVER commit to version control!)
NODE_ENV=production
PORT=3000
DATABASE_URL=your_database_url
JWT_SECRET=your_jwt_secret
API_RATE_LIMIT_WINDOW=900000
API_RATE_LIMIT_MAX=100
ALLOWED_ORIGINS=https://yourdomain.com
```

### 9. **Database Security**
```javascript
// Use parameterized queries to prevent SQL injection
const query = 'SELECT * FROM users WHERE id = $1';
const values = [userId];
await pool.query(query, values);
```

### 10. **Authentication & Authorization**
```javascript
// JWT Token validation middleware
const authenticateToken = (req, res, next) => {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1];

    if (!token) return res.status(401).json({ error: 'Access token required' });

    jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
        if (err) return res.status(403).json({ error: 'Invalid token' });
        req.user = user;
        next();
    });
};

// Role-based authorization
const authorizeRoles = (...allowedRoles) => {
    return (req, res, next) => {
        if (!req.user || !allowedRoles.includes(req.user.role)) {
            return res.status(403).json({ error: 'Insufficient permissions' });
        }
        next();
    };
};
```

### 11. **File Upload Security**
```javascript
// Secure file upload configuration
const upload = multer({
    storage: multer.memoryStorage(),
    limits: {
        fileSize: 5 * 1024 * 1024, // 5MB limit
        files: 1
    },
    fileFilter: (req, file, cb) => {
        const allowedTypes = ['image/jpeg', 'image/png', 'application/pdf'];
        if (!allowedTypes.includes(file.mimetype)) {
            return cb(new Error('Invalid file type'), false);
        }
        cb(null, true);
    }
});
```

### 12. **Security Headers Checklist**
```javascript
// Additional security headers
app.use((req, res, next) => {
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('X-Frame-Options', 'DENY');
    res.setHeader('X-XSS-Protection', '1; mode=block');
    res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
    res.setHeader('Permissions-Policy', 'geolocation=(self), microphone=()');
    next();
});
```

