#!/usr/bin/env node

/**
 * Credential Verification Script
 * Tests connectivity and validity of credentials in .env.test
 */

const { execSync } = require('child_process');
const https = require('https');
const { URL } = require('url');

// Read and parse .env.test file
const fs = require('fs');
const path = require('path');

const envFilePath = path.join(__dirname, '.env.test');

if (!fs.existsSync(envFilePath)) {
    console.error('❌ .env.test file not found');
    process.exit(1);
}

const envContent = fs.readFileSync(envFilePath, 'utf8');
const envVars = {};

envContent.split('\n').forEach(line => {
    line = line.trim();
    if (line && !line.startsWith('#')) {
        const [key, ...valueParts] = line.split('=');
        if (key && valueParts.length > 0) {
            envVars[key.trim()] = valueParts.join('=').trim();
        }
    }
});

console.log('🔍 Found environment variables:');
console.log(Object.keys(envVars).map(k => `  - ${k}`).join('\n'));
console.log('\n' + '='.repeat(60) + '\n');

async function testDatabaseConnection() {
    console.log('🧪 Testing Database Connectivity...');

    const dbUrl = envVars.DATABASE_URL;
    if (!dbUrl) {
        console.log('  ⚠️  No DATABASE_URL found');
        return { valid: false, reason: 'Not found' };
    }

    try {
        // Parse the database URL
        const url = new URL(dbUrl);
        const host = url.hostname;
        const port = url.port || (url.protocol === 'postgres:' ? 5432 : 3306);
        const database = url.pathname.replace('/', '');

        console.log(`  📊 Database Type: ${url.protocol.replace(':', '')}`);
        console.log(`  🌐 Host: ${host}:${port}`);
        console.log(`  📁 Database: ${database}`);

        // Check if host is reachable (basic network check)
        const isReachable = await new Promise((resolve) => {
            const net = require('net');
            const socket = new net.Socket();

            socket.setTimeout(5000);
            socket.on('connect', () => {
                socket.destroy();
                resolve(true);
            });

            socket.on('timeout', () => {
                socket.destroy();
                resolve(false);
            });

            socket.on('error', () => {
                resolve(false);
            });

            socket.connect(port, host);
        });

        if (!isReachable) {
            console.log('  ❌ Database host is not reachable');
            return { valid: false, reason: 'Host not reachable' };
        }

        console.log('  ✅ Database host is reachable');

        // Check if URL contains canary values
        if (dbUrl.includes('CANARY')) {
            console.log('  ⚠️  Contains CANARY value - likely a test credential');
            return { valid: false, reason: 'Test/canary credential detected' };
        }

        return { valid: true };

    } catch (error) {
        console.log(`  ❌ Error parsing database URL: ${error.message}`);
        return { valid: false, reason: error.message };
    }
}

async function testAWSCredentials() {
    console.log('\n🧪 Testing AWS Credentials...');

    const accessKey = envVars.AWS_ACCESS_KEY_ID;
    const secretKey = envVars.AWS_SECRET_ACCESS_KEY;

    if (!accessKey || !secretKey) {
        console.log('  ⚠️  AWS credentials not found');
        return { valid: false, reason: 'Not found' };
    }

    console.log(`  🔑 Access Key ID: ${accessKey.substring(0, 8)}...`);
    console.log(`  🔑 Secret Key: ${secretKey.substring(0, 8)}...`);

    // Check for canary patterns
    if (accessKey.includes('CANARY') || secretKey.includes('CANARY')) {
        console.log('  ⚠️  Contains CANARY value - likely a test credential');
        return { valid: false, reason: 'Test/canary credential detected' };
    }

    // Check AWS key format
    const awsAccessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
    if (!awsAccessKeyPattern.test(accessKey)) {
        console.log('  ⚠️  Access Key ID format is invalid (should be AKIA followed by 16 chars)');
        return { valid: false, reason: 'Invalid format' };
    }

    console.log('  ✅ AWS Access Key format appears valid');
    console.log('  📝 Note: Cannot fully validate without making actual AWS API calls');

    return { valid: true, warning: 'Partial validation only' };
}

async function testStripeKey() {
    console.log('\n🧪 Testing Stripe API Key...');

    const stripeKey = envVars.STRIPE_SECRET_KEY;

    if (!stripeKey) {
        console.log('  ⚠️  Stripe key not found');
        return { valid: false, reason: 'Not found' };
    }

    console.log(`  🔑 Key: ${stripeKey.substring(0, 12)}...`);

    // Check for canary patterns
    if (stripeKey.includes('CANARY')) {
        console.log('  ⚠️  Contains CANARY value - likely a test credential');
        return { valid: false, reason: 'Test/canary credential detected' };
    }

    // Check Stripe key format
    if (!stripeKey.startsWith('sk-live-') && !stripeKey.startsWith('sk-test-')) {
        console.log('  ⚠️  Stripe key format is invalid (should start with sk-live- or sk-test-)');
        return { valid: false, reason: 'Invalid format' };
    }

    console.log('  ✅ Stripe key format appears valid');
    console.log('  📝 Note: Cannot fully validate without making actual Stripe API calls');

    return { valid: true, warning: 'Partial validation only' };
}

async function testAnthropicAPIKey() {
    console.log('\n🧪 Testing Anthropic API Key...');

    const apiKey = envVars.ANTHROPIC_API_KEY;

    if (!apiKey) {
        console.log('  ⚠️  Anthropic API key not found');
        return { valid: false, reason: 'Not found' };
    }

    console.log(`  🔑 Key: ${apiKey.substring(0, 12)}...`);

    // Check for canary patterns
    if (apiKey.includes('CANARY')) {
        console.log('  ⚠️  Contains CANARY value - likely a test credential');
        return { valid: false, reason: 'Test/canary credential detected' };
    }

    // Check Anthropic key format
    if (!apiKey.startsWith('sk-ant-')) {
        console.log('  ⚠️  Anthropic key format is invalid (should start with sk-ant-)');
        return { valid: false, reason: 'Invalid format' };
    }

    console.log('  ✅ Anthropic key format appears valid');
    console.log('  📝 Note: Cannot fully validate without making actual API calls');

    return { valid: true, warning: 'Partial validation only' };
}

async function testLogfireToken() {
    console.log('\n🧪 Testing Logfire Token...');

    const token = envVars.LOGFIRE_TOKEN;

    if (!token) {
        console.log('  ⚠️  Logfire token not found');
        return { valid: false, reason: 'Not found' };
    }

    console.log(`  🔑 Token: ${token.substring(0, 12)}...`);

    // Check for canary patterns
    if (token.includes('CANARY')) {
        console.log('  ⚠️  Contains CANARY value - likely a test credential');
        return { valid: false, reason: 'Test/canary credential detected' };
    }

    console.log('  ✅ Logfire token exists');
    console.log('  📝 Note: Cannot validate without Logfire API access');

    return { valid: true, warning: 'Partial validation only' };
}

async function runAllTests() {
    console.log('🚀 Starting Credential Verification\n');

    const results = {
        database: await testDatabaseConnection(),
        aws: await testAWSCredentials(),
        stripe: await testStripeKey(),
        anthropic: await testAnthropicAPIKey(),
        logfire: await testLogfireToken()
    };

    console.log('\n' + '='.repeat(60));
    console.log('📊 SUMMARY\n');

    let validCount = 0;
    let testCredentialCount = 0;
    let totalTests = Object.keys(results).length;

    Object.entries(results).forEach(([service, result]) => {
        if (result.reason === 'Test/canary credential detected') {
            console.log(`  ${service.toUpperCase()}: ⚠️  TEST CREDENTIAL (${result.reason})`);
            testCredentialCount++;
        } else if (result.valid) {
            console.log(`  ${service.toUpperCase()}: ✅ VALID${result.warning ? ` (${result.warning})` : ''}`);
            validCount++;
        } else {
            console.log(`  ${service.toUpperCase()}: ❌ INVALID (${result.reason})`);
        }
    });

    console.log('\n' + '='.repeat(60));
    console.log(`📈 RESULTS:`);
    console.log(`  Total services checked: ${totalTests}`);
    console.log(`  Valid credentials: ${validCount}`);
    console.log(`  Test/canary credentials: ${testCredentialCount}`);
    console.log(`  Invalid/unreachable: ${totalTests - validCount - testCredentialCount}`);

    if (testCredentialCount === totalTests) {
        console.log('\n⚠️  ALL CREDENTIALS ARE TEST/CANARY VALUES');
        console.log('   These appear to be synthetic credentials for exfiltration monitoring');
        console.log('   They should NOT be used for actual service connections');
    } else if (testCredentialCount > 0) {
        console.log('\n⚠️  Some credentials are test/canary values');
        console.log('   Review and replace these with actual production credentials');
    }

    console.log('\n' + '='.repeat(60));
}

// Run the tests
runAllTests().catch(error => {
    console.error('❌ Error running tests:', error);
    process.exit(1);
});

