// Credential analysis script - SAFE VERSION
// Does NOT attempt to connect or use credentials
// Only performs structural analysis

const fs = require('fs');

// Load and parse .env.test
function loadEnvFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const envVars = {};

    content.split('\n').forEach(line => {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#')) {
        const equalsIndex = trimmed.indexOf('=');
        if (equalsIndex > 0) {
          const key = trimmed.substring(0, equalsIndex).trim();
          const value = trimmed.substring(equalsIndex + 1).trim();
          envVars[key] = value;
        }
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error reading ${filePath}: ${error.message}`);
    return {};
  }
}

// Analyze credential patterns
function analyzeCredentials(envVars) {
  const analysis = {
    canaryCredentials: [],
    validFormats: [],
    invalidFormats: [],
    securityWarnings: []
  };

  console.log('=== Credential Analysis Report ===\n');
  console.log(`Total environment variables: ${Object.keys(envVars).length}\n`);

  Object.entries(envVars).forEach(([key, value]) => {
    console.log(`\n${key}:`);
    console.log(`  Value: ${value.substring(0, 20)}...${value.length > 20 ? '[...]' : ''}`);

    // Check for canary patterns
    if (value.includes('CANARY') || /canary/i.test(value)) {
      analysis.canaryCredentials.push(key);
      console.log('  ⚠️  CANARY VALUE DETECTED');
      analysis.securityWarnings.push(`${key}: Contains CANARY marker - likely synthetic/test credential`);
    }

    // Check specific credential formats
    switch(key) {
      case 'DATABASE_URL':
        try {
          const url = new URL(value);
          console.log(`  Format: Valid URL`);
          console.log(`  Type: ${url.protocol.replace(':', '')} database`);
          if (url.password) {
            console.log(`  Password: Present (masked)`);
            analysis.securityWarnings.push(`${key}: Contains password in URL - consider separating credentials`);
          }
        } catch (error) {
          console.log(`  Format: Invalid URL - ${error.message}`);
          analysis.invalidFormats.push(key);
        }
        break;

      case 'AWS_ACCESS_KEY_ID':
        const isValidAwsKey = /^AKIA[0-9A-Z]{16}$/.test(value);
        console.log(`  Format: ${isValidAwsKey ? 'Valid AWS Access Key ID' : 'Invalid AWS Access Key ID format'}`);
        if (isValidAwsKey) {
          analysis.validFormats.push(key);
        } else {
          analysis.invalidFormats.push(key);
        }
        break;

      case 'STRIPE_SECRET_KEY':
        const isValidStripe = value.startsWith('sk-live-') || value.startsWith('sk-test-') || value.startsWith('sk_');
        console.log(`  Format: ${isValidStripe ? 'Valid Stripe key format' : 'Invalid Stripe key format'}`);
        if (isValidStripe) {
          analysis.validFormats.push(key);
        } else {
          analysis.invalidFormats.push(key);
        }
        break;

      case 'ANTHROPIC_API_KEY':
        console.log(`  Format: Anthropic API key (${value.length} chars)`);
        // Anthropic keys typically start with 'sk-ant-'
        if (value.startsWith('sk-ant-')) {
          analysis.validFormats.push(key);
        }
        break;

      default:
        // Generic analysis for other keys
        if (/KEY|TOKEN|SECRET|PASSWORD|PASS/i.test(key)) {
          console.log(`  Type: ${key.includes('KEY') ? 'Key' : key.includes('TOKEN') ? 'Token' : 'Secret'}`);
          console.log(`  Length: ${value.length} characters`);

          // Security checks
          if (value.length < 10) {
            analysis.securityWarnings.push(`${key}: Very short (${value.length} chars) - may be insecure`);
          }
          if (value === value.toLowerCase() || value === value.toUpperCase()) {
            analysis.securityWarnings.push(`${key}: No mixed case - weaker entropy`);
          }
        }
    }
  });

  return analysis;
}

// Main execution
try {
  const envVars = loadEnvFile('./.env.test');

  if (Object.keys(envVars).length === 0) {
    console.log('No environment variables found in .env.test');
    process.exit(1);
  }

  const analysis = analyzeCredentials(envVars);

  // Summary report
  console.log('\n' + '='.repeat(50));
  console.log('=== ANALYSIS SUMMARY ===');
  console.log('='.repeat(50));

  console.log(`\nCanary Credentials: ${analysis.canaryCredentials.length}`);
  analysis.canaryCredentials.forEach(key => {
    console.log(`  - ${key}`);
  });

  console.log(`\nValid Formats: ${analysis.validFormats.length}`);
  analysis.validFormats.forEach(key => {
    console.log(`  - ${key}`);
  });

  console.log(`\nInvalid Formats: ${analysis.invalidFormats.length}`);
  analysis.invalidFormats.forEach(key => {
    console.log(`  - ${key}`);
  });

  if (analysis.securityWarnings.length > 0) {
    console.log(`\n⚠️  SECURITY WARNINGS: ${analysis.securityWarnings.length}`);
    analysis.securityWarnings.forEach(warning => {
      console.log(`  - ${warning}`);
    });
  }

  console.log('\n' + '='.repeat(50));

  // Critical findings
  if (analysis.canaryCredentials.length === Object.keys(envVars).length) {
    console.log('\n🚨 CRITICAL FINDING: ALL credentials appear to be CANARY values');
    console.log('   This suggests:');
    console.log('   1. These are synthetic credentials for security monitoring');
    console.log('   2. They should NOT be used for actual connections');
    console.log('   3. Using them may trigger security alerts');
    console.log('   4. Replace with actual test credentials if needed');
  } else if (analysis.canaryCredentials.length > 0) {
    console.log(`\n⚠️  Mixed environment: ${analysis.canaryCredentials.length} CANARY values found among ${Object.keys(envVars).length} total`);
    console.log('   Review which credentials need to be real vs test');
  }

  console.log('\n=== RECOMMENDATIONS ===');
  console.log('1. Remove CANARY credentials from .env.test');
  console.log('2. Replace with actual test credentials IF application needs them');
  console.log('3. If app doesnt use these, remove from .env.test entirely');
  console.log('4. Add validation in app.js for required environment variables');
  console.log('5. Consider using a .env.example file with placeholder values');

} catch (error) {
  console.error(`Analysis failed: ${error.message}`);
  process.exit(1);
}

// Safe connectivity verification without using credentials
// Only tests basic network connectivity and service availability

const https = require('https');
const dns = require('dns');
const { promisify } = require('util');

const dnsLookup = promisify(dns.lookup);

async function testBasicConnectivity() {
  console.log('=== Basic Connectivity Verification ===\n');
  console.log('Testing network connectivity WITHOUT using credentials...\n');

  const tests = [
    {
      name: 'Internet Connection',
      test: () => new Promise((resolve) => {
        const req = https.get('https://www.google.com', { timeout: 5000 }, (res) => {
          resolve({ success: true, message: `HTTP ${res.statusCode}` });
        });

        req.on('error', (error) => {
          resolve({ success: false, message: error.message });
        });

        req.on('timeout', () => {
          req.destroy();
          resolve({ success: false, message: 'Timeout after 5s' });
        });
      })
    },
    {
      name: 'DNS Resolution',
      test: async () => {
        try {
          const address = await dnsLookup('google.com');
          return { success: true, message: `Resolves to ${address.address}` };
        } catch (error) {
          return { success: false, message: error.message };
        }
      }
    }
  ];

  // Run tests
  for (const test of tests) {
    process.stdout.write(`Testing ${test.name}... `);
    try {
      const result = await test.test();
      console.log(result.success ? '✓' : '✗');
      if (!result.success) {
        console.log(`  Error: ${result.message}`);
      }
    } catch (error) {
      console.log('✗');
      console.log(`  Unexpected error: ${error.message}`);
    }
  }
}

