function testApiConnection(url, apiKey, serviceName) {
  const parsedUrl = new URL(url);
  const options = {
    hostname: parsedUrl.hostname,
    port: parsedUrl.port || 443,
    path: parsedUrl.pathname,
    method: 'GET',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${apiKey}`,
      'User-Agent': 'Credential-Verifier/1.0'
    },
    timeout: 10000
  };

  const req = https.request(options, (res) => {
    console.log(`   - ${serviceName} API Response Status: ${res.statusCode}`);
    if (res.statusCode === 401 || res.statusCode === 403) {
      console.log(`   - ❌ ${serviceName} API: Invalid credentials (expected for test values)`);
    } else if (res.statusCode === 200) {
      console.log(`   - ⚠️  ${serviceName} API: Credentials might be valid (unexpected for test values)`);
    } else {
      console.log(`   - ⚠️  ${serviceName} API: Unexpected response code ${res.statusCode}`);
    }
    res.on('data', () => {}); // Drain response
  });

  req.on('error', (error) => {
    if (error.code === 'ETIMEDOUT' || error.code === 'ECONNREFUSED') {
      console.log(`   - ❌ ${serviceName} API: Connection failed (network/connectivity issue)`);
    } else if (error.code === 'ENOTFOUND') {
      console.log(`   - ❌ ${serviceName} API: Host not found`);
    } else {
      console.log(`   - ❌ ${serviceName} API Error: ${error.message}`);
    }
  });

  req.on('timeout', () => {
    req.destroy();
    console.log(`   - ❌ ${serviceName} API: Request timeout`);
  });

  req.end();
}

