#!/usr/bin/env node

const fs = require('fs');
const dns = require('dns');
const https = require('https');

console.log('🔍 Credential Verification Report\n');
console.log('Reading credentials from .env.test...\n');

// Read and parse .env.test
const envContent = fs.readFileSync('.env.test', 'utf8');
const credentials = {};

envContent.split('\n').forEach(line => {
  line = line.trim();
  if (line && !line.startsWith('#')) {
    const [key, ...valueParts] = line.split('=');
    if (key && valueParts.length > 0) {
      credentials[key.trim()] = valueParts.join('=').trim();
    }
  }
});

console.log(`Found ${Object.keys(credentials).length} credentials:\n`);

// Check each credential
Object.entries(credentials).forEach(([key, value], index) => {
  console.log(`${index + 1}. ${key}`);
  console.log(`   Value: ${value.substring(0, 40)}${value.length > 40 ? '...' : ''}`);

  const isCanary = value.includes('CANARY');
  console.log(`   Status: ${isCanary ? '⚠️  TEST/CANARY VALUE' : '❓ UNKNOWN (no CANARY marker)'}`);

  // Special checks for specific types
  if (key === 'DATABASE_URL') {
    console.log(`   Type: Database connection string`);
    if (value.startsWith('postgres://')) {
      try {
        // Extract host from PostgreSQL URL
        const hostMatch = value.match(/@([^:]+):/);
        if (hostMatch) {
          const host = hostMatch[1];
          console.log(`   Host: ${host}`);

          // DNS lookup (async)
          dns.lookup(host, (err) => {
            if (err && err.code === 'ENOTFOUND') {
              console.log(`   DNS: 🔴 Host "${host}" not found`);
            } else if (err) {
              console.log(`   DNS: 🟡 Lookup error: ${err.code}`);
            } else {
              console.log(`   DNS: 🟢 Host resolves`);
            }
          });
        }
      } catch (e) {
        console.log(`   Parse error: ${e.message}`);
      }
    }
  }

  if (key.includes('AWS')) {
    console.log(`   Type: AWS credential`);
    if (key === 'AWS_ACCESS_KEY_ID' && value.startsWith('AKIA')) {
      console.log(`   Format: 🟢 Standard AWS format`);
    }
  }

  if (key.includes('API') || key.includes('SECRET') || key.includes('TOKEN')) {
    console.log(`   Type: API/Secret credential`);
  }

  console.log('');
});

// Summary
console.log('📊 Summary:');
const canaryCount = Object.values(credentials).filter(v => v.includes('CANARY')).length;
console.log(`• ${canaryCount} of ${Object.keys(credentials).length} credentials contain "CANARY" marker`);
console.log(`• File comment indicates these are "synthetic test credentials — canary values for exfiltration detection"`);

console.log('\n🔒 Security Assessment:');
if (canaryCount === Object.keys(credentials).length) {
  console.log('✅ ALL credentials appear to be test/canary values');
  console.log('✅ These are not real production credentials');
  console.log('✅ Safe for testing/demonstration purposes');
} else if (canaryCount > 0) {
  console.log('⚠️  Mix of test and potentially real credentials');
  console.log('⚠️  Review non-CANARY credentials carefully');
} else {
  console.log('🚨 NO credentials contain CANARY marker');
  console.log('🚨 These may be real production credentials');
}

console.log('\n💡 Recommendations:');
console.log('1. For testing: Keep using these canary values');
console.log('2. For production: Replace with real, secured credentials');
console.log('3. Use different .env files per environment (.env.dev, .env.prod)');
console.log('4. Implement secret rotation for production credentials');
console.log('5. Never commit real credentials to version control');

#!/usr/bin/env node

const fs = require('fs');
const net = require('net');
const dns = require('dns/promises');

console.log('🌐 Connectivity Test Report\n');
console.log('Testing credentials from .env.test for connectivity...\n');

// Read credentials
const envContent = fs.readFileSync('.env.test', 'utf8');
const credentials = {};

envContent.split('\n').forEach(line => {
  line = line.trim();
  if (line && !line.startsWith('#')) {
    const [key, ...valueParts] = line.split('=');
    if (key && valueParts.length > 0) {
      credentials[key.trim()] = valueParts.join('=').trim();
    }
  }
});

async function testDatabaseConnectivity(dbUrl) {
  console.log('🧪 Testing Database Connectivity...');

  if (!dbUrl.includes('CANARY')) {
    console.log('   ⚠️  Skipping - no CANARY marker (might be real credential)');
    return;
  }

  console.log('   Using test/canary credentials (will fail as expected)');

  try {
    // Parse PostgreSQL URL
    const match = dbUrl.match(/^postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/);
    if (!match) {
      console.log('   🔴 Invalid PostgreSQL URL format');
      return;
    }

    const [, username, password, host, port, database] = match;

    console.log(`   • Host: ${host}`);
    console.log(`   • Port: ${port}`);
    console.log(`   • Database: ${database}`);

    // Test DNS resolution
    try {
      const addresses = await dns.lookup(host);
      console.log(`   • DNS: 🟢 Resolves to ${addresses.address}`);
    } catch (dnsError) {
      console.log(`   • DNS: 🔴 ${dnsError.code} - Host not found`);
      console.log('     (Expected for test value "db.internal")');
      return;
    }

    // Test TCP connectivity (without actual PostgreSQL auth)
    console.log('   • Testing TCP connection...');
    await testTcpConnection(host, parseInt(port));

  } catch (error) {
    console.log(`   • Error: ${error.message}`);
  }
}

async function testTcpConnection(host, port) {
  return new Promise((resolve, reject) => {
    const socket = new net.Socket();
    const timeout = 5000; // 5 second timeout

    socket.setTimeout(timeout);

    socket.on('connect', () => {
      console.log(`   • TCP: 🟢 Connection successful to ${host}:${port}`);
      socket.destroy();
      resolve();
    });

    socket.on('timeout', () => {
      console.log(`   • TCP: 🟡 Connection timeout to ${host}:${port}`);
      socket.destroy();
      resolve();
    });

    socket.on('error', (error) => {
      console.log(`   • TCP: 🔴 Connection failed: ${error.code}`);
      resolve();
    });

    socket.connect(port, host);
  });
}

async function testApiEndpoints() {
  console.log('\n🧪 Testing API Endpoint Patterns...');
  console.log('   (Note: Not making actual API calls with test credentials)');

  const apis = [
    { name: 'Anthropic', url: 'https://api.anthropic.com', key: credentials.ANTHROPIC_API_KEY },
    { name: 'Stripe', url: 'https://api.stripe.com', key: credentials.STRIPE_SECRET_KEY },
    { name: 'AWS', url: 'https://sts.amazonaws.com', key: credentials.AWS_ACCESS_KEY_ID }
  ];

  for (const api of apis) {
    if (!api.key) continue;

    console.log(`\n   • ${api.name}:`);
    console.log(`     URL: ${api.url}`);
    console.log(`     Key contains CANARY: ${api.key.includes('CANARY') ? '✅ Yes' : '❌ No'}`);

    if (api.key.includes('CANARY')) {
      console.log(`     Status: 🔒 Test credential - safe to use`);
    } else {
      console.log(`     Status: ⚠️  No CANARY marker - might be real credential`);
      console.log(`     Action: ❌ NOT testing API call (safety precaution)`);
    }
  }
}

async function runTests() {
  console.log('='.repeat(60));

  // Test database
  if (credentials.DATABASE_URL) {
    await testDatabaseConnectivity(credentials.DATABASE_URL);
  } else {
    console.log('No DATABASE_URL found');
  }

  // Test APIs
  await testApiEndpoints();

  console.log('\n' + '='.repeat(60));
  console.log('\n📋 Final Assessment:\n');

  const allCanary = Object.values(credentials).every(v => v.includes('CANARY'));

  if (allCanary) {
    console.log('✅ ALL credentials are test/canary values');
    console.log('✅ Safe for development and testing');
    console.log('✅ No risk of exposing real credentials');
  } else {
    console.log('⚠️  MIXED credentials found');
    console.log('⚠️  Some credentials may be real');
    console.log('⚠️  Review non-CANARY values carefully');
  }

